/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230228-9","meetingId":"r05-cm02","date":"2023年2月28日","dateIso":"2023-02-28","committee":"文教委員会","time":"午前１０時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件整理しています。","topics":[{"id":"topic-01","title":"令和４年度品川区教育委員会事務事業の点検および評価の報告書","agenda":"令和４年度品川区教育委員会事務事業の点検および評価の報告書","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ページ数の順番で幾つかお伺いしたいのですが、まず５ページの学校用務ですが、民間委託によりそうなったという意味なのでしょうか。成果というのはどんな感じで捉えているのかというのと、あと、生徒の評判とかはどんな感じなのかというのを伺いたいと思います。","respondent":"宮尾庶務課長、中谷指導課長","answer":"私から、学校用務業務委託に関する部分につきましてのご質問にお答えします。こちらは委員のお見込みのとおり、委託を導入した後の結果として、常に複数人の人員が配置できているという意味です。 要は、いろいろと準備をして、緊張して臨んで、本当にオールイングリッシュで、１対１で会話をするという中で、適度な時間かなと考えています。子どもたちの生の声としましては、やはり１対１で会話をするということに…","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"１４ページの研修ですが、どういう方がこの人権同和教育研修の講師を務めているのか、お聞かせほしいと求めました。それとも都の補助か何かが出ているのですかというのと、まだ１年たっていないのですが、現時点ではどのように捉えていらっしゃるのか伺います。","respondent":"矢部教育総合支援センター長","answer":"特段Ａさん、Ｂさんと、配置児童がきちっと決まっているわけではないので、フレキシブルな対応が可能になったということが一番多かったです。学級担任との連携が強化され児童の支援に生かすことができた…","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かれば、２３区でこういうのを配置しているところというのは、ほとんど配置しているのでしょうか。そこら辺を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"詳細はきちんとお調べいたしますが、たしか、ほかの都の中の状況は、私ども、まだつかんでおりません。補助金については、今、間違えるといけませんので、お調べして、きちんとお伝えしたいと思います。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"その子たちへの配慮の部分を本当に気をつけていただきたいというところを強く求めたいのですが、今の現状についてお知らせをほしいと求めました。現状はどうでしょうかというところと、教育委員をはじめ、この有識者とはどういった方たちなのでしょうかというところをお知らせください。","respondent":"宮尾庶務課長、森学校施設担当課長、勝亦学務課長、中谷指導課長、矢部教育総合支援センター長","answer":"私から、５ページの学校用務業務委託に関するご質問にお答えをさせていただければと思います。大きさを変えるとか… 計画を持たないのかですけれども、計画は、毎年状況が変わってまいりますので、その都度対応していく。就学人口、老朽度… 生ごみリサイクルです。学校の給食調理等で出ます生ごみにつきましては、回収を事業者のほうでいたしまして… 逆にその方の国の文化を日本人のお子さんたちが学ぶ、大変貴重な機会になっているなと考えています。そういった意味で…","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"地域の学校で一緒に学びたいと言っている知的も含めた障害のある子どもたちの要望というのは、お願いしたいなというところを訴えたいと思います。このまちづくりでこの学校で間に合うのかなと、ぜひ区教育委員会としての計画をきちんと持っていただきたいなということは、強く求めたいと思います。","respondent":"矢部教育総合支援センター長、森学校施設担当課長、中谷指導課長","answer":"担任を中心に全体的に支援はしますけれども、学習支援員と介助員という支援がございまして、できる限りの支援はこれからも努めてまいりたいと考えています。 まちづくりのほうとはしっかり連携を取ってやっていきたいと考えています。常にスタートラインにもう一度立ち返って、一から検討していくためにも… レガシーのほうですけれども、その関係づくりをしっかり見守っていけるような、学校の教育活動を展開していきたいと考えています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"１点だけ。これは要望でとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]},{"id":"topic-02","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"３５人学級になっていますが、対応可能なものとして設計されているのか、確認をさせてください。伺いたいと思います。","respondent":"森学校施設担当課長","answer":"基本、鈴ヶ森小学校と源氏前小学校ですけれども、３５人学級で大丈夫かということで、大丈夫なように設計しております。設計に進んでいこうという考えですので、何年か前からはそのように、まず測量から始めて設計に移っていくというスキームで行っております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"３０人学級にするということも必要だと考えているのですが、そこら辺はどう考えていらっしゃるのか、それが１つです。それはいいことなのですが、三木小学校が選定されなかったのは、何か理由があるのか伺いたいと思います。","respondent":"森学校施設担当課長","answer":"中学校の３５人学級というところですけれども、国等から指針が出次第、そのように対応していきたいと考えています。今は特にそこまでは考えていませんけれども、出次第、対応はするように検討はしていきたいと考えております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"三木小学校のほうも、地域の方のお話をしっかり丁寧に伺いながら、ぜひ具体化を進めていただきたいと要望します。この制度はどうなのかなと思ってしまうのですが、そうした動きについて区教育委員会としてはどう考えているのか、最後に伺いたいと思います。","respondent":"森学校施設担当課長","answer":"そのまま、できる限り同じような学習環境を維持していきたいと考えながら、改築を進めていきたいと考えています。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"基礎的なところで伺ってしまうのかもしれないのですが、地域からは、人工芝生化は嫌だという意見とかも生活者ネットワークには届くのです。そういった声を聞いて改築に反映がされるその時期というのは、どの段階なのかというのを伺いたいと思います。","respondent":"森学校施設担当課長","answer":"近隣の方、町会長の方々をお呼びして、ご意見を賜るという会を設けてあります。皆様とつくる学校というのがコンセプトですので、地域に根差した学校づくりのために、ご意見を反映させながら設計していくということをしております。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜこういう質問をするかというと、どうしてこんなに子どもたちを分けてしまうのだというご意見とか、やはり地域からは聞こえてくるのです。もう全てが決まってからお知らせをされているような気がするというような地域の方たちの声があるので、今こういった話をしております。","respondent":"森学校施設担当課長","answer":"建設準備懇談会は、学校とよく調整いたしまして、来ていただく方を選定しております。行っている時期ですけれども、基本的には平日の夜、お集まりいただけるような時間帯を設定して、懇談会を開催しております。","id":"exchange-011"},{"speaker":"田中委員","kind":"確認","question":"参加される方は限定されているということですか、今のご答弁だと。そこを確認させてください。","respondent":"森学校施設担当課長","answer":"説明会については不特定多数で、ある程度メンバーは確定した上で、繰り返して開催しています。複数回開催しています。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"対象をお知らせいただきたいのと、この基本設計の前の段階、それとも実施設計の前の段階なのか。説明会は対象が広いということだったのですが、そのときの声は反映がされるのかというところを確認したいのですが、いかがでしょう。","respondent":"森学校施設担当課長","answer":"計画の段階で説明会を行うことはあまりございませんので、説明ができない状況になりますので、説明会を行っております。〔「対象は」と呼ぶ者あり〕 対象は、懇談会についてはメンバーがある程度決まっております。その学校に応じて、どの町会であったりというのは違うのですけれども、懇談会のメンバーについては選定しております。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"だから、そういった方たちの声が反映されないのかなというところを伺いたくて、大体こういった方が対象ですというのを教えてほしいと求めました。自分たちの声が届かないのだろうという状況になってしまうので、ぜひそこは改善をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"説明会のときに我々の意見が通らないのではないかということなのですが、当然、その辺は見直したりすることもあるかと考えています。皆様が喜んで使っていただけるようなことを前提にして、今後も各所と連携し、設計してまいります。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"やはり子どもたちにとっての学校というのが一番だと思うので、その子どもたちの声をきちんとお聞きほしいと求めました。そういった、やはりそこを使っている子どもたちの声というのは聞き取る環境を整えてほしいと強く要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問","question":"１件、お伺いしたかったのが、今、３５人学級ですとか、またその地域の事情とかといって、クラス数をどうするか。もう少し付加してもいいわけだけれども、そうもいかない理由があると思うのだけれども、少しその辺を教えてほしいのですが。","respondent":"森学校施設担当課長","answer":"保護者、児童・生徒のご意見ですが、学校のほうからきちんと聞いておりますので、意見は吸い上げているということになっております。国庫補助金についてはそのような形ですけれども、学区内の児童・生徒は必ず通えるように、しっかり設計していくということは行っております。","id":"exchange-016"},{"speaker":"渡部委員","kind":"確認","question":"ちょうど今改築をやっているところなどは先が見えないところがある中で、相当区費を突っ込んで改築に当たっているのだということの確認がしたかった。本当に１５年ぐらい前にやっていたものに対して、品川区の独自会計が相当ここに充てられているという認識でいいのかどうかだけ、確認させてください。","respondent":"森学校施設担当課長","answer":"そのとおりです。〔「分かりました」と呼ぶ者あり〕","id":"exchange-017"},{"speaker":"江野下委員","kind":"質問・要望","question":"少し見た目で教えていただきたいのですけれども、茶色のものというか、よくあるトラックみたいなですかね。経緯とかがあれば説明を求めました。","respondent":"森学校施設担当課長","answer":"この色がついているところも全て人工芝で検討しておりまして、今の予定ですと色をつけないで、全部緑でやりましょうと話は進んでおります。最初のイメージですので、実際とは変わってくるような形になります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもの直接の意見を聞こうという流れになっているわけですから、やはりあえて、子どもの新たな発見とか気づきというのは必ずあると思うのです。ですから、そういう直接子どもを検討に入れて意見を聞くような仕組みというのは、少し研究していただきたいなという意見を言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"工夫が行われているというのは分かりましたが、さらにそういった方向を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"松澤副委員長","kind":"質問","question":"安藤委員のお話と同じ感覚で、この学校の改築の選択の中で、これをぱっと１面を見ると、荏原が２、品川が５ですよね。何て言えばいいでしょうか、視点の中にあってもいいのではないかなと思っていまして、そこら辺を説明を求めました。","respondent":"森学校施設担当課長","answer":"まさに様々な要因が絡んでまいりますので、計画的に建て替えるのは事実ですけれども、学校というのを決め打ちすることは非常に難しい状況です。老朽度もありますし、地域バランスもありますが、そういうのを様々勘案しながら選定してまいりたいと考えています。","id":"exchange-021"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"もう、では木の学校にしようかみたいな盛り上がりも見せているというのをお聞きしますので、いろいろやっていただきたいと考えています。これもまた地域活動課とのバランスもあるから要望だけしますけれども、またそういったバランスもしっかりと鑑みてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-03","title":"区立学校における一足制の導入","agenda":"区立学校における一足制の導入","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"港区でも何か２６校中２４校でということで、学校ごとに導入するかどうかを何か検討した上で、決めるということなのでしょうか。伺いたいと思います。","respondent":"森学校施設担当課長","answer":"学校ごとに考えるのかどうかというお話ですけれども、校庭の種類が大きく影響しておりまして、一足制の導入は非常に難しいと考えています。港区の２校、砂が中に入ってしまうので、そういうところで一足制導入は非常に困難であると考えています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"いかがでしょうかということと、区教育委員会としてなぜこれを導入したいのかというのをもう少し、分からなかったのでお伺いします。","respondent":"森学校施設担当課長","answer":"ほかの所要室を広くすることが可能になってまいりますので、様々な要因から一足制を導入できないかというところからスタートしてまいりました。校庭の人工芝化も進んできておりますので、靴が汚れるということも減っており…","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"子どもの意見をどういうふうに取り入れて検討を徹底していくかというのを伺ったので、お伺いします。２３区中６区で導入実績ありというのですが、これどういう意味なのかなというか、そこら辺が分からなかったのでお伺いします。","respondent":"森学校施設担当課長","answer":"導入している他区の件につきましては、今、実際に一足制を導入している区です。校数としては、多いところや、少ないところ、いろいろあるのですけれども、６区については、現在も一足制を導入している学校があるです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"聞き取れなかったので確認したいのですが、それは体育館の話ですか、それとも廊下の話ですか。どうも、やはりそこを利用する子どもたちにきちんと意見を聞いてほしいということを求めたいと思うのですが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"目的について説明が足りなかったというのは、あったかもしれません。マイクロプラスチックの問題ができる限り発生しないように対応はしておりますし、メーカーのほうでも材質の変更、工法の変更等を行っておりますので。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"そこだけ確認したかったのと、人工芝によって、まさか地域のそういう花火とかができなくなると思っていなかったのですね。子どもたちもみんなで、そのメリット・デメリットをきちんと話し合う場というのを求めたいのですが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"それから、やり方についていろいろご説明したり、こちらである程度準備したりすることも可能ではないかなと考えています。そういう問題が起きないように、お祭りも開催ができるように、いろいろ検討しながら、校庭の種類については設定していきたいと考えています。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"人工芝を導入しているところでないと一足制はできないということでいいのですよねという確認と、そういう機会を設けていただきたいということです。今までの人工芝にしてきた学校の事例とかも踏まえて、きちんと話合いをしていただきたいということを求めたのですが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"人工芝に限らず、ご意見を賜りながら、校庭の種類については検討していきたいと考えています。","id":"exchange-028"},{"speaker":"渡部委員","kind":"意見","question":"もうそのまま継続してやっているのかというのを聞かせてほしいのと、では品川区は、今もう土のグラウンドのところはやらないわけですよね。要するにどういうタイミングでやっていくよというのが、今の段階である程度あるなら、お聞かせいただけますかとの意見を述べました。","respondent":"森学校施設担当課長","answer":"鮫浜小学校は、現在そのままモデル実施ということで、一足制を導入した状態になっております。そういうのを踏まえまして、それは我々が考えているところなのですが、少しでも多く導入することが可能にはしていきたいとは考えております。","id":"exchange-029"},{"speaker":"渡部委員","kind":"確認","question":"ありがとうございました。確認ですが、その２２校には一斉にどーんと学校に、そういうふうに移行していこうという考え方でよかったのですよねという確認だけ。","respondent":"森学校施設担当課長","answer":"一斉にやるというのもあるのですけれども、なかなか、今ご議論があるように、やはり学校のほうで、「えっ、上履き使わないのですか」となりますので、１校ずつぐらいでも丁寧に増やしていって、実証を重ねていきながら、浸透していくことができればなと考えております。","id":"exchange-030"},{"speaker":"渡部委員","kind":"意見","question":"学校を決めて徐々に行くのだよというようなことを、町場に下ろしていけばいいですよねと、そういう意味合いでした。すみませんとの意見を述べました。","respondent":"森学校施設担当課長","answer":"まさにそのとおりです。","id":"exchange-031"},{"speaker":"江野下委員","kind":"質問","question":"これ、密を避けるというところから話が動き出したというのをお聞きしましたけれども、その前から、地域の学校では一足制の話を私は伺っておりました。何かもう少し違うアイデアで、子どもたちのためにそこの部分も生かしてあげられるのではないかなと思いますが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"まさに委員のおっしゃるとおりでございまして、できれば昇降口の部分を違うスペースに転換することができればなと考えております。まだまだ計画変更の余地がありますので、そういうところについては、児童・生徒のためになるような空間をつくっていきたいと考えております。","id":"exchange-032"},{"speaker":"松澤副委員長","kind":"質問","question":"やはり何というのですか、きれいだから、そんなの汚れないに決まっているじゃない。要は１校１校、こうやって丁寧にやっていっていますよという部分の何か周知みたいなものというのはする予定があるのか、それだけ説明を求めました。","respondent":"森学校施設担当課長","answer":"今後も実証を重ねてまいる予定ですので、来年度末頃に、文教委員会で、報告ができればと考えてはいます。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"しないかは判断できるというところを確認したいのが１点と、１月から後地小学校で実施されたということだったのですが、説明はどうされたのか。それで、子どもだったり保護者だったりからの反応というか、伺いたいと思います。","respondent":"森学校施設担当課長","answer":"一足制の導入につきましては１校１校丁寧に対応していくということで、一斉にやるとは考えておりません。年末に教育委員会事務局からも担当が参りまして、そういうふうにやっていきますというご説明は、学校のほうからも我々からもさせていただきました。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"各学校で進めていくではなくて、もしモデルでやってみて、やはり少しあれだったなというときには、一足制の導入は中止もできるということですよね。各学校で判断はできるというところを確認したいのですが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"嫌ですということであれば、当然元に戻す、上履きに戻すということも可能と考えております。決して区で強制してということは考えておりません。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"どういう手続きを経て、いつになるのか、今どのように考えていらっしゃるのか。そういう精神というのは大事だというのはこどもの権利条約でもありますし、そういった点で聞いているのですが、いかがか尋ねました。","respondent":"森学校施設担当課長","answer":"本格実施については検討中ですけれども、教職員もそうですけれども、実際やってみてどうだったのかというのは聞いてみたいと考えています。好きな靴が履ける、運動もしやすいというのがありますので、子どもたちにとっても一足制はいいのではないかなと考えています。","id":"exchange-036"},{"speaker":"安藤委員","kind":"意見","question":"子どもたちの意見はすごく大事だと思うので、ぜひそういう感じでお願いしたいと思いますとの意見を述べました。","respondent":"中島教育長","answer":"そこにも出ておりましたし、様々な形で教員の意見なども吸い上げて、そこでモデル実施という判断を進めていく。そこは、やはり学校長、そしてＣＳの中で、どういう形で実施ができるかということを十分判断していただいて進めていく。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"要望です。利用するのは、一足制になるのは子どもなので、子どもがメインなので、子どものための学校として、そこは強く求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"幾つかお伺いしたいのですが、同じ２位とか３位とか１位とか、その中でも複数いらっしゃるではないですか。中学校は２月末ということだったのですが、それはどういう意味なのかなというか、待機期限が過ぎたらどうなるのかというのをお伺いしたいです。","respondent":"勝亦学務課長","answer":"その抽選の結果で、区分の中で順位、１位、２位、３位というのは決まってまいります。学校選択の待機というものがなくなりまして、希望のところに入学できない方は、事前に就学指定をした学校へ入学をする予定となります。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"抽選が４３４名の方になったのですが、これは、今年はトータル何人いらっしゃったのでしょうか。伺いたいと思います。","respondent":"勝亦学務課長","answer":"今、小学校、中学校とも集計をしているところでございまして、具体的な数字については、こちらでは今、数字はない状況です。入学の可能な枠がある中での学校選択ということで、なかなか全ての方のご希望をかなえるというのは、難しい状況にあろうかと考えています。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"私は学校選択制の見直しというのを質問させていただいているのですが、時代やニーズに応じて効果的に実施していくという答弁もされています。これだけ大きなデメリットを背負ってまで選択制を続ける必要性というのは、もはやないのではないかと思うのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"従来の教育改革プラン２１から今の品川教育ルネサンスの中で、そういった選択の幅を持たせるといったようなメリット、効果があると考えています。そういった意味で、デメリットの部分ではなく、そういったメリットの中で…","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそも子どもが地域と関わる中心になるのが学校なわけですから、義務教育学校も子どもたちのほうからつくってと言っていたわけではないですから。メリットでもないし、デメリットのほうが大きいということで、重ねて選択制は中止を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"今回はそれ以外にはなかったのかというところを伺いたいのと、あと、この無抽選の数とがとても開きがあるのは大丈夫なのかなと。どういう状況を指しているのかというのを確認したいのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"こちらの学校選択の抽選にエントリーができないという形での説明をしていますので、ここには出てきていないという状況です。こちらの無抽選の中には、先ほどご説明させていただいたとおり、こちらの数字は最終的には変わってくるのかなと捉えてあります。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"中学校・義務教育学校については４３４名の方が待機ということだったのですけれども、では、３割程度の方が私立を希望されるということで、大体、この４３４名の待機の方はほとんど解消ができるということを、区教育委員会としては考えているのかというところを伺いたいのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"昨年度につきましては、最終的に繰上げができなかった中学校につきましては３校ございまして、合計の人数としましては３８人という状況です。今年度につきましては、今日終了いたしまして、これから集計に入るという状況です。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっとまとまらないのですが、子どもたちの不安感を取り除くような、そういった施策というのも考えていただきたいということを思います。今度、そういった声もあるので、ぜひなるべく早い段階での子どもや保護者への周知ということはしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"渡部委員","kind":"確認","question":"ですから、そこには、たしかあの当時でも、３年間か何かの明確な猶予期間を設けていたはずだよね。この制度がある以上、抽選を申し込んでしまった以上しようがないのだよねという確認だけさせてください。","respondent":"勝亦学務課長","answer":"この繰上げの時期ですけれども、今、私立の学校の入試の結果についてご報告をいただきまして、それを一つ一つ確認を取った上で繰上げをしていくという作業をしてございまして、なかなかこれを大きく前倒すというのは、日程的には厳しいのかなとは考えてあります。","id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"例年３月何日ぐらいなのかというのを、もしお伺いできればお伺いしたいのと、分かれば教えてください。締切り後です。","respondent":"勝亦学務課長","answer":"中学校のほうが２月末という形になっているのですけれども、指定校変更については、大体時期的には１００件程度上がってくるかなと考えています。その中でも多くは住所変更で、必ず手続き的には対応しておりまして…","id":"exchange-047"}]},{"id":"topic-04","title":"令和３年度品川区区立学校における体罰等の実態把握","agenda":"令和３年度品川区区立学校における体罰等の実態把握","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２つお伺いしたいのですが、区教育委員会としてはどういうふうに考えていらっしゃるのか、改めて伺いたいというのが１つです。何か去年から今年、変わったことがあるのかというのを伺いたいと思います。","respondent":"中谷指導課長","answer":"これは、法律にもきちんと根拠づけられておりますし、東京都においては、ガイドラインに規定されているものであると認識しています。今までは通常教室で、都の教育委員会の指示に基づきまして…","id":"exchange-048"},{"speaker":"安藤委員","kind":"確認","question":"確認ですが、こういったことも含めてなくしていきたいと、そういうお考えなのでしょうか。この２ページの（１）で言うところのこの分類がありますが、上からどこまでを根絶しようと考えているのか、お伺いしたいと思います。","respondent":"中谷指導課長","answer":"開始当時は、報告の件数が１００件を超えているような状況が、当初ございました。昔作られたものでありますが、変わらずやはり理念としては大事であると捉えて、こちらを活用していきたいなと考えています。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもの権利に関する啓発というのですか、子どもの権利条約に定められていますが、そういう啓発というのはまだまだ足りないと思うのです。そういったところもぜひ強化をしていただきたいと思うのですが、強化が必要だと思うのですが、最後にお考えを伺いたいと思います。","respondent":"中谷指導課長","answer":"これらをしっかり理解している教職員が適切に指導に当たるということは、とても大事であると考えています。そこをしっかり、これは教職員に必ず配られるものになっておりますので、こういったものを活用するということをやっていきたいと考えております。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"これまで求めてきたのですけれども、そこの部分の状況について伺いたのと、その事例について伺いたいのと。その部分についても伺いたいです。","respondent":"中谷指導課長","answer":"もちろんこれはこれで、必要な指導を子どもたちに対して行うといったことで対応しています。その当該のお子さんと教員の話が一致していて、そのようなことはなかったということで、確認するようなケースを指しています。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"こういった調査をしますということをしっかり１枚の通知で出しているところと、そういったことを求めたいと思うのですが、いかがでしょうか。いかがでしょうかというのと、この体罰の中に、子どもへの性暴力とかも含まれるのかというところを確認させてください。","respondent":"中谷指導課長","answer":"こちらも東京都の教育委員会の方針に基づきまして、必ず事前に保護者の方に、こういった調査を行うということをお伝えすることになっております。改訂点も含めまして、しっかりこれを読んだ上で生徒指導に当たるというところを…","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"私も都の教育委員会ともやり取りをして伺ったところ、改善を求めていただきたいということは、要望しておきます。大人も共に学ぶ機会も必要だと思うのですが、どのように区教育委員会としては考えているのかも伺いたいと思います。","respondent":"中谷指導課長","answer":"アンケートのやり方につきましては、今後検討していきたいと考えています。リーフレットの考え方も同様になりまして、こちらも都教育委員会の周知の指示があったところで、速やかにご案内をしたいと考えています。","id":"exchange-053"},{"speaker":"渡部委員","kind":"確認","question":"これ、令和３年度は結局、東京都のほうで服務事故の報告が上がったのは、品川区の教員では１件という確認でいいのですか。それとも、この「不適切な」というのも、カテゴライズされている中で、体罰に関わるところの中では、そっちも当てはまってしまったりするのか尋ねました。","respondent":"中谷指導課長","answer":"やってはいけないものが、先ほども申し上げたように体罰と不適切な行為ということで、こちらに関しまして、今、ご案内しているとおりの件数を報告しているというところになります。","id":"exchange-054"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"田中委員","kind":"質問","question":"では、区長部局が検討し、こういった項目でいかがですかといったアンケートの案を基に、区教育委員会が子どもに分かりやすいものを作っていくのか。小学校の１年生から中学校３年生までを同じアンケートで行うのか、そうではないのかとか、そういった内容についてもお知らせください。","respondent":"勝亦学務課長","answer":"項目、対象、それから、そういった伝え方につきましても、今後、区長部局と連携をしながら検討していくと考えています。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"連携をしながらのその連携の取り方を今伺っているのですが、区長部局からの要望を聞き取ってアンケートを作成するのか、お知らせいただけたらと思うのですが。","respondent":"勝亦学務課長","answer":"区民アンケートにつきましては、区長部局において、まず今後検討ということで考えていると理解しています。詳細につきましては、今後、連携の中で決定してまいると考えています。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問","question":"伺いたいのですが、また区長部局からはその時期というものも示されているのか。詳細について、今分かる範囲でお知らせいただけたらと思うのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"そういった調整の方法につきまして、具体的なものもこれからという形になるかと考えています。","id":"exchange-057"},{"speaker":"田中委員","kind":"質問","question":"では、まだ全然区長部局からは、区教育委員会に示されていないということでいいか尋ねました。","respondent":"勝亦学務課長","answer":"具体的なものは知らされていないというところです。","id":"exchange-058"}]},{"id":"topic-06","title":"第２期品川区子ども・若者計画パブリックコメントの結果","agenda":"第２期品川区子ども・若者計画パブリックコメントの結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"前回質疑で、第１期のときのパブリックコメントが８人、３３件という説明だったと思うのですが、今回は、人数と意見ともに結構増えたのかなと思うのですが、その要因とか、あとは、意見を出してもらうために何か工夫したことなどがあれば、教えてほしいと求めました。","respondent":"廣田子ども育成課長","answer":"１１月の委員会でもいろいろご意見をいただきまして、こういうものを今考えていますというところを行ける限りで説明して、前回よりも周知には心がけたところです。","id":"exchange-059"},{"speaker":"若林委員","kind":"意見","question":"２ページの反映というところの（２）の「医療的ケア児を明記すべき」を反映させて下線部になったのですが、日本語としてちょっとどうかなというのが率直な感想なので、指摘をしますとの意見を述べました。","respondent":"廣田子ども育成課長","answer":"表記を最終的に少し見直すというところも考えていたので、ここはご指摘のとおりで、少し工夫をさせていただこうかと思います。失礼いたしました。","id":"exchange-060"}]},{"id":"topic-07","title":"すまいるスクールの利用者アンケート調査結果","agenda":"すまいるスクールの利用者アンケート調査結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"お考えがあれば伺いたいのと、どこかでクロスなども含めた結果の報告はあるのでしょうかというのと、伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"結果については、第三者評価については、努力義務ではありますが公表するようにとあるので、ホームページ等で出す予定となっております。いろいろなご要望があったので、それを今、分析しているという感じです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"何かそういうアンケート結果というのを前提に活用するというお考えはあるのかというのと、このアンケート結果というのを今後の事業展開に生かしていくというお考えなのか、そこだけ伺います。","respondent":"廣田子ども育成課長","answer":"区の職員と一丸となってやっておりますので、そこのすまいるスクールの質がどうかというところを見るためにやっています。多少の……、あるかもしれないのですが… 実施が可能なことかというところがあるので、やりたくてもやれないこともありますので、本当に品質管理のために使うという考えです。","id":"exchange-062"},{"speaker":"田中委員","kind":"確認","question":"たしか教室もそこまでできなくなってしまったのかなと思うので、そこが今、回復したのかどうかを確認させてください。今の子どもたちの利用状況、やはりまだ足りていない、教室とかもぱんぱんな状況が続いてしまっているのかというところを確認させてください。","respondent":"廣田子ども育成課長","answer":"支援児の方とか配慮が必要なお子さんが大変増えているので、少し寂しい思いをさせてしまっているところがあるということは、否めないと思います。少し新年度、例えば１年生は９８％ぐらい来ますので、どうするかというのは大きな課題となっています。","id":"exchange-063"}]},{"id":"topic-08","title":"区立児童相談所の竣工および今後のスケジュール","agenda":"区立児童相談所の竣工および今後のスケジュール","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"どうしても利用するお子さんへの心理的な影響を伴ってしまうのですが、そこら辺はどういうふうにケアをしていこうと考えているのか伺いたいのと、そこら辺についてはどんなお考えをお持ちなのかお伺いします。","respondent":"長谷川児童相談所移管担当課長","answer":"一つはハード的な部分での対応として、児童心理司が中心となって、子どもの心のケアというのを図っていきたいと思っています。学校長向けにまずは説明をして、実際に生徒さんたちにどのようにアプローチできるかというのは、まさに係内で検討しています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"１１月の報告のときに、それは採用はできたのでしょうかという現状を伺いたいのが１つと、この人員算出についても伺ったのですが。今、今定例会、総務委員会で定数条例も変わりましたが、その後、実際はどうなったのかというのをお聞かせほしいと求めました。","respondent":"長谷川児童相談所移管担当課長","answer":"多かったときをベースに人員に関しては算出しておりますので、実際、令和３年度は虐待対応件数がかなり減っているところになります。今後の虐待対応件数の推移によって、また注視していかなければなりませんが、現状は足りる計算ということになっています。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりかなり専門性が求められますし、ぜひそこら辺を重視して、専門的な方をどんどん採用してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問","question":"１点伺いたいのが、そういった工夫がどのようにされるのかといったところをまず伺いたいのと、その状況についても伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"それから、子どもの権利擁護に関しましては、今まさに検討中になっています。意見表明を支援する仕組みですとか、子どもたちを支える第三者の部分の役割ですとか、そういったところを今、整理をしている段階です。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"図面で示されている入り口は１か所あると思うのですが、緊張感を持っていないと、なかなか防ぐのは難しいのではないかなと思うのですね。もう今の時点でも、やはり子どもたちのＳＯＳというのはあるので、ぜひなるべく早く設置をしていただければということを強く求めたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"警備員ですけれども、特に資格要件とかを定めておりませんので、一般の方が来られることを想定しています。警備を委託する際に、そこら辺の危機管理の部分に関しては、しっかり情報共有を図っていきたいと考えています。","id":"exchange-068"}]},{"id":"topic-09","title":"第二期品川区子ども・子育て支援事業計画中間年度見直し改定版（素案）","agenda":"第二期品川区子ども・子育て支援事業計画中間年度見直し改定版（素案）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それとも減ると予想しているのか伺いたいのと、それとも減っていくと予想しているのか、改めて分かるようにお伺いしたいなというのが１つ。それと、このアンケート、意向調査をしていると思うのですが、この意向調査の調査対象というところがありますが、これは全員なのですかね。","respondent":"初貝保育教育運営担当課長","answer":"例えば１８ページですけれども、それにおいても少し、当初予定したよりも少なくなるです。今回はランダムに７,０００名の方を抽出いたしまして送付させていただいて、そのうちの３,７７０名の方からご回答いただいているという状況です。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこが少し分からなかったので教えていただきたいのと-、あと１月３１日に子ども・子育て会議をやられたということですが、委員からどんな意見が出たのかというのを伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"１つ目のご質問に関しましては、当初のこの計画を立てた当時より下振れしています。は、事業に対する周知方法をもう少し工夫してほしいとか、そういったような意見をいただいているところです。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"５月に申込みをやめてしまう人、１園だけ希望している人というのは何かいろいろ事情があるのでしょうが、去年でも２００人ぐらいいたのですね。そこら辺がちょっと分からないのですが、そこを踏まえてきちんと算出されますよということなのか、区の考えを伺いたいと思います。","respondent":"初貝保育教育運営担当課長、立木保育課長","answer":"幾つかご質問をいただきました。このたびの子ども・子育て支援事業計画自体が、先ほど資料１のところでフローをお示しさせていただいたのですけれども、量の見込みを出しています。 今回の子ども・子育て支援事業計画の量の見込みと確保方策に関しては、今、担当課長から説明があったとおり。細かく出しているものではなく、全体の利用意向の、利用したいかどうかというところで出しているものです。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"１０がゼロになったというところで満足するのではなく、ぜひ実態に即して、様々な理由でどうしても入れないという方々がまだいらっしゃるということを踏まえた上での事業計画にしていただきたいなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"少し勉強不足で教えていただきたいのですけれども、そもそものこの計画の見直しの目的と、この計画の活用方法と対象をお知らせいただけますか。","respondent":"初貝保育教育運営担当課長","answer":"冒頭も少しご説明させていただきましたけれども、あとは社会情勢の変化というところを、中間年度で一旦見直しをかけるというのを目的としております。活用の方法といたしましては、こちら、量の見込みというものを立てて、それに対する確保方策を立てています。","id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"２３ページから２５ページまでは各地域の内訳が出ているのですが、この見方について、マイナスが出ている地域というのはどう考えたら……。数だけを見て、なくしていくとか、そういう考え方はやめていただきたいということは、まず求めたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"この計画の説明ですけれども、２年で１回入れ替わるという形なのですけれども、意見をきちんと聞いていくという形で実施しています。きちんと確保方策が量の見込みを上回るという形で、量の見込みに対して確保がきちんと取れているというところなのですけれども、ただ。","id":"exchange-074"},{"speaker":"田中委員","kind":"意見","question":"確保方策というのは、具体的にどういう意味を指すのかというところをお知らせいただけますかとの意見を述べました。","respondent":"初貝保育教育運営担当課長","answer":"確保方策の具体的な中身に関しましては、ページで言うと２６ページ、２７ページに記載があります。それぞれ保育に関わるそういった施設の整備であったり、そういったところで確保すると、そういった内容になってあります。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"やはりなかなか難しい計画だなということを思いました。なかなか難しいなということを思うので、そういった説明の機会も設けていただきたいと思うのですが、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"こういった内容にしなさい、あとは、こういった算出根拠をもってやりなさいと示されているところもあります。今ご説明のところ、意見を参考しながらということで、考えてまいりたいと思います。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、自治体として分かりやすくしていくという工夫とかは全然できるものだと思うので、ぜひそういった工夫はしてほしいと求めました。４１ページの養育支援訪問についてですが、今の状況についてお知らせいただけたらと思うのですが、いかがか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"子ども家庭支援センターで実施しております養育支援訪問事業につきまして、子ども家庭支援センターにご相談いただいている件数は増加傾向にあります。私どものほうで専門職が実施しております育児支援ですとか専門相談など、そういったものが…","id":"exchange-077"}]},{"id":"topic-10","title":"認可保育園の新規開設等","agenda":"認可保育園の新規開設等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"最近、認証から認可への移行という報告が割と多いなと感じているのですが、これは大体、事業所からそういった申出があって進んでいくという流れが多いのか、もしそういった相談があった場合は、区としてどういう支援メニューみたいなものがあるのか、伺いたいと思います。","respondent":"中元保育支援課長","answer":"各園での受付になってくるのですけれども、認可に移行しますと、保育課での入所調整の対象となってまいります。児童福祉法に規定する保育所ということで、子ども・子育て支援法に規定する施設型給付の対象となってくるところが、大きく変わってくるものです。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"これからも何かそういったところは増えてくるのではないかなと思うのですが、すみません、何か財政支援というか、補助みたいな、整備に対しての支援とか、そういったものは何かあるのか尋ねました。","respondent":"中元保育支援課長","answer":"移行に向けて工事等が必要ですので、そういう部分での整備に関する補助ですとか、そういうものが子ども・子育て支援法の給付の対象となります。","id":"exchange-079"}]},{"id":"topic-11","title":"私立幼稚園の新制度園への移行","agenda":"私立幼稚園の新制度園への移行","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"初めてということなので、もう少し伺いたいのですが、保育料のところについては変化があるということでご説明がありましたが、何が変わるのかというのをもう少し、園の運営とかにとってどうなのか、通っている方にとってはどうなのか、それをもう少しご説明ほしいと求めました。","respondent":"中元保育支援課長","answer":"補助金の事務を区の保育支援課でやりまして、運営に必要な、公定価格で定められた額をお支払いしていくというところになります。園での教育については、特に変わるところはございません。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"幼稚園の設置者としての経営面ということになると、移行すると、少し支援が増えてくるというか、経営面から言うとプラスになるのでしょうか。そこら辺が少し分からなかったので、すみません。","respondent":"中元保育支援課長","answer":"園のメリットといたしましては、やはり経営面が、保護者の方からお月謝を集めるという事務も必要なくなりますし、安定的に区から補助金をお渡しいたしますので、安定するというところは大きな違いになってまいります。","id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"これも不勉強で教えていただきたいのですが、私立幼稚園だけれども私立保育園のような扱いになるということですよね。今、同じような書式をこの私立幼稚園も提出する形になるのかという部分とかも、お知らせください。","respondent":"中元保育支援課長","answer":"そこの準備が園にとっては、この１年間、ずっと保育支援課がお手伝いしながら準備を整えてきたというところはあります。保育園と同じような考え方で、申込みをされたら入園ができるという基本的な考え方となってまいります。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"この八潮幼稚園が今回の新制度に移行した理由をお知らせいただきたいのと、この移行準備をしている幼稚園があるのかという部分についても、お知らせいただけたらと思います。","respondent":"中元保育支援課長","answer":"ご相談が２か所ぐらいから来ているところですが、書類の準備のところとかはこれからご相談しながら、秋ぐらいまでに進めていくという形になります。〔「何で八潮幼稚園が今回移行されたのか」と呼ぶ者あり〕 すみません。正直なところ、やはり経営的なところを安定化させたいという思いが強く、この制度のほうにご検討されたです。","id":"exchange-083"},{"speaker":"渡部委員","kind":"確認","question":"確認なのですが、八潮幼稚園がこのように新制度に移行される。品川区の私立園が数園、品川区としては、新制度移行はこれからも応援していくというようなスタンスでいいのかどうかという確認をしたい。","respondent":"中元保育支援課長","answer":"新制度の説明会というものを幼稚園協会に集まっていただいているときにやったりして、まだ勉強中というところがずっと続いているような形でした。区としても、私立幼稚園のほうでそういうご希望があれば、全面的にサポートして応援していくという姿勢で取り組んでいるところです。","id":"exchange-084"},{"speaker":"渡部委員","kind":"質問・要望","question":"入園調整をどうしていくかというのが、もし方向性があるのであれば教えていただきたいのと、移行というのは期限は決まっていなかったのですか。その２点、すみません。","respondent":"中元保育支援課長","answer":"期限がいつかというのは、ちょっと私の中で今、認識にないです。申し訳ございません。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5094#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":77221,"voices":273}},{"id":"r05-20230228-5","meetingId":"r05-cm02","date":"2023年2月28日","dateIso":"2023-02-28","committee":"総務委員会","time":"午前１０時００分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 はじめに、(2)事務事業評価の試行実施","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 はじめに、(2)事務事業評価の試行実施","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"新公会計制度に移行したときに、議員向けの研修が１回行われて、たしか、私はその場で言ったでしょうか。要は、研修してくれないかなということなのですけれども、その辺について説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"こちらに関しましては、区民の意見を聞いて、それによって評価するということを予定しております。現状、会計管理室が担当しているところですので、ご意見として伝えします。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問・要望","question":"事業評価の結果の報告と伺ったのですけれども、結果も大事ですが、その後の公募にも関わってくると思うのです。区民も参加しながら進めるのだということを、まずはきちんと広報していただきたいのですけれども、その点についてお考えを説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"来年度に実施を予定しております政策評価につきましては、公募の際もそうですけれども、機会を捉えて周知していくことを考えております。既にプレス等でも公表しておりますので、引き続き、周知に努めたいと思います。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそれを進めてほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのことを伺いたいです。４２事業というのは、どのような事業で、どのように選んだのかということについても伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"そういった機会で、今後の取組というところで、令和５年度の実施を目指して、試行等を実施しているという形で答弁の中でご報告したと考えています。記載マニュアル等の課題への対応につきましては、実施と並行いたしまして準備しており…","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこら辺のところもどう考えられているのか、伺いたいと思います。その点についても伺います。","respondent":"佐藤（聡）計画担当課長","answer":"ご説明したとおり、主に来年度の行政評価実施のための課題の抽出、あるいは検証を目的として実施しております。来年度の評価に活かしていくことを考えておりますので、評価結果自体を報告するということは予定しておりません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事務事業評価によって、効率性でなくされた事業も幾つかあったと思うのです。福祉の削減につながらないところで、ぜひやっていただきたいということで、重々お願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"確認","question":"少し聞き漏らしたところもあるのでお伺いしたいのですが、各所管に再確認して、それを数字化または文書化して作るものなのでしょうか。それについて、まずお伺いします。","respondent":"佐藤（聡）計画担当課長","answer":"評価の仕方というところですけれども、基本的には、所管課で自分の所管している事業について、一般に目的等から始まりまして、評価まで記載いただいて、それに基づいて企画部で評価をしたという順番です。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"要は、身内が身内を評価するわけですから、その辺がどうなのかなということで、少しご意見を聞かせてください。その辺について、どうなのか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"これに関しては、平成２４年に実施した際も課題として挙げられていたところです。改めて、実際の評価委員会の前に勉強会ではないですけれども、その上で評価いただいてはどうかということで予定しているところです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"提案","question":"企画部のほうでこうやって提案しているのですけれども、恐らく、部長や課長は本当に大変だなと思います。非常に心配しているのですが、その辺はどうなのか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"区民の方に提示して、次の施策に活かすという形で実施することを予測しておりますので、全く成り立たないということではないかなと考えております。やはりそのような認識は持っておりますので、来年度は実施したいと考えておりますので…","id":"exchange-009"},{"speaker":"湯澤委員","kind":"質問・要望","question":"広報について、興味を持った区民の多くが理解していただけるような広報の発信の仕方も必要なのかなと思っているのです。何かその辺りの方針があれば、教えてほしいと求めました。","respondent":"佐藤（聡）計画担当課長","answer":"区民の方への周知というところで、なかなか専門用語が多いというのは、我々も日々感じているところです。難しいかなと思いますけれども、なるべくふだんの業務からご理解いただけるような形で説明を尽くしたいと考えております。","id":"exchange-010"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ある種、説明責任を果たすということを遂行していただきたいと考えていますので、ぜひ分かりやすい表現も含めてほしいなと考えています。そういったところに関しては、区として何か展開、展望があれば、教えてほしいと求めました。","respondent":"佐藤（聡）計画担当課長","answer":"あまり多くすると、一人ひとりの発言の機会や意見の機会が限られるという反面もありますので、なかなか難しいと考えております。ご意見をいただいて、その繰り返しでＰＤＣＡサイクルを回すということで、意見が反映されるような形で進めたいと考えております。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"今回は令和３年度主要施策の成果報告書の４２事業をやるということなのですけれども、いろいろな事業を見直されるということなのです。今後はどういうものにしていくか、誰がどうやって決めていくのかというところは、いつ決めていくのかということを教えてほしいと求めました。","respondent":"佐藤（聡）計画担当課長","answer":"評価対象事業につきましては、来年度は、基本的には全事業を対象にいたしまして実施することを予定しております。以降に関しては、またその結果を踏まえて検討していくということになろうかと思います。","id":"exchange-012"},{"speaker":"大倉委員","kind":"意見","question":"全事業ということで、分かりました。事業をどれだけ、どのようにやってきたかという説明をしっかり見直して、予算を効率的・効果的に正しく使うためには必要だなと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問","question":"前回やられたときの流れ、委員会、議会、区民も含めた公表までの流れを説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"事務事業評価は、前回は平成２４年にやっております。その際の結果については、区議会にお示しした上で、ホームページ等で公表するという流れでございました。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問","question":"前回、平成２４年でした。政策ですから、どのような資料を提示して、まさに評価いただくのかなというところを改めて説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"実施を考えておりますのは、例えば、子育てや環境といったところでご意見をいただきながら評価していただくことを考えております。事前検討会を進めさせていただいて、１１月を予定しておりますけれども、その上で評価いただくことを考えております。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問","question":"その中で、当然、評価だから、いろいろな評価があると思うのです。いや、これはやめるべきだという意見が出てくることを期待する場という理解でいいのか、説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"個別の事業に関してどのように考えられているかというところのご意見を、その上での評価と考えておりますので、副委員長ご指摘のような形で進んでいくと認識しております。","id":"exchange-016"},{"speaker":"つる副委員長","kind":"質問","question":"平成２４年のときもそうだったと思うのですが、政策ですから大きい方向になるので、関連してきていると思うのです。この結果の公表のタイミングは、平成２４年のときもそうなのですけれども、どのぐらいのタイミングでまとまって出るものなのか、説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"２つあって、１つは、これまで実施してきたことの評価というところがあります。あるいはもう少し長期的なスパンであれば、基本計画や実施計画に活かしていくという形で、位置づけとしては考えております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちなどは情報公開を求めると必ずそれを言われるのですけれども、その段階でとどまってはいけないと思いますので、ぜひ今後。もし何か見解があったら最後にお伺いしたいのですが、いかがでしょう。","respondent":"佐藤（聡）計画担当課長","answer":"政策評価で今回ご説明したところについては、まさに区民の方にご参加いただくということが１つの目的ですので、そのような観点でも周知していきたいと考えております。","id":"exchange-018"}]},{"id":"topic-02","title":"区における「東京都パートナーシップ宣誓制度」の活用","agenda":"区における「東京都パートナーシップ宣誓制度」の活用","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区としてＬＧＢＴＱ、区としてはそのような取組に対してどう考えられているのか、伺いたいと思います。そのような取組が現状でどうなっているのか、区としてどのようにしていこうとしているのかについて教えてほしいと求めました。","respondent":"加島人権啓発課長","answer":"区でも、冒頭申し上げました「みんなのひろば」や、当事者の方の相談を受けるためのカウンセリング相談などを実施してまいりました。パートナーシップ宣誓制度の活用が始まりますので、この行動指針に関する説明も、もう少し重点を移して行っていきたいと考えているところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区としては、そのような職員の研修、教職員の研修もされているし、子どもたちに対しての理解を深めるような取組もされているということですよね。そのようなことに対して、区としての姿勢や取組、方針を示すようなものは何かあったりするのか尋ねました。","respondent":"加島人権啓発課長","answer":"先ほどの説明で、１点、当事者の方をお呼びしてやっているような形になります。２０１９年、平成３１年に男女共同参画のための品川区行動計画、こちらに性的マイノリティへの理解促進と支援というものを取組目標として掲げまして。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"いろいろ見ても、そのような違和感を感じている子どもたちをしっかりと理解するというのもすごく大事だということが言われていると思うのです。そこら辺のところは、意識的に取り組まれているのか、その点だけお願いしますとの意見を述べました。","respondent":"加島人権啓発課長","answer":"人権啓発、人権教育に関して、重点的に推進するための学校が２校定められております。そちらを中心として、教育委員会のほうで職員に対する啓発を行っていると伺っております。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"職員も本当にしっかりと学んで理解していますよ、子どもたちが傷つかないためにも、そのようなところはぜひ進めてほしいと求めました。これから、この問題は多様性、インクルーシブのところで重要な問題になってきますので、ぜひ取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"健康保険なので、ただ、提示したりするときに表面にそれがないようにという配慮を品川区としてしていただいたような気がしたのです。今の事業のご紹介になかったので、もしかしてそれが間違いだったかもしれないのですが、もし把握しておられたら伺いたいと思います。","respondent":"加島人権啓発課長","answer":"私も記憶の中では、トランスジェンダーで外見と性別の記載が違う方に向けて、保険証の記載に配慮したと聞いております。恐れ入ります、こちらの部分については、後ほど、所管にも改めて意見とともに確認してまいります。","id":"exchange-023"},{"speaker":"吉田委員","kind":"確認","question":"その認識があるということが確認できたので、よかったです。やはり運動を進めれば、ちゃんと政策としても進むのだということが確認できて、とてもよかったと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-03","title":"令和５年度組織改正（案）","agenda":"令和５年度組織改正（案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回も（主査）制となっているのですけれども、課長の下に秘書担当を新設するというのは、課長の秘書みたいな形になるということなのですか。少しその点も伺いたいと思います。","respondent":"佐藤（憲）企画調整課長","answer":"冒頭のご説明でも一応お伝えしたのですけれども、（主査）制になると、複数の係長級職員の配置が可能になるということ。現庁舎跡およびその周辺を含めた広範囲の検討を行うというところと、検討委員会やワークショップ設置の運営もありますでしょうし、今後。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、この秘書担当というのは、秘書担当課長になるということなのですか。２ページの福祉部の一番下の障害者支援課のところで、これはなぜ廃止になったのか、伺いたいと思います。","respondent":"佐藤（憲）企画調整課長","answer":"障害児者総合支援施設担当は、指定管理を行うまでは、施設管理や事業者調整をその施設内に配置した職員が行っていました。ご案内のとおり、指定管理になりましたので、その業務は指定管理に委託しているところで廃止というところです。","id":"exchange-026"}]},{"id":"topic-04","title":"令和４年度都区財政調整再調整等","agenda":"令和４年度都区財政調整再調整等","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大体６ページにわたっていろいろと資料も出ていたのですけれども、なぜ今回はこのような２ページだけになっているのか、伺いたいのが１点です。これは、品川区の場合、この８項目で再算定するとどれぐらい増えるのか、教えてほしいと求めました。","respondent":"黒田財政課長","answer":"１点目の、今回、なぜ資料が例年よりも少ないのかというご質問ですが、先ほどご説明した、令和５年度の都区協議がまだ合意しておりません。およそ３６億５,０００万円ほど増収の予定でございまして、財政調整の増額として３６億円を計上させていただいておりまして…","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほど、それは、まだ児童相談所が始まったところが少ないからということなのですか。それとも、そのほとんどが開設しないと、なかなか東京都との調整の合意はできないということなのか尋ねました。","respondent":"黒田財政課長","answer":"令和２年度の協議の際にも、令和２年度は最終的に特例的な対応として０.１％の配分割合を変更したということなのです。現時点で８区が児童相談所を設置するということなのですけれども、大幅な役割分担の変更には当たらないというのが東京都側の考え方です。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"それに対して、品川区としては急なのだけれども、８区では算定には応じられないとなると、勇み足だったのですか。これには企画調整課や財政課が全部関わっていると思うのですけれども、その辺について、見解はどうなのか尋ねました。","respondent":"黒田財政課長","answer":"この配分割合を増やさなくても、現在の配分割合の中で、開設する８区の需要は十分算定できると主張しております。児童相談所の経費が全く算定されないということではなくて、今、財政調整の考え方自体が都と区で合意できていないということになります。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"東京都では、もう賄い切れないということが現状で分かっていたわけですから、そういうことに対して、何で理解がないのか。それはもう納まっているはずだというのは変な感じがするのですけれども、もう一回だけそこを答弁してください。","respondent":"黒田財政課長","answer":"東京都の基本的な認識としては、児童相談所の業務は広域的な業務であって、まずは一義的に都が担うべき事務であるというところが１つあります。今回は特別区の児童相談所の設置が令和５年度で８区という状況では…","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"まして、当時と社会情勢が全然違うではないですか。これに対して抗議をしたいぐらいですが、何とかうまく協議が成立することを祈っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-05","title":"国における「マスク着用」の見直し","agenda":"国における「マスク着用」の見直し","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点を伺いたいと思います。保健所ではなくて、なぜ総務課からこのような形での報告なのかというところも少し伺いたいなと思います。","respondent":"古巻総務課長","answer":"３月上旬ぐらいに国から一定の方針が出るということを保健所から聞いているので、区としての対応については、保健所で様々検討していくです。情報共有したり、方針について検討・協議を進めておりますので、庁内の連携はしっかりできていると申し上げられると思います。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に第８波のときには、介護の現場では自分たちが高齢者に感染させないようにというところで、本当に完全防備でやったりしているのです。本当に軽く見てはいけないと思いますので、慎重に運んでいただきたいということで、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"須貝委員","kind":"提案","question":"マスクはこうしろ、ああしろとここで提案されていますけれども、私は少し論点が違うのではないかなと思います。意見だけ言いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":33748,"voices":101}},{"id":"r05-20230301-14","meetingId":"r05-cm03","date":"2023年3月1日","dateIso":"2023-03-01","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１０時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6146#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":2246,"voices":11}},{"id":"r05-20230302-19","meetingId":"r05-cm03","date":"2023年3月2日","dateIso":"2023-03-02","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"では、陳情の順番に沿ってお伺いしていきます。どのようにお考えになっているのかというのをお伺いしたいというのと、それ自体について、その点をお伺いしておきたいと思います。","respondent":"河内環境課長","answer":"もう一つは、切迫度の認識です。根っこになっております脱炭素、二酸化炭素の排出抑制に向けてという点で、それをしっかり捉まえて進めていく姿勢は変わりございません。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"そして、この陳情された方が求めているのは、さらには気候非常事態宣言という手法を用いるべきではないかと。いかがか尋ねました。","respondent":"河内環境課長","answer":"共通にしたり、出さなかったりだとか、いろいろな考えがあるところです。事業者の方、シンプルな発信の中にも啓発手段としてはしっかり持ちつつ、こういったものを進めるべきかというところで今考えているところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"続いて、その実態も含めて、文字どおりの気候区民会議を設置していくことを求めているのだろうと私は考えました。そういう会議になっていくのだと思うのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"環境全般について二十数年来取り組んでまいりまして、一定の普及、定着状況も見て取れたかと思っているところです。取組内容につきましても、こういった内容も非常に鋭意進めているところもありますので、今すぐはというところは今は考えていないという状況です。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"何とかしなければいけないのだという認識をとにかく持って、解決へ向けて全力疾走していかなければいけないのだと。差し当たって３本、そうすると、検討していくということでいかがか尋ねました。","respondent":"河内環境課長","answer":"より実践的な進め方をしておりまして、あるいはスピード感でいいますと、こういった取組が非常に大事かと考えています。そういった意味で、今のところはまだすぐにとは思っていないという状況です。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"区民の納得の上で進めるべきですから、取り組みたくなるような充実した支援の提供、そういういろいろな工夫が必要だと思うのです。啓発活動が必要だと私は思うのですけれども、そこら辺、いかがお考えか尋ねました。","respondent":"河内環境課長","answer":"先ほども申し上げたとおりなのですが、こちらの義務化の条例ですが、令和７年４月に施行する予定です。この２年間、足踏みで何もしないのかというわけにもまいりませんし、支援なども啓発しながらやっていきたいです。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ進めていってほしいと求めました。東京都もそういうパンフレット、解体新書とか、そういうのを作っているのを見たりしましたので、ぜひやっていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"では、１個ずつ伺っていきます。品川区では、ゼロカーボンシティ宣言をするということですが、どういう検討でゼロカーボンシティ宣言にしたのかというところを伺いたいと思います。","respondent":"河内環境課長","answer":"こういった２０５０年に向けてということにはなるのですが、やはり取組内容をしっかり決めてからというスタンスということで進めてまいりました。２０５０年の目標、２０３０年の目標を明確にしたということもありまして…","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"私の質問の仕方が悪かったと思いました。どちらかにしようかとか、また、ほかの表現にしようかといったような検討はなかったのかというところも伺いたいと思います。","respondent":"河内環境課長","answer":"その理由につきましては、先ほど申し上げたとおりで、取り組む内容が脱炭素に向けてということで、同様なことです。特別区の中でも２１区が取り組んでおりますので、気候非常事態宣言の内容を含んでいるという進め方をするという検討内容で、今に至ったです。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"その危機感をぜひ打ち出してほしいということだと思うのですけれども、ゼロカーボンシティ、まだ宣言はこれからですよね。ぜひ今のこの危機的状況を訴える形に宣言をしてほしいと思うのですけれども、そこについていかがか尋ねました。","respondent":"河内環境課長","answer":"このまま行けば、諸説ありますけれども、皆さんのところで大変なことになるのですというところの危機感を発信しながらやっているところです。宣言が全てというわけでもないという認識なのですが、やはり実効性を取りながらも…","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"今後、こういった気候区民会議としての新たな会議体の設置についての検討というのはいかがでしょうかというところと、この会議が公開ではないのです。どういった議論がされているのかというところは、ぜひ見える化はしていただきたいと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"それから、実際の動きをつくる会議と、大きく２つあるかと考えています。傍聴の方を呼んでいろいろやるというような仕組みではないのですが、常にオープンでいろいろなことを話し合うようなところでやっているところです。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"どういった意見が反映されているかというのが見えるようにもしていただきたいということを求めたいと思いますが、いかがでしょうか。本当に気候危機の今の切迫的なこの状況をどうにか改善していこう、みんなでつながろうということを強く求めているのだと思うので、いかがか尋ねました。","respondent":"河内環境課長","answer":"この後出てまいりますパブリックコメントの報告の際に少し言及しようかというところでございまして、後ほどまたすみません、ご説明申し上げます。計画のことについては、そういったところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"本当にバッシングとかも確かに多かったと。そういうことではないのだというような説明、区内事業者、今そういった周知はどのようにされているのかという部分を伺いたいと思います。","respondent":"河内環境課長","answer":"概要などにつきましてご説明申し上げた上で、都の窓口をご案内するなど、そういったものに努めているところです。で、こちらの義務にかからないところで、やはり再生可能エネルギーの推進というのは非常に大事だと認識しております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"今のこの危機的な状況について知るための、そういったＰＲのポスターだったりとか、そういったこれからの周知方法について伺いたいと思います。本当に問題は区民の方たちなので、その方たちへの周知について、改めて伺いたいと思います。","respondent":"河内環境課長","answer":"自分のところの集合住宅かお宅かは分かりませんが、そういった質問を呼び起こせるような、そういった発信の仕方も今進めているところです。個別に丁寧に対応していくことによりまして、再生可能エネルギーを広げていきたいと考えているところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"その施設に入らなくても見えるような、区有施設でもこうなっていますというようなお知らせとかもぜひ今後はしていただきたいと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"各施設の所管につきましては、エコリンクなどを通じまして、啓発につきまして、今後、情報を流していきたいと考えております。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"製品の資材ですか、原材料を選んでいるのは企業。そこまで保障できるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"この陳情書にも書いてあるのですけれども、効果が薄い物件にまで強制的に義務を課すものではないというところは共有したいと思います。設置してそのままとかではなく、そういった議論の場というのが確保されているのかというところを伺いたいのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"太陽光パネルなどを設置して、進め方などにつきましては、ワークショップなどで積極的にそういったものを研究していきたいと考えているところです。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜ市民というのを使うのかというと、ぜひそういった議論の場ができるような機会を、そういった自治体になってほしいということを願っての質問です。説明の場とかを求めていただきまして、気候危機に対してみんなで共有できる場を持っていただきたいと思うのですけれども、改めて伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"小芝委員","kind":"意見","question":"気候非常事態品川宣言の陳情ですが、これ、既にゼロカーボンシティ宣言が予定されているというところもあります。既に内容も似ているところもありますので、事態を見守るべきではないかという判断で、継続すべきと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問・要望","question":"宣言そのものよりも取組が大事ということは大前提として、その上でゼロカーボンシティ宣言をこの４月５月に向けてやると。今、判断はできないということで、継続とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"ですから、いろいろな手段で訴えていく必要があると思います。採択を主張いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"田中委員","kind":"確認","question":"継続というので思わずびっくりしてしまって、継続と言われても、次というのはないということですよね。そこの確認をしたいと思ったのですけれども、委員長。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ならば、ぜひ皆さん、結論は出してほしいと求めました。ぜひ全会一致でできれば採択したいと思うのですが、いかがでしょうかと投げかけて、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと不採択でお願いいたします。今もう２１区が取り組んでゼロカーボンシティ宣言をしている、それをやはり見守っていくべきだと私は考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"小芝委員","kind":"意見","question":"継続にするでお願いします。そういった相手をもとにもう既に会議体が開かれておりますので、今後もその事態を見守るべきと考え、継続にしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問","question":"継続でお願いします。この品川区環境活動推進会議というものが既に２０年やられて、やはりここはしっかり継続して、慎重に見ていきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"おくの委員","kind":"意見","question":"その意味で、この気候区民会議の設置の陳情は、結論を出すで、採択ということでお願いしたいと思います。ここで継続にしますと廃案になってしまうという意味でも、ぜひとも結論を出すで、採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"皆さん、ぜひ、結論を出していただきたいなと。できれば全会一致で採択をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"現在、品川区環境活動推進会議を２０年もやっていることと、このたびは品川区環境基本計画、これもしっかりつくっているではないですか。これに対して何もやっていないわけでないので、全て実績があるので、このまましっかり継続してやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"小芝委員","kind":"質問","question":"ですので、今後は、この条例ありきというよりも、この事態をまず見守るべきではないか、まだ２年間ありますので。この件に関しては事態を見守るべきという考えで、継続にしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問・要望","question":"当然、区としても身近な自治体として、連携してやっていくことは大事だということで、既に一部やっていらっしゃるということです。令和７年４月ということなので、まだ時間もある中で、継続してやっていただきたいという中で継続にしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"おくの委員","kind":"質問","question":"あくまでも国民の納得の上でそういう対策を進めるべきですから、丁寧な情報提供や開かれた議論、そして充実した支援の提供は必要だと思います。そういう意味でも、結論を出し、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"この陳情は、都と連携して品川区としても区民や事業者に向けて新制度の周知をしてほしいということだったので、これは誰も否定していないと思います。区としても進めていますし、そういった周知を後押しすることにもつながると思うので、ぜひ採択を主張していただきたいなと強く願いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-02","title":"品川区環境基本計画素案のパブリックコメント実施結果","agenda":"品川区環境基本計画素案のパブリックコメント実施結果","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"代表質問をしたときの区長の答弁でも、情報提供を行うというご答弁になっていたかと思うのですが、事業者の方たちはしっかりされていると思います。家庭に向けたそういった情報提供等を行っていただきたいということと、計画の中でもきちんと示してほしいと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"今、委員がおっしゃいました家庭からの排出ですが、個々別々の事象として認識しています。で、社会共通の危険な物質などにつきましては、そういったものを取り上げてまいりたいという姿勢で進めてまいりたいと考えているところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ前向きにやってほしいと求めました。有害化学物質によって水などの汚染とかにもつながっていますので、家庭、市民に向けた発信もぜひしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"のだて副委員長","kind":"質問","question":"質問ですが、パブリックコメントの結果の公表が４月１１日となっていますけれども、公表日が違うのはなぜなのかというところを伺いたいと思います。数値の目標や石炭火力や原発について国に意見を言わないということが反映されているのではないかと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"２番目のほうから先にお答えさせていただいてよろしいでしょうか。先ほどの再生可能エネルギーの推進は、こういったところにつながるものと認識しております。","id":"exchange-035"},{"speaker":"のだて副委員長","kind":"質問","question":"この計画改定の発表が４月１日、パブリックコメントの結果の公表が４月１１日と、その理由を伺いたい。その普及をさらに広げていくためには、やはりそれを妨げている国の施策について意見を言っていくことが必要だと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"改めて国に申し上げるまでもなく、やはり再生可能エネルギーに向けての取組みを充実するというところが情報の優先度としては大変高いと考えています。そういったことからこういった方式での発信としたものです。","id":"exchange-036"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それを、新増設を含めて計画しているのが日本政府ということですから、ぜひそこはしっかり区としても指摘していってほしいと求めました。ＣＯ２削減の目標が世界基準に達していないという不十分な点、今、早期打開のために抜本的な見直しをすべきだということを求めておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"さっきの陳情のときにご説明をするとお話があった、品川区環境活動推進会議のことについて伺いたいです。生ごみについては、微生物によって土に返す方法についても計画の中で示してほしいといったご意見もあったと思うので、２点お願いします。","respondent":"河内環境課長","answer":"その上で、処理方法にアプローチしていくものだと認識しております。今後また処理方法など様々進展してくるかと思いますが、適宜発信していければと考えているところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"ページを教えていただきたいのと、公開についてなのですが、各会議体の会議録や要旨、そういったものの公開が今後されるという認識でいいですか。伺いたいと思います。","respondent":"河内環境課長","answer":"１０８ページのＰＤＣＡの真ん中のところに公開すると明記いたしたものです。それを振り返るのに品川区環境活動推進会議などの力もかり、ご意見も踏まえ、皆様に公表するというところでこの計画を進めてまいるものです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"多分これまでは自由な意見が云々かんぬんということで公開されていなかったと思うのです。ぜひ、議事要旨などでもいいので、どういった議論があったという、その経緯が見られるそういった形の公開を求めているのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"１０４ページをご覧いただきたいと思うのですが、こちらに推進体制と進捗管理指標が出てまいります。要旨など中身につきましては、今後の課題といたしております。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"要望にとどめますが、もう２０年、この品川区環境活動推進会議をされていて、これまで活発な議論がされているというご説明だったと思うので、どういった議論がされて、どういった理解が共有されているかといったところも分かるように、ぜひその議論の公開を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問","question":"３６ページ、そこはどうなのかなというところと、２０２１年１０月２２日に補助２６号線の大崎高校の地下のところが開通しているわけです。この出典の図が２０２０年ですから、この３月１日より開通したバスが間に合うかどうかという、反映可能かどうかという質問です。","respondent":"河内環境課長","answer":"間に合うように努力したいと考えています。","id":"exchange-042"},{"speaker":"たけうち委員","kind":"意見","question":"１２０ページのフードドライブのところです。本当に詰まらないところで恐縮なのですが、そこを直してほしいと求めました。","respondent":"河内環境課長","answer":"ご指摘どうもありがとうあります。修正したいと思います。","id":"exchange-043"}]},{"id":"topic-03","title":"品川区一般廃棄物処理基本計画（第四次）素案のパブリックコメント実施結果","agenda":"品川区一般廃棄物処理基本計画（第四次）素案のパブリックコメント実施結果","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"この委員会でも申し上げてきたことですし、皆さんおっしゃっていることですし、それに向けて今後も努力してほしいと求めました。それから、これも申し上げたことですけれども、サーマルリサイクルというのは何とかやめていただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"田中委員","kind":"意見","question":"この結果をどう受け止めているのかということと、なぜこのことを聞くかというと、品川区廃棄物減量等推進審議会では結構議論がされるのです。このパブリックコメント４名というのは非常に残念だなと思っていて、この発信方法だったり、そこのところをまずお知らせくださいとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"ただ、政策の方向として、少しでも関心のある方にこうやってコメントいただいているというのは非常にうれしいことだなと考えています。新たな手法で、そういったところもうまく活用しながら続けていきたいと考えています。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった説明とともにご意見を伺う機会というのを設置していただきたいですし、また、そういった工夫をしてほしいと求めました。３０ページ、体験会などの実施とかについても求められておりますので、いかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"実際に今、一定のリサイクル方法を研究していかなければいけないと考えていますので、そういった面で進めていきたいと考えています。構造は全く一緒で、少し大きいものという形でやっているものですので、通常の生ごみを入れて乾燥させて堆肥化していくというものです。","id":"exchange-046"}]},{"id":"topic-04","title":"第３８回 品川区防災フェア","agenda":"第３８回 品川区防災フェア","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"若干伺いたいのですけれども、最近コロナもあるのでどうかとは思うのですが、この防災フェアで位置づけられているのか。その点を伺いたいのと、どういうふうな支援が準備されているのかというのも、いかがか尋ねました。","respondent":"平原防災課長","answer":"新たな形でやっていかなければならないものについては、それに対応していくということで検討していきたいと思います。どういう展示がよいかというのは日々検討を加えながら、そういったものを進めてまいりたいと考えていますので、進化させていきたいと考えています。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"予約を取ったりとか、何かあるのかなというところを伺いたいのですけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"予算ですけれども、今回、全体的に委託という形で業者にお任せした関係もございまして、全体で６００万円ということで実施いたします。配布物ですが、それ以外には当日受付のところで、会場レイアウトとともにそれを見ながら回っていただくということを予定しております。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"６００万円の予算というので少し驚いたのですが、もし分かればお知らせいただきたいのと、伺いたいと思いました。","respondent":"平原防災課長","answer":"来場されたお子様であるとか、そういった方々を中心に、いわゆる防災啓発品をお配りするというようなことも今回の予算に含まれております。いわゆる物品費に当たるものについては約１００万円といったところで…","id":"exchange-049"}]},{"id":"topic-05","title":"「しながわ防災こどもｂｏｏｋ」の作成・配布","agenda":"「しながわ防災こどもｂｏｏｋ」の作成・配布","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"小学校１年生ですから、どうしたのと声がかかることも、そのメッセージがあるとすごくよかったなと思いました。見解を伺いたいと思いますけれども、次回にはそういった視点も持って具体化していただけたらと思ったのですけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"そういったところを踏まえて、次回は、そういったところを反映させていただければと思っています。これで最終という形ではなくて、随時更新を考えてありますので、そういったお声を反映させていただければと思います。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"確認をさせてください。簡易トイレがないではないですか、今後もし改訂されるときには、トイレットペーパーと簡易トイレがあったらいいなということを求めたいと思います。","respondent":"平原防災課長","answer":"１９ページのところ、後ろのシールでありますとか、２６ページのチェックのところは入ってあります。２６ページ、救助のときには重要だと考えていますので、そういったところについては周知啓発してまいりたいと考えています。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"１点だけ要望したいと思います。防災課が出張でお話に行くとか、そういった工夫ができたらなということを思ったので、そういったことも話し合ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"松澤委員","kind":"質問・要望","question":"すみません、家庭の話をしてしまい、少し恥ずかしいですが。そういったところに１枠、要望するとか、説明を求めました。","respondent":"平原防災課長","answer":"学校との連携という点ですけれども、全ての学校というわけにいかないのですけれども、ご希望されている学校で行っているところです。今回、今回この配布を通じて、さらにそういう連携が進むように教育委員会ともしっかりと手を携えて行っていきたいと考えています。","id":"exchange-053"}]},{"id":"topic-06","title":"令和５年度品川区・区内三消防署合同水防訓練および避難施設開設訓練の実施","agenda":"令和５年度品川区・区内三消防署合同水防訓練および避難施設開設訓練の実施","exchanges":[{"speaker":"田中委員","kind":"質問","question":"避難施設開設訓練について伺いたいのですけれども、自治会等とあるのですが、この等には誰が含まれるのか。町会、自治会以外の方も参加は可能なのかどうかというところを伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"それは聴覚障害者ばかりでなく、視覚障害者の方にもお声かけする予定です。さらに言うならば、外国人の方にもご見学いただくよう総務部門と、今、調整を始めているところです。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"障害者の方たちだけではなくて外国人の方たちも、様々な方が参加できるということですよね。町会の掲示板とかでのお知らせとかもあるのかなというところも確認させていただきたいのと、見ているだけではなくて、いかがか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"町会への周知につきましては、個別に書類のほうで、地域センターを通して実施してまいります。説明員を必ずつけて対応するということで、今、内容について調整を進めているところです。","id":"exchange-055"}]},{"id":"topic-07","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"のだて副委員長","kind":"質問・要望","question":"活発な委員会になったと思いますので、それを区のほうでもしっかり活かしてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6632#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":43251,"voices":145}},{"id":"r05-20230306-3","meetingId":"r05-c-budget","date":"2023年3月6日","dateIso":"2023-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を183件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問","question":"残り時間が少なくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。次に、第５項、総括質疑につきましては、例年と同様に、特に政策的な質問をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、８ページの歳入全般、そして８７ページ、給食施設整備費の２点を伺います。この辺りの傾向が大体このような形で例年と変わりないものなのか、あるいは、この年度に特別な事案があったかどうかの確認をしたいです。","respondent":"黒田財政課長、勝亦学務課長","answer":"令和３年度の最終補正予算額を若干下回った、決算見込額が５１２億円ですので、２３億４,８００万円の増額補正をしたというものです。調整税等の収入見通しが、当初の算定時より９２６億円の増収見込みとなりまして… 私からは、給食設備の工事に関してお答えいたします。８校ほどの工事を行いまして、伊藤学園の冷媒配管工事といったものを必要十分な範囲で行って、工事費に契約落差が出たものです。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問・要望","question":"こちらの要望も、やはりお願いベースにもなりますが、ぜひとも対象のところで枠内にしていただきたいという要望を受けています。特別支援学校への給食費無償化もぜひお含みいただきたいというのが、私たち自民党の改めての要望になりますので、この辺のお考えもお知らせください。","respondent":"提坂税務課長、勝亦学務課長","answer":"今回の補正予算の特徴的な部分ですけれども、まず普通徴収につきましては、納税義務者数については、ほぼ見込みどおりの数字だったということです。当初見込んだ数よりも８００人弱ぐらい増えたということと、あと… 学校教育法上、特別支援学校につきましては、設置者が都道府県と定められてあります。現状把握等に努めているところではありますが、支援の実施につきましては前向きに検討していきたいと考えています。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"この令和４年度に限らず、では来年度はどうなのだろう、あるいは中長期で見てどうなのだろう。その辺を説明を求めました。","respondent":"提坂税務課長、勝亦学務課長","answer":"かなり影響を受けて、税収が減になるのではないかと見込んでいた部分はあったのですが、逆に増収になっているという部分があります。微増の部分がありますけれども… 物価上昇が継続していますので、中学校１食２０円を上乗せした単価で無償化を進めて、１食をつくっていきたいと考えています。そういった中で、現状６％程度の上乗せをしておりますので、当面は今の金額で、給食の必要な質…","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"まさに給食費のところはそこを伺いたくて、補正で対応しました、この辺の柔軟さというものが非常に大事かなと思われます。そういう意味で、政策的な趣旨の確認です。","respondent":"佐藤企画調整課長","answer":"子育て支援、そういった政策が品川区全体のまちづくりや活性化につながるというところで、非常に重要な政策だと考えております。そういった施策を品川区から積極的にスピード感を持って全国に発信していくところで、より少子化対策を進めていくです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"７５ページ、８３ページ、公園内の多言語化についてお伺いいたします。初めに、私立幼稚園保護者補助金について、内容をお知らせください。","respondent":"中元保育支援課長","answer":"こちらは、私立幼稚園に対し、区が、子どもが通園している保護者の経済的負担を軽減するため、保護者の方の所得に応じて保育料の一部を補助させていただいている事業です。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"区内で初めて、新制度へ１園が移行とのことです。幼稚園に通う保護者の方々にとって、この私立幼稚園保護者補助金に関しては何か影響があるのか、お伺いいたします。","respondent":"中元保育支援課長","answer":"こちらは、平成２７年度に開始されました、子ども・子育て関連３法に基づく子ども・子育て支援新制度のことを略して、新制度と総称しているものです。入園料や給食費等の実費相当額のみを幼稚園にお支払いいただくようになります。","id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"次に、新制度に移行した場合、私立幼稚園と在園保護者それぞれについて、どのように、何か変わることがあるのか、主な変更点を伺います。これまでの幼児教育に影響があるのか、伺います。","respondent":"中元保育支援課長","answer":"ですので、新制度への移行は、施設が利用者の方に提供している教育・保育の内容に何ら変更を加えるものではございません。従来から各私立幼稚園で行われている保育・教育の内容が、園の方針や理念に変更がない限り、引き続き実施されることとなります。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。今後ですけれども、この新制度を、区として私立幼稚園に対して新制度移行を推進されていくのか、区のお考えをお伺いします。","respondent":"中元保育支援課長","answer":"新制度への移行に当たりましては、私立幼稚園に一定程度の施設や設備基準の確保などの要件が求められます。ご希望があれば、区が可能な範囲で手続をサポートするということで、進めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"平成２７年度にこの制度ができてから、今回初めて１園が移行ということで、かなり園の準備といいますか、そういう負担があったのかなと思います。具体的なスケジュールと、園側の事務負担や、その負担に対して区がどのような支援をしていただけるのか、お伺いいたします。","respondent":"中元保育支援課長","answer":"今年度は７月に私立幼稚園園長会におきまして、新制度の説明会を実施いたしました。保育支援課の職員も園に足を運んだりしながら、園舎・園地などの実地調査も行い、園に寄り添って継続して支援を行ってまいったところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"提案","question":"関連いたしまして、次に、幼児保育・教育の視点で、保育園ではなく３年保育の私立幼稚園にお子さんを預けたいと考えられる保護者がいらっしゃいます。幼稚園と保育園の一時預かりをつなげていく仕組みづくりを、ぜひ提案しますが、見解を伺いますとの意見を述べました。","respondent":"中元保育支援課長","answer":"区としましても令和５年度予算で、私立保育園等で空きスペースを活用した一時保育事業について、予算を計上させていただいているところです。将来的には、こちらの一時保育を、制度を整えまして、長期休業中に私立幼稚園の皆様にも拡充していければと考えているところです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"提案","question":"保護者からは、国や東京都、区、それぞれの使える補助金や助成金が分かるようにしてほしい。ぜひ品川区でも、子ども・子育て支援に関する全てがまとまったポータルサイトの作成を提案いたしますが、見解を伺いますとの意見を述べました。","respondent":"廣田子ども育成課長","answer":"令和４年度、本年度から検討を開始しまして、令和５年度にはリニューアルを考えておりますので、これから工夫していきたいと思います。情報の更新が年に１回となっておりますので、区のホームページ等でリンクが張れないかなど、至急検討しようと思ってあります。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"改めてお伺いしますが、区内の公園・児童遊園における注意事項等の多言語化についてお伺いしたいと思います。改めてお伺いいたしますので、ご答弁は結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"８３ページ、地域交通検討経費、コミュニティバスについて伺います。新年度は当初から１時間３本での運行になるわけですけれども、伺いますけれども、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"来年度のコミュニティバスの運行経費補助の金額ですが、６,１００万円程度です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"試行運行３年目で、この基準を満たさない場合、廃止を含む見直しをする判断を行うとしています。２年目も評価を行おうとしていますけれども、１年目の今年もそろそろ終わろうとしているのですが、見通しを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"３月末から試行運行を開始しまして、１月末までの状況ですが、現在のところ、シルバーパスの分、シルバーパスは基本的には無料でご乗車いただくわけですが、その分を補填した形で、現在の収支率が５８.６％というような状況です。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、他自治体を参考にしたというのであれば、他自治体の状況、特に２３区の状況を伺いたいなと。５０％以上に設定しているという区は何区あるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"調査をかけた時点での数字ですが、コミュニティバス運行区のうち６区が判断基準を設定しています。そのうち、５０％以上の区が５区というような状況です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"担当者の方に「収支率というのは設定しているのですか」と聞いたら、「え、収支率ですか」というリアクションだったのです。収支率５０％で、利用者を増やす努力こそ行ってほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"一定、それに向かって乗車率を向上していく取組を継続していくことが、使っていただく区民の方に提示する上でも非常に重要な数字だです。現在、試行運行ですので、その状況を適宜、地域公共交通会議でもお示ししながら、様々な取組について検討していきたいです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年１１月からの、伺いたいのですが、渋谷から山手通りを通って大崎を経由して大井町に行く。あったとすれば、どのような説明だったのか伺います。","respondent":"鈴木都市計画課長","answer":"やはり東急バスとして、事業採算性も含めて、地域の利用実態も含めて、ダイヤ改正を行って、進めているところだです。基本的には利用実態に合わせて、今後も継続してダイヤ等については適宜見直しを行っていくと聞いているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"この大崎ルートは、先ほどの紹介した区の考え方に照らしても、一日も早く運行を始めるべきだと思うのですけれども、いかがでしょうか。区の考えを伺います。","respondent":"鈴木都市計画課長","answer":"残りの候補案、今お尋ねの大崎ルートにつきましては、基本的には現在、試行運行を開始している大井ルートの状況を見ながら、適時適切に判断していくです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"大井ルートは参考程度にはなると思います。大崎ルートの試行運行は、なぜ大井ルートの試行を待たないと行わないのか、合理的な説明があれば伺います。","respondent":"鈴木都市計画課長","answer":"試行運行を開始するに当たって、様々な状況の検討をしてまいりましたが、把握していなかったです。そうした意味では、それを一定、一年、二年、その推移・経過を見守って、しっかり、残りの２ルートの実施の方向性についても検討していきたいです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"全く納得のいく説明ではないと思います。大崎ルートの一日も早い早期運行と、料金は１００円に下げ、便利で使いやすいコミュニティバスの実現を求めて質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"７７ページの新型コロナワクチンの集団接種会場運営委託について、８５ページの高層マンション対策リーフレット作成等経費についてお伺いします。この主な内容と、事業についての補助金がどういった補助金なのか、お知らせください。","respondent":"平原防災課長","answer":"こちらの防災普及教育費ですけれども、災害時に必要となりますハザードマップの作成経費に対しましての国費補助でございまして、今年度、防災地図を見直した中にハザードマップ全てを入れさせていただいたところの国庫補助です。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"そこで区では、今回、ハザードマップを更新されたということですが、区民に対してどのように周知を行っていかれるのでしょうか。伺います。","respondent":"平原防災課長","answer":"今回、そちらを区内全戸配布、これは２月の中旬ぐらいから開始させていただいたところです。様々な機会を捉えまして、防災地図の活用方法についても周知・啓発してまいりたいと考えています。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"こうした災害も含めて取り組んでほしいと求めましたが、その点についてもしご意見がありましたら、お伺いいたします。ペットと一緒に避難ができる施設という掲載が表示されていなかったように感じますが、ぜひそれも今後どのようにされていくのか、併せて伺います。","respondent":"平原防災課長","answer":"現在、例えば富士山でいきますと、地域防災計画の見直しの中でしっかりと今後考えていきたいと考えています。検討させていただきまして、この防災地図とは別の形になりますが、しっかりとこちらも周知させていただきたいと考えています。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"この防災地図を実際に使っていただくための取組を、区ではこの防災地図の配布により、どのような効果を期待されているのでしょうか。伺います。","respondent":"平原防災課長","answer":"風水害と地震とで避難の考え方も異なりますので、まず１つ、工夫させていただいたところです。幅広く周知させていただきまして、しっかりと防災のこと、あるいは避難のことについて考えていただくきっかけとなればと考えているところです。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"これについても、もしなくした場合、その場でもらえるのでしょうか。地域センターに行ったり区役所に行ったり防災センターに行ったりしたら頂けるのか、それについて伺いたいと思います。","respondent":"平原防災課長","answer":"防災ハンドブック、防災地図につきましては、区民の方々にお持ちいただきたいものと考えています。転入された方、あるいは紛失された方につきましては、しっかりご対応させていただきたいと考えています。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"６７ページの歴史館運営費の１億２,９１０万円のマイナス理由について伺いたいと思います。品川区の伝統文化の発信拠点である歴史館のリニューアル工事の今現在の進捗状況がもし分かれば説明を求めました。","respondent":"山崎文化スポーツ振興部長","answer":"そこの請求がなく、当初の支払い計画が変更になったということで、来年の債務負担行為に当該額が回っているというようなところです。来年度、補強なども含めて組み上げるというようなところで、解体工事などが進んでいるというような状況です。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"私の知り合いでも、お茶をやっている方がいらっしゃいまして、ぜひ茶室を使いたい、いつ頃使えるのかという質問がありましたので、お聞きしました。やはり区民の皆様方に立ち寄っていただきたいということで、ぜひペットや駐輪場を若干増やしたり、その点について伺いたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"子どもたちも含めて、多様な方々が品川区の文化を経験し、体験しというようなことで考えてあります。活発な交流や連携を育む拠点づくりとしまして、そういった考慮も入れながら、リニューアルを進めているところです。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問・要望","question":"続けて今度は８５ページの、高層マンション対策リーフレット作成等経費が、約２１０万円マイナスになっていると伺っております。いわゆる階数が当てはまるのか、また何棟ぐらいが対象になっているのか、ざっくりでいいので説明を求めました。","respondent":"平原防災課長","answer":"そういったところも含めまして、今後ご審議いただきます新年度予算のところでしっかりと対応させていただきたいと、今、考えているところです。区内で８６３棟を対象とさせていただいているところですが、対象マンションの再検討も含めて、検討しています。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"マンション防災対策について少し伺いたいと思うのですが、現在、様々な方法で防災対策関連の講習会が実施されるとお聞きしております。ぜひ拡大していただきたいと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"マンションの管理組合に対しましては、平成２９年度より、希望がございましたら防災講演あるいは防災訓練の支援を行わせていただいているところです。先ほどのお話にありましたとおり、マンション対策の進捗と併せまして、また検討してまいりたいと考えています。","id":"exchange-030"},{"speaker":"江野下委員","kind":"質問","question":"これまでの国際交流の節目でもある友好憲章締結３０周年記念事業は、２年後にはなってしまいますが、また新しい別の形での開催はお考えでしょうか。ご見解をお伺いいたします。","respondent":"古巻総務課長","answer":"今ご説明があったとおりでございまして、結局今年もコロナ禍の影響で実施できなかったということで、成果はあったのかなと考えています。１６人程度のホームステイの受入れをするということで、プラスして何かできることがあれば考えて、進めていきたいと考えております。","id":"exchange-031"},{"speaker":"江野下委員","kind":"提案","question":"品川区とジュネーヴ市とも、スポーツを通じた交流をしていくのはいかがでしょうか。世界のトップアスリートが走る大会、品川区シティマラソンで上位の選手を品川区民から派遣したりと、マラソンを通じた国際交流はいかがか尋ねました。","respondent":"古巻総務課長","answer":"ポートランド市とは５年ごとにスポーツ交流を様々行わせていただいておりますけれども、今ご提案いただきましたジュネーヴ市とマラソンです。まだこれから様々な検討が進んでいく状況と認識しておりますので、どんな工夫ができるのかということは考えていきたいと思います。","id":"exchange-032"},{"speaker":"江野下委員","kind":"提案","question":"そこでご提案です。ポートランド市、品川区にお住まいの外国人の方々の国々の郷土料理等を一堂に会した、地域に住む外国人との交流事業を開催してはいかがか尋ねました。","respondent":"古巻総務課長","answer":"いろいろ検討といいましょうか、進めさせていただきたいと思いますけれども、様々なイベントがこれからまた再開してくると思います。その中で、どんな国際交流ができるのかということをしっかり考えていきたいと思います。","id":"exchange-033"},{"speaker":"江野下委員","kind":"質問","question":"新時代の品川区にふさわしい、新しい国際交流を希望して、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"８３ページ、７７ページ、新型コロナウイルス感染症対策について伺います。この状況を共有するために改めて伺いますが、関係する部署はどこなのか、お知らせください。","respondent":"吉野戸籍住民課長","answer":"１点目なのですけれども、今もＤＶ対応はさせていただいているのですけれども、情報の漏えいが懸念されております。それから関係します警察・他自治体から、こういったところでの注意喚起、それから被害といった情報は来ておりません。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれの部署で行った対応についても伺ったので、併せて伺いたいと思います。この続きについては総務費で伺いますが、それぞれの部署で行った対応についてはお答えほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘によりまして、各課でホームページで周知しているところです。それから、私どもの戸籍住民課では、窓口でも案内通知をお渡ししているというような形になっています。","id":"exchange-036"},{"speaker":"田中委員","kind":"提案","question":"各家庭の騒音対策など、今、現に起きている悪影響に対応するための補助を、区として国に求めているのでしょうか。求めているのであれば、その方法、どんな書式で求めているかなどを伺いますとの意見を述べました。","respondent":"吉野戸籍住民課長、鈴木都市計画課長","answer":"申し訳ありませんでした。人権啓発課なのですけれども、こちらも連携させていただいて、至急、ホームページにアップさせていただきたいと思いますので、よろしくお願いします。 それの検討経費と連動しておりまして、検討経費で契約落差が生まれた関係で、こちらの助成金についても減額の補正です。過去、基本的にはしながわ花海道という言葉を出して説明させていただきましたが…","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"文書で行ったのかどうかなども伺いたいと思います。文書で要望したのであれば、それをきちんと示してほしい、公開してほしいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"委員からの事前のお問合せについては、電話でお聞きいただいた内容については、その要項に沿って丁寧に説明させていただいたです。台場小学校、羽田新飛行ルートが運用開始される前に、防音工事が終了しているというようなところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"機構と協議会が別団体なのかどうかということも、答弁漏れでしたので、お知らせください。約３,０００万円の補助金を品川区は受けているのであれば、きちんとこの要領について公開してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それから、その音につきましては、国のほうで騒音の想定値を用いて、本格運用開始前に防音工事助成の施設について調査をし、工事が行われたです。必要に応じて電話等で、前回も回答させていただきましたが、そうした形でお伝えしたいです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"きちんと、地域の方たちが求めている騒音対策の補助もあるのではないか……。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"１か月何回、監査委員協議会を開催し、その１回当たりの会議は何時間ぐらいあるのでしょうか。そして、１か月の報酬は幾らになるのか尋ねました。","respondent":"高山監査委員事務局長","answer":"そして、１回の会議時間につきましては、おおむね２時間程度です。それから、非常勤の、同じく議会選出の監査委員につきましては１８万２,０００円という月額の報酬が設定されております。","id":"exchange-041"},{"speaker":"須貝委員","kind":"意見","question":"他の自治体などでは、給与制というのをやめて、そして、１回の会議に出席するごとに１日当たり３万円の日当制にしています。これを採用しているのですが、品川区もこういうことをいつまでもやらないで、改善するべきだと私は思うのですが、ご見解を説明を求めました。","respondent":"高山監査委員事務局長","answer":"監査委員の報酬につきましては、監査委員の給与等に関する条例において定められているところです。議会の議決を経て設定されているものですので、私ども事務局の立場から、報酬の設定に関しての見解を申し述べることは控えします。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"それを、いつまでも品川区がこういうやり方をしていいのでしょうか。２０万円もらっていいのか尋ねました。","respondent":"古巻総務課長","answer":"先ほど監査委員事務局長からもお話をさせていただいたとおり、その職責等に応じた金額ということで、条例で定めがあるところです。今の報酬自体がそれほどの高額ではないのではないかといった認識もありますので、現状、推移しています。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"今、新人や若手職員で退職する方が増えていると私は聞いていますが、品川区では実態はどうなのでしょうか。民間企業でも同じような話を私は聞いていますが、これの主な退職理由は何で、どういうふうにお聞きになっているのか尋ねました。","respondent":"崎村人事課長","answer":"そのうち、２０代、３０代、いわゆる若手職員の方々が大体７５％ぐらいになっております。育児に専念したいといったことでお辞めになる方、様々な理由がありますけれども、理由としては以上のようなところです。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"採用に当たっては、全員、品川区で募集して、品川区で面接して、品川区で採用を決定しているのでしょうか。採用は１年に１回か尋ねました。","respondent":"崎村人事課長","answer":"採用選考が任命権者に委任されているものについては区で実施していますが、特別区人事委員会が採用選考を実施いたしまして、採用するといった流れになってあります。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"そして品川区にマッチングする人を採用していかないと、８０人のうち７５％が若手だというのが、問題があるのではないですか。それとも、あくまで、例えば８０人採用するのは、いや、取りあえず８０人みんな入れないといけないということになってしまうのか尋ねました。","respondent":"崎村人事課長","answer":"ただ、採用選考を区独自で実施するということになりますと、人事委員会というものを独自で設置して、そこで採用選考を行うということになります。採用予定者数を年度の初めにお示しして、面接をして、時には本当に需要数を満たさない合格者ということもあります。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"というのは、どういうことですか。もし何かご見解があったら説明を求めました。","respondent":"崎村人事課長","answer":"区で活躍していただきたい職員、また区の中で働きたい職員という方を、一人でも多く採用したいと考えております。人事課として、しっかりとＰＲして、職員採用に向けて力を入れていきたいと考えております。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問・要望","question":"人も変わっているので、私は考えてほしいと求めました。今の制度がすぐ改善できないなら、品川区は品川区独自で、何かしっかりした採用方法を考えていただきたいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"せらく委員","kind":"質問・要望","question":"私からは、８５ページの防災関係組織経費について、時間があれば８３ページの都市防災まちづくり事業費について質問させてほしいと求めました。このＩＣＴ支援員について、現在の体制、支援員の人数、学校数と併せて説明を求めました。","respondent":"勝亦学務課長","answer":"ＩＣＴ支援員に関するお問合せです。現在、事業者と契約をしておりまして、２５人の体制で４６校の学校を受け持っているという状況です。","id":"exchange-049"},{"speaker":"せらく委員","kind":"質問・要望","question":"さっとスマホからお便りを見ることができて、行事や準備品がすぐに確認できる状態になると、品川区の子育て世代のニーズにも応えられると思います。まだ対応していない学校でのプリント配布のオンライン化を全校で実施してほしいと求めましたが、そういった学校において、伺います。","respondent":"勝亦学務課長","answer":"半分半分ぐらいである学校、それぞれ各学校の保護者、学校の状況等に応じて状況はまちまちです。そういった中で、利便性の向上、それから保護者の方のご意見を伺いながら、こういった利便性の向上を図っていきたいと考えています。","id":"exchange-050"},{"speaker":"せらく委員","kind":"質問・要望","question":"ぜひ進めていただきたいと考えていますが、学校側がやろうとしないといいますか、ＩＣＴ支援員の力を借りてぜひ進めてほしいと求めました。こちらはどちらなのか、伺います。","respondent":"平原防災課長","answer":"マンション防災の件ですけれども、今回、補正予算で提出させていただいたものにつきましては、令和４年度に増刷を考えていたものを、事業を取りやめた内容のものです。","id":"exchange-051"},{"speaker":"せらく委員","kind":"質問","question":"防災士資格取得においては、６万１,０００円ほどかかる費用を、他区では助成しているところもあります。地域の皆さんの防災への関心を高める効果もあると思いますが、区ではどのようにお考えか尋ねました。","respondent":"平原防災課長","answer":"より地域に具体的な防災の内容を考えていただくものといたしまして、平成２８年度から、しながわ防災学校という取組を進めしています。この中で、防災に関して考えていただくという講習を行っておりますので…","id":"exchange-052"},{"speaker":"せらく委員","kind":"質問・要望","question":"品川区では防災学校が無料で受講できるということで、こちらはどのような方が受講しているか教えていただきたいです。伺います。","respondent":"平原防災課長","answer":"やはり中心となって考えていただけるよう、この防災学校の取組でも、そういった講座をしています。こちらにつきましては修了後には修了証をお渡しさせていただいているところです。","id":"exchange-053"},{"speaker":"せらく委員","kind":"質問","question":"最後に、時間がないので１問だけ、都市防災まちづくり事業費について伺いたいと思います。この建て替えなどがうまく進んでいない状況かと思いますが、詳しくお伺いします。","respondent":"大石木密整備推進課長","answer":"一番多いのは不燃化特区支援事業におきまして、助成金が当初の予定より少なくなってしまったということがあります。〔時間切れにより答弁なし〕","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"私からは、補正予算書７３ページ、子どもの未来応援事業、６８３万円から、しあわせ食卓事業についてお聞きいたします。これはどういう意味で繰り越していくのか、ご説明をお願いします。","respondent":"飛田子育て応援課長","answer":"今回、令和４年度子どもの食の支援事業に賛同いただけるガバメントクラウドファンディンクについてですが、目標額５００万円のところ。適量を継続的に配布することがより効果的と考え、余剰分を令和５年度に繰越しし、必要な時期に再度配布する予定としております。","id":"exchange-055"},{"speaker":"松澤委員","kind":"確認","question":"そういった子どもたちに食品を届け、精神的なサポートにもつながり、付加価値のある取組であると記載がありました。食の配送から各支援につなげ、最終的には自立を目的とする事業であるのか、確認させてください。","respondent":"飛田子育て応援課長","answer":"そのため、配布食材一式の入った段ボールの中に、各種支援事業のお知らせやアンケートを同封しております。アンケートの回答欄には、こちらから電話をして相談に乗る、アウトリーチ型のつなぐ支援事業を実施しています。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問","question":"企業や全国に対して、食の支援事業を周知していくべきかと考えますが、ご所見を伺いたいのが１点。子どもが多い世帯というのですか、３つといった、ご見解を説明を求めました。","respondent":"飛田子育て応援課長","answer":"支援企業もしくは区が委託している配送業者が行っており、現時点では、なかなか世帯の状況に応じた対応は難しいのかなと考えております。どこまで世帯の状況に応じた対応が今後可能なのかにつきましては、引き続き検討させていただければと思います。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"１世帯２つ、３つというのは、より多く配れるような形につなげていただけたらと思います。支援につながったケースというのですか、そういった実績があったら教えていただきたいのと、ご見解を説明を求めました。","respondent":"飛田子育て応援課長","answer":"それでまた話を聞く中で、それぞれの必要に応じた支援につなげているところです。検証につきまして、現在、第２期品川区子ども・若者計画の策定をしておりまして、そこの中でも、他の分野でも連携を深めていければと考えております。","id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"２８件、数字が分かりました。支援の縦割りにしないというのですか、そういった考え方でいくべきではないかと思いますけれども、ご見解を説明を求めました。","respondent":"飛田子育て応援課長","answer":"こちらの目的なのですが、子どもの食の支援、また独り親家庭の食の支援となっているため、この寄附の目的を尊重しつつ、他の部署でも行っている支援、またそういうところも充実を図っていければと考えております。","id":"exchange-059"},{"speaker":"せお委員","kind":"質問","question":"私からは、６９ページ、障害者福祉施設等整備費、７１ページ、障害児支援事業についてお伺いします。一方で、今お示ししたように毎年大きな額の補正額が出てきていますが、その理由をお伺いしたいです。","respondent":"松山障害者支援課長","answer":"増加率を見込み、毎年、当初予算を計上していますが、給付費が当初予算を上回る伸びを示しております。障害児の手帳を所持しなくても、発達の遅れについてご不安があり、早期療育を受けさせたいというご家庭が増えていることと考えております。","id":"exchange-060"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、医療的ケアが必要な方のプラン作成を今までやったことがない事業所というところにとっては、少し負担が大きくなります。この現状をお聞かせいただきたいのと、あと、今後この医療的ケア児の基本相談、計画相談ともにどのように行っていくのか、計画を説明を求めました。","respondent":"松山障害者支援課長","answer":"現状としましては、今後、３月１０日に医療的ケア児コーディネーター連絡会を開催する予定でおります。今後、包括的な支援の提供につなげるとともに、医療的ケア児に対する地域づくりを推進することができるのではないかと考えております。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問","question":"こちらは、グループホーム整備を行う事業者が想定より少なかったという理解でよろしいのかということと、あとその理由が何か考えられますでしょうか。説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"２つほど考えられると思うのですけれども、まず１つ目として、品川区の整備費補助の交付決定というのは２段階設定になっております。こうした社会情勢もあるので、なかなかすぐに整備費補助には結びつかないという、難しい局面があるというのは事実です。","id":"exchange-062"},{"speaker":"せお委員","kind":"質問・要望","question":"区長も施政方針で、「民間事業者に対する整備費補助金の周知強化」と述べられています。ぜひ周知強化をお願いしたいところですが、時間もなくなったので、そこのところは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"確認","question":"７７ページ、健康センター事業費の３件の予算案に関連いたしまして、確認と質問をします。区内の避難者の状況を一般質問で確認いたしましたところ、避難者の安全確保などの観点から、避難者数は公表しないとの方針でした。","respondent":"古巻総務課長","answer":"昨年ご答弁させていただいた７名に加えて２名です。２件、支出しております。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのご相談を基に、昨年１０月の第３回定例会の一般質問と決算特別委員会で、区としての支援メニューの拡充というものを強く強く求めたところです。そして品川区としてやるべきことがあって、自治体によって差があったりばらつきがあったりしてはいけないのではないでしょうかというお話をしました。","respondent":"古巻総務課長","answer":"加えて生活支援につきましても、さらに半年延びて、プラスでさらに１年延長するというようなアナウンスが出たところです。なるべく早い時期にそういったことが実現できるように、今、最終的な調整をしているという状況です。","id":"exchange-065"},{"speaker":"あくつ委員","kind":"質問","question":"何月何日から開始されるのですかとも聞こうと思ったのですが、款が飛びますけれども、予算として来年度当初予算に何か計上されているのでしょうか。条例や要項等、どのような根拠によって使用料を減免していくのか、お知らせください。","respondent":"古巻総務課長","answer":"今、例えばウクライナ避難民の支援ということで一定程度の予算を計上していますので、その中で見込めるかと考えております。減免に関しては通常、そういったところを根拠に、支援を進められるかと考えているところです。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは、金融機関の口座をつくるときに在留カード等の本人確認書類と一緒に担当の人に見せるということを想定しているそうです。国が想定しているような、本証明書を活用するような、品川区独自の支援制度が既にあるのか、説明を求めました。","respondent":"古巻総務課長","answer":"こういった証明書があるので、それを掲示した場合のサポートを十分にお願いしたいということで、総務課からお願いしています。具体的な支援というよりは、サポートのより寄り添った対応ということを実現できているのかなと思っていますし、今後。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"提案","question":"それもご提案しようと思ったのですが、ご利用されるということだったので、ぜひ活用していただきたいということです。現在、聞き取りのニーズというのは、品川区にどのようなものがあるのか、区として課題と捉えていることは何なのかをお知らせくださいとの意見を述べました。","respondent":"古巻総務課長","answer":"基本的には日本語の対応というようなところも、手続の流れがよく分からない、それについては対応をしっかりできているのではないかと思っています。課題という意味でいうと…","id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう前から伺っているところですけれども、本当の支援のニーズというのはどこにあるのか、分からないのではないかというのが正直なところです。最後に伺いますが、別に区長や部長に答弁を求めているわけではないです、最後にお考えを伺って終わりたいと思います。","respondent":"古巻総務課長","answer":"今までも、寄り添った支援ということではお話をしていますが、そういった意味で、なかなか届きにくい地道な活動であることも事実かと思います。支援をさせていただいているということにつきましては、長期化してきている中で、その辺りは心がけて進めてまいりたいと思います。","id":"exchange-069"},{"speaker":"おくの委員","kind":"質問","question":"４３ページの社会保障・税番号制度システム整備費補助金に関わって、マイナンバーカードの取得についてお伺いします。伺います。","respondent":"吉野戸籍住民課長","answer":"品川区も任意になります。","id":"exchange-070"},{"speaker":"おくの委員","kind":"質問・要望","question":"受けられないというようなことはないと考えておられるのでしょうか。これは、もちろんそういうことを考えてはいけないと思うのですけれども、いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"委員ご指摘のとおり、国から、令和６年秋をめどに紙の健康保険証を廃止するという方針を発表されているのは、認識しています。マイナンバーカードが手元にない方に関しても保険診療等が受けられるということで、その際の手続に関しては今後国から示されるものと認識しています。","id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、国からこれから指示されるということですけれども、私がお伺いしているのは、品川区では、国の指示がどうであれ、今までどおり紙の保険証が使えるのかということをお伺いしたのですけれども、その点はいかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"今の段階では、資格確認証の発行等というところが考えられますけれども、詳細につきましては、今後、国から示されるものに沿って対応していくです。","id":"exchange-072"},{"speaker":"おくの委員","kind":"質問・要望","question":"他方で、品川区では任意ということを守っていくと答弁されました。どういう展開であろうが、品川区では任意だということを守っていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"宮澤情報推進課長","answer":"申請に基づいて交付されるものということで、この点は変更なく、これまでどおり保険診療は受けられると発表されているところです。マイナンバーカードが手元にない方の今後の取扱い、手続の方法等に関しましては、国から示される内容等を注視していくです。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"強く要望しておきます。その点、いかがお考えでしょうかということと、その対策はどういうふうにお取りか尋ねました。","respondent":"宮澤情報推進課長","answer":"取扱いに関して情報連携する上では、個人番号を直接使わず符号を用いるやり取りというような形で、セキュリティ対策を取っているところです。アクセス権のある職員につきまして２要素認証、職員証と手のひらの生体認証で、なりすまし防止等の対策を立てているところです。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問・要望","question":"情報漏えいの危険性は十分には払拭されていないと思います。マイナンバー制度の中止を求めて質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"小芝委員","kind":"質問","question":"私からは、７７ページの予防接種費に関連しまして、新型コロナウイルスのワクチン接種と接種をめぐる人権、また副反応についてお伺いいたします。お聞きしますが、品川区のワクチン接種状況、初回と３回目の接種率、６５歳以上の方々と２０代の方々の接種率について教えてもらえますか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３回目、６５歳以上の方の接種率は９２.３％、２０代の方は５３.３％という形になっております。この数字は、２月２８日現在のものです。","id":"exchange-076"},{"speaker":"小芝委員","kind":"質問","question":"今、２０代の方は３回目の接種率が５３.３％というお話を伺いました。さらに今後、この接種率の向上に向けて取り組むのかどうか、お答え願います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３回目接種が終わった方につきましては、旅行支援や、その辺りもホームページでうたいながら接種を進めている状況です。１つ、先日ではありますが、立正大学のキャンパスを使いまして、学生への接種を勧奨するような働きかけも行いました。","id":"exchange-077"},{"speaker":"小芝委員","kind":"質問","question":"当初からこの文言がホームページにアップされていたのかどうか分かりかねますが、この１文はとても大きいと考えます。その辺りを教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ワクチンについての説明については、モデルナ社のもの、中に説明書を同封してご説明に代えさせていただきました。予診票を基に、その方の体調を基に最終判断を致しますので、その辺りを含めた記載となっております。","id":"exchange-078"},{"speaker":"小芝委員","kind":"質問","question":"現状、品川区に、こういった人権侵害にもつながるようなケースの報告というのはなされておるのかどうか教えてください。報告を受けた場合の対応について教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"委員がご指摘のようなハラスメント的なものにつきましては、我々の耳には入ってきておりません。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、ワクチン接種の副反応について伺います。副反応のアンケートをいつ頃からアップし始めたのか、いきさつについて教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もともとは、港区で始められたアンケートでございました。協力して接種を南部で進めていこうという関係柄にもなりまして、より情報を集めていこうという流れの中での、アンケートの集計という形になりました。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問・要望","question":"副反応の統計も、これまでにおよそ全国で３万件と言われております。この報告を受けた方の症状について、分かる範囲で教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１つは心筋炎、申請が３３件上がっているうちの９件が、そういった方です。こちらが５件と報告が上がっておりまして、こちらは全て女性と聞いております。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問・要望","question":"仮に接種から５年を超えて、医療機関はこれに従い、５年で接種台帳や予診票などを廃棄してしまっているおそれも出てきます。万が一に備えまして、この接種記録を保存する期間を延長することを検討するべきではないかと考えますが、区の考えを教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"この記録は、５年で特に廃棄されるということではなく、ずっと記録・保存ができるものです。こうしたことによって、保存期限を区切ることなく接種記録を保存することが可能と考えております。","id":"exchange-082"},{"speaker":"小芝委員","kind":"意見","question":"保存期間を延長するという仕組みを改良することによって、保存できるという話を受けました。万が一に起こり得る健康被害から区民を守ることに寄与するものと考えますので、今後もお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"私からは、６４ページの人事管理費、７９ページ、商店街活性化事業費についてお伺いいたします。１点目に、人事管理費についてお伺いいたします。","respondent":"崎村人事課長","answer":"福利厚生、また各種研修に関する予算を、令和５年度も計上させていただいている予算です。","id":"exchange-084"},{"speaker":"横山委員","kind":"確認","question":"確認させていただきました。今までも努力していただいておりますけれども、どのように実現していくのかというのを、改めてお伺いできればと思います。","respondent":"崎村人事課長","answer":"ただ、例えば平日にしかできない用事や家事育児など、どうしても何か別の予定があるから取得するというのが多いのかなと認識しております。特に理由がなくとも、例えばリフレッシュ、体を休めるために取っていくものであるということを促進していく必要があると認識しております。","id":"exchange-085"},{"speaker":"横山委員","kind":"確認","question":"お伺いいたしますが、ご実感で構いませんので教えていただけたらと思います。休暇取得をしやすくするためにどのような働きかけを行っているのか尋ねました。","respondent":"崎村人事課長","answer":"例えば何か予定がないと休みが取れないと考えている職員が減ったというのを、昨年度が、例年７０％前後で推移しています。管理職が率先して年次有給休暇を取得することで、改めて、特に管理職の休暇取得について強い働きかけが必要であると認識しております。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"改めまして、リフレッシュ休暇やチャレンジ休暇を取っていただきたいと要望いたしまして、また年休の取得の促進をよろしくお願いいたします。２点目に、商店街活性化事業費についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"今回、イベントの実施がなかったというようなところもございまして、そちらが加速しているのかなと感じているところです。そういう部分も含めまして、区ではいわゆるエリアサポーター事業というものを令和２年度から実施させていただいているところです。","id":"exchange-087"},{"speaker":"横山委員","kind":"質問・要望","question":"小山のまち全体と武蔵小山商店街の継続性について、今後、区はどのように支援を進めていくのでしょうか。小山のまち全体を捉えながら、商店街の活性化と商店街を含めたまち全体の活性化を要望いたしますが、それぞれ区のお考えを説明を求めました。","respondent":"多並都市開発課長","answer":"現在は、小山三丁目第１地区・第２地区の２地区で、組合設立に向けて、地元の方は検討されているところです。やはり商店街の活性化と連携の方法というのは非常に重要な部分であり、賑わい軸の検討会など、まちづくりを進めていこうと考えているところです。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"私からは、５点まとめて、まず一括で、減額補正されている項目をお聞きしたいと思います。この理由をまず、お伺いしたいと思います。","respondent":"寺嶋福祉計画課長、櫻木生活福祉課長、菅野高齢者福祉課長、栗原河川下水道課長、勝亦学務課長","answer":"高齢者見守り相談窓口設置事業補助金の減額につきましては、その１つ上の１５節になるのですが、額を精査して移したものです。 生活困窮者支援費の減額についてです。住居確保給付金、令和４年度の見込額として４８０世帯を見込んでいたところですが… 私からは、７１ページの高齢者福祉施設支援事業、養護老人ホームについての分をお答えします。当初の見込みが８５人というところだったのですが… 私からは、下水道管改修事業の減額補正の理由についてご説明いたします。金額は少なくなりましたが…","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"１つずつお伺いしたいと思いますけれども、今、支え愛・ほっとステーションの業務の現状を確認させてほしいと求めました。そこを確認させてください。","respondent":"寺嶋福祉計画課長、菅野高齢者福祉課長","answer":"１点目は周知ですけれども、ふだん何も起きていないときに、その情報をキャッチしていただくということが大変難しいのかなと実感しております。各地区２名ずつ、本部４名ということで、この人数でしっかりやっていきたいと考えています。 私からは、養護老人ホームの入居に至るまでの経緯等についてご説明します。自立した６５歳以上の高齢者の方で、または低所得などの原因によって自宅で生活ができないなどの経済的な理由を持つ方が入所の対象となっております。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"その状況に応じて考えを持ってくださっているということが確認できましたので、どうかこれからも引き続き、どうか対応を引き続きしていただきたい。先ほど、２６４世帯でとどまったというところですけれども、利用される方の年齢別の実績は分かりますか尋ねました。","respondent":"櫻木生活福祉課長","answer":"それと、申請して却下になった件数ですが、こちらも通算で、大体２６件ぐらいになります。不備がありまして、必要な書類をご提出いただけずに、しばらく督促等を行ってもなかなかご反応いただけなくて却下になるというケースがあります。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"年齢別の状況をお伺いしたところ、今、課長もおっしゃってくださったように、若い世代の２０代から４０代の方の利用が多いという結果。どうなのかというところは、４月からまた要件が改正されていくといったところを見たときに、その辺を説明を求めました。","respondent":"櫻木生活福祉課長","answer":"こちらはご案内として、暮らし・しごと応援センターにご相談くださいという形で、引き続きのサポートをお示しするような形でご案内しています。暮らし・しごと応援センターでも様々、日々ご相談を受けていますので、そのような相談状況を見ながら考えていきたいと考えています。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"でも本当に増えている現状もありますので、区としては、若い人への対策をどうか考えていっていただきたい。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問","question":"子ども食堂については、現在、区内の数が３５か所にわたっていると伺っております。コロナ禍が３年もの間続き、アフターコロナはどのように子ども食堂の運営が変わっていくとお考えか、区の見解を説明を求めました。","respondent":"飛田子育て応援課長","answer":"今後の子ども食堂ということで、コロナ禍はどうしたらいいのかということで、２月の子ども食堂ネットワーク会議でも、そういうことで話し合いました。ですので、そういうところでもまたどのようにやっていくか、また情報交換等して模索していきたいと考えております。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"食事を提供している子ども食堂の数と、週１回、月１回など、１か月の実施回数を伺います。区は新規立ち上げ時に上限５０万円を補助していますが、今年度利用した事業者がいるのかを併せて伺います。","respondent":"飛田子育て応援課長","answer":"現在、休止中のところ５か所を除いた３０か所において、子ども食堂あるいはフードパントリーもしくは両方を実施しているというふうになっております。内訳としましては、フードパントリーのみを実施しているところが１５か所、そして両方実施しているところが１２か所になります。","id":"exchange-095"},{"speaker":"西村委員","kind":"意見","question":"新規立ち上げ時の補助もなかなか使われなかった中で、この商品券の配布は子ども食堂に大変好評です。商品券を配布するに至った経緯を説明を求めました。","respondent":"飛田子育て応援課長","answer":"コロナ禍や、原油価格や物価高の影響を強く受けているということで、子ども食堂におけるフードパントリー事業の追加支援という目的で行いました。支援をどのようにしていくものがよいかということで、こちらで子ども食堂ネットワークを通じて…","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"改めて、品川区の子ども食堂の目的を伺います。区のスタンスや考えを説明を求めました。","respondent":"飛田子育て応援課長","answer":"子ども食堂をやりたいという思いが強いところもあるし、また引き続きフードパントリーもやりたいという、様々な考え方があると思います。そういう考え方は受け止めながら、増えるような支援体制を、また今後も検討していければいいかなと考えております。","id":"exchange-097"},{"speaker":"西村委員","kind":"提案","question":"そこで、再度ご提案をします。区は子どもたちに広く周知していきたいと考えているのか、子どもが知る機会はほかにあるのか、伺いますとの意見を述べました。","respondent":"飛田子育て応援課長","answer":"子ども食堂の運営方法に関しましては、やはり子ども食堂の考え方、またやってみたいことなど、いろいろ思いがあります。そういうところも踏まえまして、いろいろなところで情報提供をしながら、また周知をしていければと考えております。","id":"exchange-098"},{"speaker":"西村委員","kind":"意見","question":"今後、様々な形態の子ども食堂が増えている今、区が子ども食堂をどういう場にしていきたいのかを改めて示すことが重要だと思っています。コロナが落ち着くと、居場所として食事を提供する子ども食堂が増えてきましたら…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"特別区民税と特別区財政調整交付金で約５９億円も増収となり、８３億円も基金に積み増しているのですから、予算がないわけではありません。既に世界では１００を超える国と地域が、消費税を５％に引き下げた場合、伺います。","respondent":"黒田財政課長","answer":"物価高騰対策支援ですが、令和４年度の第４号補正予算におきまして、国の交付金等も活用しながら施策を実施したところです。消費税５％の影響はですが、国税に関わることですので、区でそういったところの見解は持っていないところです。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"今まで国に意見を求めるべきだということで言ってきました中で、ぜひそうした見解があるのではないかと思いますが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"いわゆる消費税の中には、国税である部分と地方税である部分がありまして、地方税である部分は、地方消費税交付金として都道府県と市町村に配分されるということですから、当然、税率が変われば、そういったところに影響があるということは考えられると考えています。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"区の税収についての見解がありましたけれども、区民への影響という点での見解はありませんでした。消費税の５％への引下げが区民の暮らしを支えることになると考えないのか、伺います。","respondent":"黒田財政課長","answer":"そういう意味では、そこの財源が減ってくれば、様々な施策に影響があるだろうと認識しています。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区でも、ひとり親世帯に給付金を支給すべきではないでしょうか。伺います。","respondent":"櫻木生活福祉課長、飛田子育て応援課長","answer":"これまでも、区は住民税非課税世帯等に対して、臨時特別給付金のほか、物価高騰に対応する給付金を、着実かつ迅速に行ってきたところです。国でも今、経済対策という形で、また様々議論されているような状況かと認識しておりますので… 現在、ひとり親家庭につきましては、国の状況など、今、様々な思案もされておりますので、そちらを見ながら考えていきたいと思います。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"国の状況が出る前に、今既に区民の生活は大変な状況ですので、ぜひ区として独自に行ってほしいと求めました。そうなると、どのような状況になれば実施するという考えなのか、伺います。","respondent":"櫻木生活福祉課長","answer":"どのような状況かですが、基本的に国等の検討状況を踏まえて、実施するべきものは実施していくです。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ低所得世帯やひとり親世帯への区独自の給付金を行っていただきたいと、強く求めておきたいと思います。区内企業の８割を占める中小企業へ、区として独自に直接支援をすることが必要だと思いますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"中小系企業への支援策ですけれども、国で今、支援金を出しています。これまで運送事業者等燃料費高騰対策支援金など、中小企業の支援に当たってきたところですので、引き続き支援を進めたいと思っておるところです。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"区独自としてぜひやっていただきたいということで求めておりますので、ぜひ区民や営業を支援するという立場で実施してほしいと求めました。今回の課題は何か、伺います。","respondent":"長尾建築課長","answer":"今回の補正予算での減額については、半分ほどが緊急輸送道路沿いの耐震化に関する助成になっております。合意形成をつくったのだけれども計画の変更があったりと、話をよくお伺いしながら、都と連携して促進してまいりたいと考えております。","id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"私からは、４５ページにあります防災普及教育費についてお伺いいたします。５００万円とあり、この事業に対して補助金が出されているということですけれども、どのようなところにこの費用は使われているのか尋ねました。","respondent":"平原防災課長","answer":"防災普及教育費ですけれども、区が作成いたしますハザードマップの作成経費につきまして補助を頂くもので、今年度、防災地図を作ったうち、ハザードマップに係る部分を国費補助いただいたものです。","id":"exchange-107"},{"speaker":"木村委員","kind":"質問","question":"区では今回のハザードマップを更新したとのことですけれども、区民に対してどのように周知していくのでしょうか。そして、ハザードマップの意味も、６５歳以上の方、高齢者の皆さんは、どれぐらいこれを理解しているのか尋ねました。","respondent":"平原防災課長","answer":"見開き１枚のものですけれども、まずは新たなものを全戸配布することによりまして周知を図ってまいりたいと考えています。例えばですけれども、今週末３月１１日に開催の防災フェアといったところでも、そういった機会を捉えて周知を進めてまいりたいと考えています。","id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"あれば、何かお聞かせください。そして、もしできれば、高齢者の皆さんに本当に分かるように、そういうものが工夫できたのであれば、それも説明を求めました。","respondent":"平原防災課長","answer":"１枚の地図に地震と風水害を同じような形で掲載させていただいていたということで、分かりづらいというようなお声を頂いておりました。あるいは、災害から避難するときの考え方、情報学習面といいますけれども、そういったものを充実させていただいたところです。","id":"exchange-109"},{"speaker":"木村委員","kind":"質問","question":"そして、８３ページの下段にあります戸越公園駅周辺地区再開発事業からの質問を致しますけれども、戸越五丁目１９番地区です。減額の理由と現在の状況について説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"令和４年度は５階の床まで完成する予定です。今後のスケジュールといたしまして、事業認可当初、予定していた、令和６年５月の建物完成に向けて工事を進めております。","id":"exchange-110"},{"speaker":"木村委員","kind":"質問・要望","question":"これらの事業について、どのような事業なのか、お聞かせほしいと求めました。完成までにどの程度の期間が必要としているのかも説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"委員よりご質問いただきました説明会の内容および計画スケジュールについてお答えします。工事の期間を１１年と、予定しておりますので、工事完成まで現在から約１４年後と予定しております。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問・要望","question":"安全に、区民のためにもよい工事をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"芹澤委員","kind":"質問・要望","question":"６５ページ、品川区全体のにぎわいについてお伺いしていくのと、時間が余れば６９ページの住民基本台帳関係費について伺っていきます。それを高められるようなイベントをしてほしいというようなお声も、まず区として、これからのにぎわい創出の意義についてご見解を説明を求めました。","respondent":"川島地域活動課長","answer":"令和２年度・令和３年度は、今年度は幸いにも５つの地域センター管内で、６会場で実施できました。お子さんが集まるイベントの重要性ということも再認識されましたので、地域の活性化、にぎわい創出の部分を進めていければと思ってあります。","id":"exchange-113"},{"speaker":"芹澤委員","kind":"提案","question":"私の提案としては、これは２０１８年に濱野区政の中で、スクエア荏原で手形を押すというイベントをやりました。区民全員でギネスブックにチャレンジするというのは、１つご提案なのですが、いかがか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"東京２０２０オリンピック・パラリンピック大会の、しながわ文化プログラムの一環として、スクエア荏原で２０１８年に実施したところです。心を込めて記していただいたということで、心を１つに結びつけて、そういう取組ということで付加価値をつけて実施したものです。","id":"exchange-114"},{"speaker":"芹澤委員","kind":"提案","question":"周知不足があったのではないかというような１つ指摘があって、これはまた私からの提案でありますが、区民アンケートというものがあります。同じく、これは子どもたちの心を手形でつないでいくというようなイベントをぜひご検討ほしいと求めましたが、ご見解を説明を求めました。","respondent":"山崎文化スポーツ振興部長","answer":"それから、ギネスに挑戦という１つの目標に向かって心が１つになるといったところは、いろいろな意味で意味のあることだと思うところです。様々、区全体の中で検討させていただき、実施してまいりたいと考えるところです。","id":"exchange-115"},{"speaker":"芹澤委員","kind":"質問","question":"せっかく全区民に送るものですから、まさに継承と発展ということで、新たなイベントとしてぜひ挑戦ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"木造住宅の耐震化は非常に喫緊な課題ですけれども、その辺りの実績がどうだったのか。もう少し詳しく教えてほしいと求めました。","respondent":"長尾建築課長","answer":"それに伴いまして、もともと積んでいた金額のうち２,６００万円を補正で減額しているという状況となっております。耐震化支援事業につきましては、２月末時点ですけれども、およそ１００件ほどが申請されているというような状況となっております。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"意見","question":"それでも、かなり大幅な減額ということで、引き続き、しっかりとお願いしたいと思います。どのような感じでやっていくのか、その辺をお知らせくださいとの意見を述べました。","respondent":"長尾建築課長","answer":"今年度実施しました戸別訪問につきましては、３町丁目回っておりまして、二葉一丁目・二丁目、東大井六丁目を訪問いたしました。来年度につきましては、同様の内容で、場所を変えまして、旗の台五丁目、また中延四丁目・六丁目の３町丁目を回る予定としております。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"質問","question":"それとも、その地域の中で木造の住宅だったら、そこを、あまり築年数関係なく回るのか。どんな感じでやっていらっしゃるのか尋ねました。","respondent":"長尾建築課長","answer":"戸別訪問の訪問対象の住宅につきましては、あらかじめ東京都で持っている、建物の現況調査のデータなどを活用しまして、昭和５６年５月以前に建てられた旧耐震基準の木造の住宅を対象として訪問したところです。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういうご要望を頂いておりましたので、以前質問したときは非常に厳しい状況だったのですが、先般のご答弁では非常に前向きなお話がありました。２０００年のところまでも、そこも枠を広げてやっていくということも柔軟に検討してほしいと求めましたが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"区としましても、今後の２０００年までに建築された新耐震の木造住宅に対しての耐震改修の支援というところは検討していきたいと考えております。いろいろと周知にも力を入れてきておりますので、またそういった制度が整いましたら…","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ぜひ、よろしくお願いします。やはりこういう時を１つの契機として、戸別訪問しながら取り組んでほしいと求めましたけれども、もう一度ご決意をお願いします。","respondent":"長尾建築課長","answer":"耐震化支援事業につきましては、品川区で言いますと平成１６年からスタートしておりまして、およそ２０年ほどたっております。東京都の新しい支援事業の内容を含めまして、区内の耐震化を進めて、より被害を軽減していけるように尽力していきたいと考えております。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"意見","question":"６２ページの財政管理費、６４ページの新庁舎整備費から、特に新庁舎整備基本計画についてお尋ねします。このような経過において、改めて前年度の最終補正で積立てが分かっていれば、どうして当初予算に３０億円計上しなかったのかお尋ねしますとの意見を述べました。","respondent":"黒田財政課長","answer":"各歳出予算を、それにかかる経費というところで、財源ということで特定財源を充てていくというところで積み上げていくという作業があります。当初予算にどのぐらい庁舎の基金積立てができるかといったところで、令和４年度については５億円の予算を計上させていただいたです。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和４年当初でも、令和４年度当初で、それぐらい積み上げることが可能だったのではないでしょうか。見込みを持って庁舎整備基金を積み立てようとした、令和３年度、そして令和４年度の状況は少し疑問があるのですが、それについていかがか尋ねました。","respondent":"黒田財政課長","answer":"令和４年度の最終補正予算で２５億円ほど積立てしておりますけれども、また歳出の減額によりまして、財源が出てきた部分もあります。２５億円計上したということでございまして、ここにつきましては、確実に財源を見込めるものについて予算化しているというものです。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、公共施設整備基金積立金の補正が約２０億円計上されています。こちらの基金の将来的な充当計画があれば説明を求めました。","respondent":"黒田財政課長","answer":"基金を繰り入れたりというところで対応しておりますので、一般財源で対応するかというのは、予算編成については対応してまいりたいと考えています。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"新庁舎整備基本計画の財源計画にある起債については以前から質問させていただいていますが、見込みが立たない状況と私は考えています。庁舎整備基金の積立てを優先させ、つまりもっと増額をするべきではないかと思うのですが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"こちらは様々な公共施設の老朽化の改築等に対応しておりますので、積立てが必要だと考えておりまして、使ってしまいますと全てなくなってしまいます。そういった意味では、財源に余裕があればそちらも積み立てるといった形で…","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"次に、庁舎整備計画事業と住居表示に関する条例との関係についてお伺いします。現行の区役所の住所の広町２－１－３６になじんでいるということで、どのような決め方をいつ頃していくのか、お伺いします。","respondent":"山下新庁舎整備課長","answer":"ただいまご質問いただきました、位置に関する条例についてです。設計が進んでいく段階で、住所地の付番が成ります段階で、また議会にお諮りしていくことを考えてあります。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ほかの自治体だと、竣工の５年ぐらい前には、いわゆる位置条例を議会にかけたりしています。こういうところでこうやってやっていくという、きちんとした形をやってほしいと求めましたが、いかがか尋ねました。","respondent":"山下新庁舎整備課長","answer":"第二庁舎においては広町二丁目１番３６号を拡張したというようなお話ですけれども、今回予定しておりますのは、難しいのかなと思ってあります。位置に関する条例を上程する時期につきましては、やはり適切な時期にしっかりと上程していきたいと考えています。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"では、適切な時期ということですが、できるだけ早く、きちんとした議論を議会でするべく提出してほしいと求めました。議会の中でしっかりと議論をしていくと思っていますが、その点、いかがか尋ねました。","respondent":"山下新庁舎整備課長","answer":"ただいま委員からもご案内がございましたとおり、各自治体におきまして庁舎を設置する段では、位置に関する条例と定めております。議会審議を経てこちらを定めていく形になりますので、適宜適切なタイミングで議会に上程できるよう、こちらとしても努力を続けてまいります。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"時間がないのですが、そのために必要な議決はどれぐらいでしょうか。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問","question":"６５ページ、地域振興経費、７９ページ、商店街にぎわい創出事業、８５ページ、高層マンション対策リーフレット作成等経費についてお伺いいたします。お聞きしたいのは、担当の課長に、昨日見たことで率直な感想をお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"源氏前小学校で行われました小学生マラソン大会についてですが、あれは開催が５年ぶりということのようです。昨日は６００人ぐらいの参加者だったということで、私も同じ気持ちで、楽しい気分で帰ってまいりました。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１つお伺いしたいのが、この３９回ずっと、令和６年度から工事が着工するということが予定ではあると思うのです。来年はどうなるか分かりませんけれども、どういうお考えか、ご見解をお聞きしたいと思います。","respondent":"川島地域活動課長","answer":"今回５年ぶりにやったということで、会場がどこかという選定から含めてしっかりできると思いますので、その辺は温かく見守っていただければと思います。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これもやはり継続していただくのが私の要望なので、ぜひとも早い時期から検討してほしいと求めました。それについて、まず最初にご説明をお願いしたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"品川区と大田区は、例えば東急電鉄などによって、まち、商店街がくっついて、あるいは近隣で形成されているような状況があります。両区の観光協会が連携しながら、相乗効果を狙って回遊性を高めてというようなことで、現在実施している事業です。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"旗の台も近く、荏原限定とすると、来場者数も逆に限られてしまうのではないかと私は思っております。お考えをお聞かせほしいと求めました。","respondent":"山崎文化スポーツ振興部長","answer":"それから１つ、間をつなぐ商店街の回遊性を高めるために、謎解きウォークなどの事業も一緒に同時並行で実施しました。今、上手に皆さんに参加していただけるような方向で、様々検討してまいりたいとは思ってあります。","id":"exchange-133"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ですから、先ほどの大田区とやっているようなイベントができたらいいのかなと私は思っていますので、これは要望として入れてほしいと求めました。続きまして、８５ページ、高層マンション対策リーフレット作成等経費についてお伺いいたします。","respondent":"平原防災課長","answer":"高層マンションにおけるフラッシュオーバーにつきましては、高層マンション特有の現象といいましょうか、火災時の要注意事項の一つだと認識しております。","id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"質問","question":"火が出たのは１７階で、その上の１０フロアに住む人は全く気づかなかったらしいのです。高層マンションに関していうと、リーフレットの中に「フラッシュオーバー」という用語というのですか、そのことについてお伺いしたいと思います。","respondent":"平原防災課長","answer":"今ご指摘のございましたフラッシュオーバーをどのような形で位置づけるかですけれども、こちらは、ご指摘のとおり、高層マンションにかかわらず懸念される事項ですが、こちらの具体的な書きぶりについては、東京消防庁と連携しながら工夫してまいりたいと考えています。","id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"意見","question":"中高層マンションが８００棟あるという、安全啓発の観点からも、足りない可能性も本当に多々あると思います。低層マンションも含めてご検討をお願いしたいと思いますので、そのご見解をもう一度お願いしたいと思いますとの意見を述べました。","respondent":"平原防災課長","answer":"今回の事業の見直しに伴いまして、対象とするマンションですけれども、改めて、今、検討し直しています。１０階建て以上といったところを対象とさせていただきましたけれども、今、検討を進めているところです。","id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それから５１ページの新型コロナウイルス感染症緊急包括支援交付金に関連して新型コロナウイルス感染症対応地方創生臨時交付金について伺いたいと思…それから、４３ページの生活困窮者自立支援事業について伺います。","respondent":"竹田住宅課長","answer":"過去５年ということですので、平成２９年度からご説明いたします。この制度は、そもそも２月２８日までで終了することを予定しておりますので、２月上旬を受付期間満了としております。","id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補正予算を組んで、これを希望する方が２月２８日まで申し込めるようにぜひしていただきたいと思うのですけれども、いかがでしょうかということです。中小事業者の経済を循環させるためにも、ぜひとも補正を組んで希望者全員が受けられるように求めますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"申込み予定終了日前に、平成２９年度や令和２年度のように、予算残があった年度もあります。今後も執行状況を確認しながら適切に対応してまいります。","id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"しかるべきときに公表するということで、計画の公表はしないのか、その点についても伺います。品川区にはおよそ７億円ぐらいという報告だったと思うのですけれども、現時点で地方創生臨時交付金が幾らになっているのかも伺いたいと思います。","respondent":"黒田財政課長","answer":"公衆浴場への支援金、社会参加支援事業や運送事業者燃料費高騰対策支援、商店街装飾灯維持支援金ということで。事業の実施がなかなか難しいところもありますので、こちらの交付予定としては、１億４,７００万円ほどが交付される予定だと。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そうしますと、４回目の一億四千数百万円が、これから使える臨時交付金ということになるのでしょうか。ひとり親家庭への給付金や、住民税均等割世帯への支援を求めたいと思いますが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"は全体的な執行状況もありますので、そういった中で適切に、臨時交付金については財源として活用してまいりたいと考えています。そういったところもしっかり区として取り組んでおりますので、様々使える事業の中で、物価高騰対策というところで事業を編成したというものです。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"改めてぎりぎりのボーダーの方々への支援もぜひともやっていただきたいということで提案していますので、ぜひご検討ほしいと求めました。３つ目に、生活困窮者の支援について伺いたいと思いますとの意見を述べました。","respondent":"櫻木生活福祉課長","answer":"社会福祉協議会が実施している生活福祉資金のうち緊急小口資金につきましては、総合支援資金につきましては、合計で１万９３０件。１２億６,７１３万円、再貸付けが３,１３５件、１５億９,１０６万円と伺っております。","id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう時間がなくなってしまって、これ以上質問できないので、態度だけ申し上げたいと思います。第１号議案、３年にわたるコロナ禍に加えて物価高騰によって多くの区民が追い詰められているにもかかわらず、反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"若林委員","kind":"提案","question":"私は、４０ページの特別区たばこ税、歳入のほうですか。それがギネスに認定されるぐらいのことをやりましょうという提案をして、採用されるかどうか分かりませんけれども、そういうことを申し上げましたとの意見を述べました。","respondent":"提坂税務課長","answer":"これが令和４年１０月に終了したということで、これに伴う増税を見込んだ方の駆け込み需要というのが見込まれたということで、たばこ税について補正を組んだです。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"西口のコンテナ型の喫煙所の定員を、まず教えてほしいと求めました。やはり最初が肝心だと思いますので、その辺は今どういうふうに西口について対策を考えておられるか、一言お願いいたします。","respondent":"森田生活安全担当課長","answer":"大崎駅西口のコンテナ型喫煙所につきましては、現在、工事中ですが、１０名を予定しております。大崎西口の喫煙所につきましては、コンテナ型にプラスしまして、加熱式喫煙の方もできるようなエリアも設ける予定です。","id":"exchange-145"},{"speaker":"若林委員","kind":"質問・要望","question":"歩道・道路側というのですか、どのような違いが何かあるのか、ないのか。要するに、ポイ捨て条例の適用内とか外とか、その辺を精査していただきたいと思うのですが、お考えがあればお願いいたします。","respondent":"森田生活安全担当課長","answer":"大崎駅西口の喫煙所の周辺につきましては、指定地区ということで、路上喫煙禁止の場所です。指定喫煙所の中については当然喫煙できますが、路上につきましては規制にかかるところですので、ここで吸うことは当然、禁止になっております。","id":"exchange-146"},{"speaker":"若林委員","kind":"意見","question":"そうすると、今、敷地内はあまり規制がないというようなお話で、そうすると、コンテナに入れない人が道路の間の敷地内の足跡に立ったときに吸ってしまうという懸念のことを申し上げているので、ではもう一言お願いいたしますとの意見を述べました。","respondent":"森田生活安全担当課長","answer":"これは、足跡マークと同じように表示物として、並び列での喫煙はできませんという表示もしますのと、あと、２か月の間、整理・誘導につきますけれども、そのときにしっかりとルール化を図っていきたいと考えています。","id":"exchange-147"},{"speaker":"渡部委員","kind":"質問・要望","question":"６４ページは人事管理費で、６３ページは国際友好都市交流事業、８６ページで教育指導費の中で伺っていきますが、教育指導費のところから聞きます。それに向かって何かやってほしいのですけれども、現状を説明を求めました。","respondent":"中谷指導課長","answer":"コロナが明けて、これまでと同様の形で、当初予定ということで宿泊事業を実施して継続していきたいと考えています。今後、地域の関わりを継続して発展していくという意味においては、人選も含めた上での支援を教育委員会としてはしていきたいと考えています。","id":"exchange-148"},{"speaker":"渡部委員","kind":"質問","question":"総務課、この辺何かあれば教えてほしいのと、そうしたら少しほかの国と何かできることをやっていくというのをそろそろ考えてほしいなとも思います。いわゆる人との交流というところも含めて考えていく時期なのかなと思うのですけれども、その辺、ご見解を説明を求めました。","respondent":"古巻総務課長","answer":"今年派遣で語学研修を予定しておりますけれども、説明会に２００人ぐらいの方がいらっしゃったということで、校長枠が１５人。頂いたご提案も含めまして、今後の展開についてはいろいろと検討はさせていただきたいと思います。","id":"exchange-149"},{"speaker":"渡部委員","kind":"質問・要望","question":"それは分かるのですけれども、ただ、ライフプランの変更というのは大きいのと、予算書も確認しました。その中で、困る人たちがいた場合、それを助ける仕組みというのは、やはりどこか必要なのではないかと私は思うのだけれども、どうなのか尋ねました。","respondent":"崎村人事課長","answer":"課長補佐として、では１係長級として働けるのかというと、なかなか難しいというのも人事課としては認識しています。これからどういったところで活躍いただけるか、その方の６０歳以降の働き方については、丁寧に寄り添って考えていきたいと考えております。","id":"exchange-150"},{"speaker":"渡部委員","kind":"質問・要望","question":"新たな制度が生まれるわけですから、ここは本当に丁寧にやっていただかないと。五十六、七歳の連中が一番困ると思いますので、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"６４ページ、４０ページ、特別区財政調整交付金について伺います。こちらの実施費用なのですけれども、どの程度かかったのか、お伺いいたします。","respondent":"中谷指導課長","answer":"ＩＣＴの活用状況のアンケートということですけれども、こちらに関しては、指導課の特色ある教育活動経費の予算の中で１５０万円の予算を取りまして、実質は８５万５,０００円ということで支出をする見込みとなっております。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問","question":"どうなのかなというところがあったので、引き続きここを少しお伺いしたいのですけれども、せらく委員から。先ほどのご答弁というのは、文部科学省からの通知に対してもそごを来しているのではないかと思いますが、ご答弁はいかがか尋ねました。","respondent":"勝亦学務課長","answer":"やはり紙が欲しいという意見の保護者の方もいたというような状況の中で、例えば紙と電子、両方をお送りしますというような対応を取っている学校。そういった学校でも、それぞれ保護者の状況を確認した上で対応を取っているという状況です。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問・要望","question":"そこの対応を求めているところなのですが、今ご答弁があったのが、学校と保護者の間でそういうやり取りをしていると聞いているという話かと思います。せっかく令和４年度ＩＣＴ活用状況に関する保護者アンケートというものが行われているというところなのですけれども、今、お伺いいたします。","respondent":"中谷指導課長","answer":"約２０項目で、お子様の主にご家庭での端末の活用状況や見解、そして端末の活用についてお子様に今後期待することなどを伺うものとなっています。その中で、３者の意識が同じようなものになるのか、このアンケートの趣旨となっております。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問・要望","question":"今申し上げたような、保護者に対して、では連絡手段として望まれているのかというアンケートを別途取ることを要望したいと思います。これは目的としては、ではどういうふうに具体的にこれから前に進んでいくのかというところが、これはどういうふうに活用していく方針か尋ねました。","respondent":"中谷指導課長","answer":"早速にもっと学校での取組状況というのを広めていきたいと思っておりまして、学校としては授業公開を、コロナも明けてくる中でもっとやっていく。１１月にＩＣＴ ＳＹＭＰＯＳＩＵＭを行っておりますので…","id":"exchange-155"},{"speaker":"松本委員","kind":"質問・要望","question":"自由記載欄もないし、では、なぜ活用できていないかという保護者の意見を問うような、なぜの質問がなかなかないというふうなことがありました。なぜ今活用できていないかということについて、保護者から意見を聞くような項目を入れてほしいと求めましたが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"教育委員会の判断で、学校から申請があったものについては許可をするというような形を取らせていただいております。そのような場で、ご案内が不足しているものであれば、必ずすぐフィードバックするなどの方法を用いながらやっているです。","id":"exchange-156"},{"speaker":"松本委員","kind":"意見","question":"知らないという方もいらっしゃるので、きちんと周知をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問・要望","question":"８３ページ、７７ページ、聞けるところまで伺います。今後またパンデミックなども予想されますので、そういう配慮はぜひ検討していただきたいのですけれども、いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"ただ、一般的な区民の方にどういう形で周知していくかというのは、もう少し工夫の余地があるのかなとは認識しております。そのようなお話があった場合は、そのような状況で、また検討してまいりたいと思います。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろな数字も確認させていただきましたが、やはり広報で、年代層によってどういう広報を受け止めやすいかというのは違ってくるのかなと思います。ぜひその辺、ご見解を伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"広報につきましては、広報しながわ等を通じて、これからもしっかりと周知を行っていければと考えています。原則はそのようなことですが、ご提案できるようなところがあれば提案をするように、また指導してまいりたいと考えています。","id":"exchange-159"},{"speaker":"吉田委員","kind":"提案","question":"具体的・客観的に資産がどの程度というのは、私も提案は持ち合わせていないので、ぜひこれは検討していただきたいという要望にとどめたいと思います。その中で、感覚的に２,５００万円で何とかなりそうかなという事例かどうか、伺いたいと思いますとの意見を述べました。","respondent":"川崎障害者施策推進課長","answer":"近隣のグループホーム運営法人等に、郵送やファクスも含めまして、障害者グループホームの整備費補助については広く周知する予定です。障害者グループホームの整備を進めていく上で、ホームページ上でこういった団体を紹介・周知していくということも、検討したいと考えておりま…","id":"exchange-160"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどの午前中の質問について、その助成金を区民が必要としている助成金に使うべきではないのですかということを伺いたかったのです。書いていないのだったら、区としてそういうものも助成金の対象にしてほしいと要望してほしいという趣旨の質問だったのですけれども、見解を伺います。","respondent":"鈴木都市計画課長","answer":"以前のお問合せを頂いた際に、防音工事助成の対象になるかどうかについても併せてご回答させていただいているところです。区としましては、引き続き様々な騒音環境軽減に向けた取組を、国にはしっかり求めていきたいです。","id":"exchange-161"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、私たちとしては、それがどうか確認できないということですよね。もし、区民のそういう要望に応えられるような項目を入れてほしいということを要望してほしいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"繰り返しになりますが、こちらの要項において、周辺環境の補助対象になっているかということに関しては、なっていないです。様々使いやすい形で、航空機騒音防止法だけではなくて様々な形で助成制度を行っていただけるように、国には引き続き求めていきたいです。","id":"exchange-162"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ要望していってください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-163"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、７７ページ、感染症対策事業から新型コロナウイルス感染症対策の類型変更と感染予防対策についてお尋ねいたします。政府のこの２類相当から５類に移行するという決定に対する品川区のご理解と今後の対応について、簡単にご説明をお願いします。","respondent":"坂野保健予防課長","answer":"５類への移行と区の対応というお話です。機動的に対応できる体制を維持していくという、これは東京都の方針なのですが、これに準じた形で品川区もやっていきたいと考えております。","id":"exchange-164"},{"speaker":"大倉委員","kind":"提案","question":"７９ページ、７７ページ、学校ＩＣＴ活用経費で伺えればと思います。提案したことがあるのですが、アプリ等を使わずＬＩＮＥを使っている、この検討状況について説明を求めました。","respondent":"菅野高齢者福祉課長、平原防災課長、中谷指導課長、山崎文化スポーツ振興部長","answer":"令和２年度には、介護サービス業務継続支援金や、区ではいろいろな形で施設の支援をしてまいったところです。感染状況等を踏まえながら、今後も動向… 民間アプリというような形で考えてきたところ、今、進めさせていただいているところです。そのような中で、例えばマンション対策、それから防災地図… ＩＣＴについてお答えします。やはり教員の指導力というところをもっと上げていくというところになろうかと思いますが… 連携の部分というのを検討していたところもありまして、様々なことをやれた部分と…","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"より安心安全な、災害時に使えるようなものにしていってほしいと求めましたが、ご見解を伺いたいと思います。ホームページ等を見ると、好事例が出ていたりするのですが、そうした学校間での共有みたいなことはどのようにされているのか尋ねました。","respondent":"平原防災課長、菅野高齢者福祉課長、中谷指導課長","answer":"さらに見やすくするために、電子ブック化などを含めまして、その地図データを使って様々なことに使えるような形で工夫してまいりたいと考えています。 今現在はそういったものが市場に出回っておりますので、各事業者で購入していただいているというところで認識しているところです。… 現在、各校で１取組の優良事例というものをまとめておりまして、それらを全て集約した事例集というものを作成していく予定になっております。…","id":"exchange-166"},{"speaker":"大倉委員","kind":"提案","question":"様々、しっかり応援していただければと思って伺いましたので、ぜひよろしくお願いいたします。さらに私も研究、いろいろ提案できるようにしていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-167"},{"speaker":"石田委員","kind":"質問","question":"私は、９７ページからの、国民健康保険事業会計、そして後期高齢者医療特別会計、介護保険特別会計の３つをまとめて伺っていきたいと思います。それで、これだけマイナスする額に開きがあるというのはどういうことなのか、ばらつきの理由を伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"医療費の伸びを多く見込みを立てたところ、法定外の部分に３億円ということで、かなり減ったという形になっております。令和２年度につきましても、決算時に繰越金が多くなったりするというようなことで、法定外のほうが減るというようなことです。","id":"exchange-168"},{"speaker":"石田委員","kind":"質問・要望","question":"私たちは引下げとともに、子どもの１８歳までの国民健康保険料の無料化も求めてきましたけれども、区は。これは区独自で引下げや無料化ができるという認識に立っていただいたということでいいか尋ねました。","respondent":"池田国保医療年金課長","answer":"国民健康保険の賦課に関することにつきましては、国民健康保険法で決まっておりますので、一自治体が変えることはできません。ですので、賦課と減免との違いがありますので、その辺をご理解いただければと思います。","id":"exchange-169"},{"speaker":"石田委員","kind":"質問・要望","question":"そして、７５歳を超えても働くという状況を、区としてどのように捉えられているでしょうか。伺います。","respondent":"池田国保医療年金課長","answer":"先ほどの国民健康保険料につきましては、賦課については国民健康保険法で決まっているということでご説明をさせていただきました。２割負担になる方がいらっしゃるということですので、意外に３割負担の方も多いということで、収入がある方は把握しています。","id":"exchange-170"},{"speaker":"石田委員","kind":"質問","question":"さらに物価高騰もあるわけで、７５歳以上になっても働くということは、年金だけではやっていけないということではないかなと。そういう状況が高齢者の中にあるという状況だと思わないのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"というところで、実際の収入と保険料は一致するかというと、そうでもないところはあります。年金収入だけで５割だけ働いている方ということも、収入の少ない方ということでの把握をしています。","id":"exchange-171"},{"speaker":"石田委員","kind":"質問・要望","question":"そこを進めていただきたいのに、最終の補正予算では軒並みマイナスという状況ですので、マイナスではなく繰入れこそするべきだと求めたいと思います。改めて介護保険の改悪に反対してほしいと求めましたけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"審議会等で、来年度第９期の介護保険事業計画についての方針等、いろいろと審議している最中です。そして区でニーズ調査等を行ったり、あと区の中での需給推計等も今後出していく中で、適切な介護保険料を決めていきたいと考えているところです。","id":"exchange-172"},{"speaker":"石田委員","kind":"質問・要望","question":"もう史上最悪の介護保険改悪だと言われておりますので、ぜひ負担軽減、そして利用しやすい制度の充実へと求めていってほしいと求めました。国民健康保険事業会計第３号議案、後期高齢者医療特別会計第４号議案、介護保険特別会計に反対の態度を表明して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-173"},{"speaker":"塚本委員","kind":"質問","question":"これは２つ併せて、これについて伺いたいのと、８１ページの第二戸越幹線整備工事について伺いたいと思います。今度４月からの新入生の子たちの入学手続が進められているというところなのですけれども、最初に、どういった実態になっているのか説明を求めました。","respondent":"勝亦学務課長","answer":"新７年生を含めて、大体６,０００人になろうかと思いますけれども、就学の指定というものをご住所地に郵送するような形を取ってあります。転校等に当たりましても、添付書類や選考に当たっての面談等を行う状況がありますので、紙で対応しているような状況になってあります。","id":"exchange-174"},{"speaker":"塚本委員","kind":"質問","question":"あるいは今、行政のデジタル化というところでオンライン化とか、こういう対応というのはできないのでしょうかというお話を聞きました。これについて、教育委員会としてのご見解を伺いたいと思います。","respondent":"勝亦学務課長","answer":"手続に関わるデジタル化など、利便性の向上は重要な課題だと考えています。添付書類といったものを、業務フローの見直しややり方の見直しの研究を重ねまして、利便性の向上に努めてまいりたいと考えています。","id":"exchange-175"},{"speaker":"塚本委員","kind":"質問・要望","question":"これはもっと簡単にできるのではないですかとか、オンラインやスマホでできるのではないですかとか、中で共有してもらえばいいのではないですかとか。これはもうすぐなるんですとか、これについてご見解を伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"手続に関しては全ての手続を令和７年度末までにオンライン化するという目標の中で動いているというものです。分かりやすい形で公開していくような形は工夫していきたいと考えております。","id":"exchange-176"},{"speaker":"塚本委員","kind":"質問","question":"併せて、第二戸越幹線整備工事ですけれども、１６億６,５００万円の減額ということになっております。この減額理由についても、併せて伺います。","respondent":"宮澤情報推進課長、栗原河川下水道課長","answer":"手続のオンライン化につきまして、手続の洗い出しというのを行いまして、中には課題のある手続等もあるというのは認識しております。その辺の課題を一つずつクリアしながら、手続をオンライン化していくです。 延長約１kmの下流部シールド工事におきまして、ＪＲ東日本と協議したところ、シールドマシンの発進を４月から９月に変更いたしました。なお、本工事は、令和２年から令和５年までの４か年にわたる債務負担工事でございまして…","id":"exchange-177"},{"speaker":"塚本委員","kind":"質問","question":"これが、遅れを取り戻して、当初の予定で計画されていたとおりにスケジュールどおり完成するのか。公園を押さえて、そこが元どおり戻る日というのは地域の方も期待しておりますので、そこについてお伺いしたいと思います。","respondent":"栗原河川下水道課長","answer":"マンホールの築造や目黒川への雨水のはけ口の設置を行いまして、トンネル内の仕上げの工事と特殊人孔を同時期に行うなど工夫いたしまして、令和６年度末の完成を見込んでいるところです。","id":"exchange-178"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先に７３ページの３款民生費、２項児童福祉費、それから４０ページの９款特別区交付金の２点についてお聞きしたいと思います。これは単純に新設がなかったということなのでしょうけれども、申込み状況など、その辺の関係をまず説明を求めました。","respondent":"中元保育支援課長","answer":"申込みの状況は、それほど大きく減ってはいないのですけれども、ただ、少し定員に空いているところができているというところです。それも、でもエリアによって、まちまちなところはあります。","id":"exchange-179"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川区は私立保育園の申込みを今、募集していないというか、受けていないという感じで捉えていいのでしょうか。今の、少し空きが出ているという中で、地域的には例えば第一京浜国道から海側ですか、東品川方向、また南大井。","respondent":"中元保育支援課長","answer":"保育園の今後の考え方ですが、０歳児の方のところが、コロナの影響もあってか、少し空いているところもあります。一時預かりに対して保育園での補助メニューが出てまいりましたので、今後は地域の中の子育て支援拠点として進めていければと考えているところです。","id":"exchange-180"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これがまだ令和５年度の調整がついていないということで、品川区に令和５年度に入ってくる予算というか現金、どういう状況になってくるのか。時期的にどうなってくるのか、まず確認をさせてください。","respondent":"黒田財政課長","answer":"第２回都議会定例会までに都区合意して、都の第２回定例会で条例が改正されれば、８月に当初算定がされるというような流れになるです。過去の事例といたしましては、昭和５１年度から５４年度に、都議会第２回定例会で都区合意して条例が改正されたという例があると聞いてありま…","id":"exchange-181"},{"speaker":"鈴木（真）委員","kind":"確認","question":"品川区に限らず２３区では、確認させていただきたかった点があるのですけれども、都議会として財政調整というのはどう捉えているのか。その辺で、都議会経験者として、どんな感じだったのかというのを教えていただければと思うのですが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"都側は４４.９％ということになりますから、特別区の児童相談所の設置については、いわゆる今回の財政調整協議の都側の考え方です。","id":"exchange-182"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"しっかりと東京都に対して要望して、０.１％、逆に言えばそれをもっと増やしてほしいというのを私どもも思っています。区の財源を確保するためにも、ぜひ区長のご努力をこれからもどうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-183"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":134880,"voices":414}},{"id":"r05-20230307-3","meetingId":"r05-c-budget","date":"2023年3月7日","dateIso":"2023-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"地域生活支援事業についてお伺いします。地域生活支援事業ほか５事業、補助基本額とありますが、この中にペアレント・トレーニングは含まれているのでしょうか、説明を求めました。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおり、ペアレント・トレーニングはこの中に含まれております。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"ら・るーとのように、オンラインでの受講はされる予定なのでしょうか。ぜひ広く受講していただけるように、オンラインでの実施を行っていただきたいという要望を込めて、区のご見解を説明を求めました。","respondent":"松山障害者支援課長","answer":"来年度から品川児童学園で実施します、協議、調整しています。委員のおっしゃられるオンラインでのメリットも含めまして検討しています。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問・要望","question":"「なぜ」という疑問への答えや、心ない言動やいじめ、二次障害などを防ぐことへとつながると思うのです。強く要望するとともに、どのようなお考えをお持ちなのか、ぜひお聞かせいただけないか尋ねました。","respondent":"松山障害者支援課長、矢部教育総合支援センター長","answer":"よりよい対応で行うために、障害者支援課のほうで、品川福祉カレッジで支援者向けに講演会を実施したところです。支援者向け、あるいはどのような周知が効果的なのかは検討しまして… 市民科を中心に日々の指導に努めてまいりますが、発達障害等の対応につきましては、特別支援学級の自閉症・情緒障害の中学校の部において。特別支援教室につきましては、特別支援教室の実際の支援のあり方について…","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"諸収入の雑入についてお伺いいたします。この代金は諸収入になるのか尋ねました。","respondent":"平原防災課長","answer":"こちらの収入ですけれども、財産収入の財産売払収入という形で歳入とする形になります。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"品川区では、防災ラジオを１世帯につき１台を求める方に有償で配布しています。スマートフォンで災害情報を受け取ることが困難な６５歳以上の高齢者世代や障害をお持ちの方、経済的に困窮している非課税世帯の方だと伺いました。","respondent":"平原防災課長","answer":"そのうち３００台につきましては、防災区民組織本部長などに配布という形で、５,０００台を売却対象としたところです。昨日現在で１,３３６台の合計３,１５６台が、現在、３００台以外に販売分として３,１５６台が販売対象となったところです。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"カウンターで本人確認のできる保険証や障害者手帳などをその場で提示することにより、写しをわざわざ用意する手間を省くことはいかがでしょうか。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"翻訳機の導入を、実は２０１８年度１１月の決算特別委員会でも求めたところでありますが、残念ながらまだまだ進んでおりません。現在の公園内の案内等に関しての多言語化、区のお考えを改めてお伺いいたします。","respondent":"高梨公園課長","answer":"今、区民公園の再整備の中では、４か国語での多言語化ということで順次対応をさせていただいているところです。多言語化が行われず、いろいろなお知らせの看板を現地に掲示をしているところですが、日本語のみの表記という形になってあります。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"現場の方からもお声があるところですので、ぜひ具体的にここは早く進めてほしいと求めました。改めて伺います。","respondent":"高梨公園課長","answer":"自転車の貸出し部分についての外国人の方、親子を中心とした利用者が増えているという声は、公園課のほうにも届いているところです。英語と中国語の表記ということで現在考えておりますが、今、手配をかけているところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"順番を変えまして、温水プールの利用について伺います。地域住民としては、区の施設を有効に使わせていただきたい、そのような思いがあるのですけれども、現状をお知らせほしいと求めました。","respondent":"辻スポーツ推進課長","answer":"変更になるかと思いますが、真夏以外のところでは、十分コロナ禍前と変わらないような状況で推移しているという状況です。やはりどうしても学校が先になってしまいますので、そこはうまく調整をしながらということでやっているところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"そんなに人数も多くないので半面は要らない、１コースだけの貸出しをしてもらえたらという、そういうお声もありまして、利用料金も減ってくると。利用条件の緩和をご検討いただきたいと思うのですが、いかがか尋ねました。","respondent":"辻スポーツ推進課長","answer":"貸出しの仕方についての質問ですが、今のところ、全面貸し、それから半面貸しという２つの形だけになっております。どのような貸出しの仕方が区民の健康増進に一番つながるのかということを随時考えていきたいと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"「ゆり花壇大作戦２０２１年」の４,２００株から始まり、今年は１万株を予定しているということで、私もそこに参加させていただきました。できたら鮫洲駅からの案内をしていただきたいということ、鑑賞時の声のことも含めて対応をお願いしたいと思いますが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"どちらかが迷惑を被るというような形のないようにすることがイベントとしては大切なことだと考えています。境界にネットを張るなどの対応はしたところですが、必要な対応については前向きに行っていきたい、このように考えているところです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"私は、５０ページ、特別区民税、５６ページ、特別区交付金、税収あるいは森澤区長の区政運営の姿勢についても伺っていきたいと思います。それとも、全く関係ないのか、どちらなのでしょうか、伺います。","respondent":"黒田財政課長、多並都市開発課長","answer":"それなりの住居費がかかるという意味では、そういった収入がある方が品川区に住まわれているという実態もあると思いますので、そういったところが区民税の増収につながっているのではないかというふうに考えてあります。 再開発の観点からお答えします。再開発事業ということで事業を立ち上げて進めている事業であり、まちの課題を解決するために面的な開発を進めている、そういう事業です。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"人口を増やす、高額納税者を増やすことは、再開発事業の目的と全く関係ないということなのか、それとも関係あるということなのか、もう一度伺います。","respondent":"多並都市開発課長","answer":"皆さんでお話ししていただいて、それを実現する方策を一緒に共同という形で共同ビルを建てるなどを検討いただき、解決する事業の仕組みです。区としましては、そういうまちの皆さんが考えるまちを実現するために支援するものであり…","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"「選ばれるしながわ」とは、具体的にどういう意味なのか伺いたいと思います。選ぶ人は誰なのか、なぜ選ばれたいのか、改めて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"区におきましては、３つの無償化をはじめ、国に先駆けて先進的な子育て支援も含めて、来年度、選択と集中で財源を充てて進めていくものです。世論調査では９割の方々に住み続けたいと言っていただいておりますが、今後、転入増にもつながるものだと考えております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"人口を増やすことと税収を上げることが１つのキーワードになっていると思います。「選ばれるしながわ」とは、これから区に転入する方、転入人口を増やしたいという意味なのでしょうか、伺います。","respondent":"佐藤企画調整課長","answer":"区といたしましては、先ほどご答弁したとおり、品川区民の福祉向上に向けて様々な施策をバランスよく展開していくというところが１つです。もう１点、それはそれで、そういうところだというふうに考えているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"そうですね、つながればというか、「選ばれるしながわ」を掲げているわけですから、何を目的にしているのですかということを伺っているのです。９割以上、現在住んでいる区民への目線が感じられないのですけれども、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"施政方針で書かれているとおり、様々な施策をバランスよく、４つの体系をもって進めていくところです。転入増、地域のにぎわい等も活性化されますので、そういったものも含めて品川区を盛り立てていくところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"子育て支援の充実は、「選ばれるしながわ」の実現のために行うものではないと思いますけれども、いかがでしょうか。住民福祉の増進との基本に立って、そういった区政運営に転換していただきたいのですけれども、併せて伺います。","respondent":"佐藤企画調整課長","answer":"それに共感して、多くの方々に品川区を訪れていただくところも１つの観点です。議会のほうに予算をお願いしておりますので、その辺も含めまして、様々議論していただければと思います。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"６９ページのボルダリング場について、１０１ページの無電柱化推進事業について、１４７ページの過料についてお伺いいたします。６９ページのボルダリング場について伺います。","respondent":"辻スポーツ推進課長、高梨公園課長","answer":"今、委員お話しされたとおり、東京２０２０大会で新競技としてボルダリングが出ました。そのような施設をつくりたいという思いで、区の真ん中にある適地として、しながわ中央公園のところに設置をしたところです。 過去には八潮北公園にスケートボード場ということで、アーバンスポーツの施設をこの間つくってきてあります。アーバンスポーツについても機会を捉えて展開をしてまいりたい、このように考えているところです。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"これで区のお考えははっきり見えたかと考えています。続けて、令和５年度の予算では、約１万２,０００回ということなのですけれども、これはどのような形で計算されたのでしょうか、お知らせください。","respondent":"辻スポーツ推進課長","answer":"初めての施設ですので、区内に弓道場があります。それから、スケートボード場の利用率などを勘案しまして、その中から算出してこの数字を出したところです。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"実は私も、もう４１歳になるのですが、様々な意見を聞いて、ボルダリングデビューをしようかというふうに思っております。レンタルできる環境にしていただきたいとは思っているのですけれども、現段階で、品川区はどのようなお考えをしているのかお知らせください。","respondent":"辻スポーツ推進課長","answer":"４０代でも、５０代でも、６０代でも利用できるかと思います。月に１回、初心者講習会ということで、無料で開くような予定をしております。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"このボルダリング場の設計図を確認させていただいたのですが、私自身は無料エリアで鍛えてから有料エリアで挑戦させていただきたいと考えています。こうした対策について、どのようにお考えでしょうか、お知らせください。","respondent":"高梨公園課長","answer":"有料エリアは高さ４ｍほどありますが、もう少し小さいお子様、遊具のように使っていただければということを想定しています。夜間のそういったことが起きるようであれば、夜間の閉鎖等も視野に入れながら適切に管理してまいりたい、このように考えているところです。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひこうした近隣住民に配慮をしてほしいと求めました。例えば入り口付近に、ふれあい掲示板みたいな少し大きい使用上のルールみたいな看板等を設置されてはどうかと考えていますが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"利用者の方に混乱のないように、分かりやすい掲示、周知に努めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"続きまして、９７ページのヤングケアラー支援事業について伺います。医療の各機関の緊密な連携を促進させると伺っておりますが、その後また費用がかかってしまうのか、あわせて伺います。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラー支援におきましての相談にかかる費用のお問合せですけれども、１,２６０万円程度を、提案をさせていただいているところです。そこから具体的なご支援を差し上げるに当たりましては、特段そのことに関して特別経費がかかるということは想定してございません。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"区として、この年齢についてどうなっているのでしょうか。高校生につきましては、義務教育の学校でないので、例えば、高校を中退された方などは対象に含まれるのでしょうか、あわせて伺います。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーの支援に関する年齢の区の考え方に関するご質問かと思いますけれども、また、当然ながら支援の対象と考えています。必要な支援が何かというところについては、しっかりと把握し、適切な支援ができるように支援策を組み立ててまいりたいと考えております。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"高校を中退された方とお話をする機会があり伺いましたところ、その本人は笑顔で答えておりますけれども、胸が痛みます。掲示板等も含めて、ポスターで周知をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"これまでも学校、児童センター、図書館などにポスターを掲出するなどいたしまして周知を行ってまいりました。周知用のリーフレットの作成などを行っていきたいと考えておりますので、広く地域の方に認知いただけるように、周知啓発に努めてまいります。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、１０１ページの無電柱化推進計画事業の補助金について伺います。今後、地域住民に対し、こうした業者が突然来ないように対策をとっていただきたいのですが、いかがか尋ねました。","respondent":"森道路課長","answer":"当然、事業を始める前に、今回も文庫の森から補助２６号線にかけてについては説明会をさせていただきました。事業者と調整しながら、今後、努めてまいりたいというふうに考えております。","id":"exchange-026"},{"speaker":"江野下委員","kind":"質問","question":"軌道に乗っていると伺い、その家族への応援、居場所づくりに対しての取組にも感謝申し上げます。８２５万円と、ひきこもり支援のための新たな施設を立ち上げるものではないとは思いますが、新たな事業を立ち上げるものなのか尋ねました。","respondent":"廣田子ども育成課長","answer":"相談支援、ハード面でつくるわけではないのですけれども、機能としての地域支援センターを立ち上げていくことに取り組むための資金となっています。重症事例が増えたために、連携をさらに強化するために…","id":"exchange-027"},{"speaker":"江野下委員","kind":"確認","question":"確認がとれました。区内のひきこもり人数の把握、また、年齢層や状況などをどの程度把握されておりますでしょうか、説明を求めました。","respondent":"廣田子ども育成課長","answer":"ひきこもりの調査は、子ども・若者計画を立てた当初に行っておりまして、推計値としては１,５００人と推定しております。ひきこもりという定義に当てはまる子ばかりを支援しているわけではございませんで、小学生と２０代、３０代ぐらいが主に多い利用者となっています。","id":"exchange-028"},{"speaker":"江野下委員","kind":"質問","question":"幅広い年齢層だというふうに伺いましたが、私も５０代でありますが、近年は５０代以上の高齢者のひきこもりも多くなったと伺います。８０代の親が５０代の子どもの世話をする、いわゆる８０５０問題、高齢者になった子どもをさらに高齢の親が面倒を見るケースを何件か伺っています。","respondent":"廣田子ども育成課長","answer":"委員ご紹介のとおり、８０５０問題等が出てきております。取り組んできた中では、その人のゴールに向かって支援をしていくような多様性を認めていくことが必要であるというところが分かってまいりましたので。","id":"exchange-029"},{"speaker":"江野下委員","kind":"質問・要望","question":"ある人などは、私が死んだら、この子はどうなるのかなどと悩んでいる方もいるとお伺いします。そしてまた、その子どもたちが年をとっても前向きに生きていけるように、充実した支援を要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"人員確保の必要性を求めてきましたが、先日の総務委員会で審査があった職員定数条例でも、人員は１名の増にとどまっています。新規事業開始に向けても、やはり保健センターの人員を増やすべきだと考えますが、区の見解を伺います。","respondent":"柏木品川保健センター所長","answer":"これについても、今、検討中です。体制と人員の確保についても、現在、検討をしています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"２月２８日、自殺予防の取組を求める通知を、政令市などの教育委員会に出したところです。特に、子どもの自死を食い止めるためには、区はどこに焦点を当て施策につなげていくのか伺いたいと思います。","respondent":"坂野保健予防課長","answer":"今の体調、支援先へのつなぎの必要性を評価いたしまして、必要に応じて医療機関やほかの支援機関等へのつなぎを行っているところです。頼れる大人がその辺にいるのか、医療機関にはアクセスがあるのか、特に丁寧な支援機関へのつなぎを念頭に現在実行しています。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"検討状況を伺いたいのと、アドボケイトの必要性を求めていますが、進捗状況等を伺いたいと思います。そして、具体的に子ども意見表明支援員の配置を何人程度で予定されているのか伺います。","respondent":"長谷川児童相談所移管担当課長","answer":"現在、詳細についての検討を進めておりますが、まだ決定した事項はございません。その中で、意見表明支援事業をつくっていくわけになりますが、ここをどういった方に担っていただくかということを含めて、今現在、検討しています。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"対象施設には、私立保育園に限らず、区立保育園や延長保育をする幼稚園も含まれているのでしょうか、伺います。この事業の報告、公表については、どのように契約時に求めているのか伺います。","respondent":"立木保育課長","answer":"１５０施設ほどを年２回回りますので、約３００回ほどの予定ということで、考えているところです。これは子ども・子育て支援法の中で私立幼稚園も指導検査対象になってまいりますけれども、今、進めているようなところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"園児の置き去り事案は毎年ゼロになっていない状況があるので、ぜひ品川区として、品川区独自の配置基準を求めていただきたいと強く求めます。伺います。","respondent":"立木保育課長","answer":"こちらは区長会を通しまして、国のほうにも要望等をしています。職員、これは公立の職員だけでなく、区全体として保育の質を上げていくというようなことで取組をさせていただいているところです。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"強く要望したいと思います。保育園は命を預かる現場だということをぜひ強く思ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"須貝委員","kind":"確認","question":"それぞれの所管にお聞きしますが、根本的な解決策、現場を見ていて、どのようにお感じなのですか。どのように対策をすればいいとお思いなのですか、説明を求めました。","respondent":"初貝保育教育運営担当課長、染谷子ども家庭支援センター長、飛田子育て応援課長、菅野高齢者福祉課長、矢部教育総合支援センター長、松山障害者支援課長","answer":"どういった形で就労していただくかですけれども、保育課では、保育園で病児保育を事業として扱っております。こちらは… ヤングケアラー支援に関しましてお答えをします。ヤングケアラーの支援につきましては、そのご家庭全体を支援をしていくということが１つ重要なポイ… ひとり親家庭の支援としましては、また洗濯、そういう家庭の状況を把握しながら業務に当たっているところです。 区内には、２０か所の在宅介護支援センターがございまして、必要な介護サービスにつなげている現状があります。…","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、どのような対策があるのですかとお聞きしました。私が病院へ行かなければいけないときにどうするのか尋ねました。","respondent":"初貝保育教育運営担当課長、菅野高齢者福祉課長、中元保育支援課長、松山障害者支援課長","answer":"先ほどご説明させていただきましたけれども、区では、病児保育をやっております。やはり急なお預かりですけれども、引き続き… 高齢者の介護につきましては、やはり状態像も様々ということもあります。日頃から相談等に応じて、ご家族が困らないように… 助成額としては、午後１０時まででしたら、１時間当たり上限２,５００円をお支払いいたします。午後１０時以降… 急なお預かりに関しましてですけれども、障害分野ではショートステイという制度があります。本人の状況等、健康状況、パニック等の状況…","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"今の事業部もそうですが、保育課、障害者支援課、高齢者福祉課もそうですが、煩雑な書類はたくさんあるのではないですか。こういうものをそろそろ導入していかないと、煩雑な事務関係がパンクしてしまうのではないか尋ねました。","respondent":"宮澤情報推進課長","answer":"そういったところにＡＩ技術は現在も活用しておりますが、どういう形で実装できるかというのは、今後検討という形にはなってきております。ＤＸ推進基本方針においても、今後、先端技術の動向には注視していきたいと考えております。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、このチャットＧＰＴは、産業革命やインターネットに匹敵する、それだけの技術だそうです。区の職員も少し仕事量を減らせるように、なおかつ、円滑に様々な事業が進められるように対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"７５ページ、自転車駐車場使用料、５２ページ、特別区たばこ税について質問します。１１２台の収容と戸越の地域では台数も多い駐輪場だったので、状況と、新たな駐輪場整備などの計画はいかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"今後の見通しですけれども、付近に２か所の区営駐輪場がありますので、そちらのほうに収容可能です。おおむね９０％台ということで、現在の駐輪場については、現状のままやっていきたいと考えております。","id":"exchange-041"},{"speaker":"せらく委員","kind":"提案","question":"前回ご提案した子どもたちが描いた絵の設置については、視点を変えて、１つ提案させてほしいと求めました。こういった形など、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"しかしながら、阪急前の阪急の駐輪場、こちらに３か所の阪急が用意している駐輪場があります。歩道への駐輪の可否については、その状況を見ながら、今後、検討してまいりたいと考えています。","id":"exchange-042"},{"speaker":"せらく委員","kind":"質問","question":"１個飛ばしでないと駐輪ができないという状況で、どうしても自転車が入らず、諦めてほかの駐輪場を探したということもありました。この禁止看板、ずっと置いておくわけにはいかないと思いますので、改めてこういった別の視点からということはいかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"今、看板の設置、常に置いておくわけにはいかないというご質問についてお答えしたいと思います。やり方等を確認をしまして、どういったものが品川区にあっているのかも確認をしながら検討してまいりたいと思います。","id":"exchange-043"},{"speaker":"せらく委員","kind":"質問","question":"次に、喫煙関係で質問します。当区でも、路地のそういった投げ捨ての多いポイントに貼ってもらえたら効果的だと思うのですが、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"いろいろご相談を受けた際には、現場に係員が行きまして、どのような表示ができるかということで確認した上で表示を貼っているところです。どうしても貼れない場所につきましては、ご自宅のほうに掲げられる看板についてもご提供させていただいているところです。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問","question":"港区ではそうされているので、品川区でもいかがですかという質問だったのですが、そちらはまた後ほどお願いします。投げ捨てに関するご相談があった場合、見回りの強化などはしっかり対応されていますでしょうか、伺います。","respondent":"森田生活安全担当課長","answer":"は、パトロールの強化であるとか、なるべくその状況が改善されるようなものを知恵を絞って対応しています。","id":"exchange-045"},{"speaker":"せらく委員","kind":"質問・要望","question":"お子様を連れて歩く際に気になるという方が多くいらっしゃいます。喫煙者や灰皿設置者に向けた配慮義務の周知も引き続きしていただきたいと思うのですが、どのように指導はされていますか尋ねました。","respondent":"森田生活安全担当課長","answer":"路上に灰皿を置く場合につきましては、これはどちらかといいますと、道路の設置になりますので、道路の禁止行為になるところから、これは警察とも相談をしながら進めていくべきものではないかと考えています。","id":"exchange-046"},{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、５０ページの特別区民税について、また、５２ページの特別区たばこ税について伺います。５０ページの特別区民税について伺います。","respondent":"黒田財政課長","answer":"個人の所得も上がるという意味では、区民税も収入増となりますし、法人の住民税も上がれば財調が増えていくという形で経済活動が活発になってきているところも要因としてあるのかと考えています。","id":"exchange-047"},{"speaker":"小芝委員","kind":"質問","question":"３つ挙げますが、あと買物に便利であること、土地になじみや愛着があるということがアンケート結果で分かりました。このまま品川区に住み続けたいと考える人が回答者の９割を超えるということは、区はどのようにお考えか、説明を求めました。","respondent":"佐藤企画調整課長","answer":"委員ご紹介のとおり、区民の９割を超える方々に、引き続き区に住みたいと言っていただいたところは大変喜ばしいところです。区といたしましては、そういった面も含めまして、引き続き多くの区民の方に住んでいただけるように全力で施策を展開してまいりたいと考えています。","id":"exchange-048"},{"speaker":"小芝委員","kind":"質問・要望","question":"例えば、羽田空港へのアクセスとして、先般、武蔵小山からバスが運行を始めたことも、また１つ品川区への移住を決めるきっかけになるかもしれません。交通利便性、この先にあるものをどのように品川区は考えておられるのか、ご見解をお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"さらには、今現在、検討を行っておりますが、羽田アクセス新線に関わる新駅の設置の要望の可能性の検討なども行っております。やはり品川区にとっては非常に重要な都市基盤、地域公共交通の充実について、今後もしっかりと検討を行っていきたいです。","id":"exchange-049"},{"speaker":"小芝委員","kind":"質問・要望","question":"この３０億円を受動喫煙や副流煙で不快な思いをされてきた区民、コンテナ型喫煙所の整備拡大を進めるべきであるとの立場に立ちまして、質問をします。西口に喫煙所を整備することになりましたその経緯について教えてほしいと求めました。","respondent":"森田生活安全担当課長","answer":"大崎駅西口バスターミナル内の喫煙所についてのご質問です。喫煙所に隣接する歩道に喫煙者が出るなどのこともございまして、この改善のために取組をさせていただいたところです。","id":"exchange-050"},{"speaker":"小芝委員","kind":"質問・要望","question":"年間３０億円を超えるたばこ税からしますと、その１％に満たない額で、受動喫煙から、たばこを吸わない非喫煙者を守ることができるわけです。それぞれコンテナ型喫煙所を設置していただきたい、検討すべきと考えますが、ご見解をお願いいたします。","respondent":"森田生活安全担当課長","answer":"このコンテナにつきましては、ある程度の敷地面積が必要でございまして、また、埋設物等々も含めまして、様々な検討が必要です。現状、そういった敷地を確保した上での設置をしないといけませんところから、現在も、個々、場所の選定を図りつつ、今進めているところです。","id":"exchange-051"},{"speaker":"小芝委員","kind":"質問・要望","question":"１人当たり１,０００円徴収していると認識をしておりますが、さらには、この条例の適用される範囲を広げていく。それがまちの景観を守ることにもつながってくると思いますが、区の見解を教えてほしいと求めました。","respondent":"森田生活安全担当課長","answer":"喫煙所の設置や、または指導・取締りということで、様々な対策を得ながらも進めているところです。こういったものを加味しながらやっていきたいと考えていますので、現状でこれを広げていくというところでの検討は、今のところしていないところです。","id":"exchange-052"},{"speaker":"小芝委員","kind":"質問・要望","question":"さらにこの５月から類型も変わってきますので今後増えると思いますが、そういう方には、ぜひあらかじめお知らせしてほしいと求めました。ぜひ外国語で喫煙所の位置を明確に分かるようにしてほしいと求めましたが、ご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"現在、ホームページに掲載をしています。様々なご検討もいただきまして、引き続き検討してまいりたいと考えています。","id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、児童虐待・ＤＶ対策等総合支援事業費補助金、いじめ防止対策事業補助金についてお伺いいたします。将来的には、子どものケア葛藤とコントロール葛藤の解決に向けた関わりを教育現場でも行っていただきたいと要望いたします。","respondent":"矢部教育総合支援センター長、長谷川児童相談所移管担当課長、染谷子ども家庭支援センター長、柏木品川保健センター所長","answer":"初めに、学校の対応です。自己肯定感が低い原因は１つではないというふうにも考えてあります。 例えば、怖いことがあった後に自分の体にどのようなことが起こるのかなどをパンフレットや絵本を活用しながら説明をしております。… 子ども家庭支援センターにおける対応等ですけれども、その保護者の方の愛着障害などが影響している可能性があると言われております。… 内容といたしましては、基本、相談を受けて、保護者等も含めてでありますが、支援をしていく。心理士一人で行うわけではなく…","id":"exchange-054"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、地域振興基金繰入金、協働推進経費についてお伺いいたします。これからさらに加速していただきたいというふうな思いがありまして質問するのですけれども、あと団体ですとか、現状についてをご説明ください。","respondent":"川島地域活動課長","answer":"伴走型支援ということで、もう既に５０件ほどコーディネート、今後もこの辺の取組を組織的にしっかりやっていくことが重要であるというふうに考えてあります。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問","question":"区民ですとか団体と区をコーディネートする職員を配置していただいて、そうした現在の流れをさらに加速してほしいと考えているのですけれども、協働推進の拠点づくりの見通しについて説明を求めました。","respondent":"川島地域活動課長","answer":"集いの場のような部分を置けたらいいなということは考えているところですが、今、検討しています。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"昨日、子どもたちのマラソン大会、川島参事にも楽しく見守っていただいたという感想をお聞きしたのですけれども、こちらの協働推進、庁内とＮＰＯの協働推進の強化等につきましても、楽しみながらお仕事を進めていただきたいと思っていますが、最後、感想ではなく、一言お願いします。","respondent":"川島地域活動課長","answer":"仕事をしっかり楽しくやっていきたいと思います。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"確認","question":"１４３ページ、この「等」の中身を調べるために歳入予算見積書を確認しますと、環境学習交流施設地所賃貸料６２万８,８００円と計上されていました。これは区立の公園の中の区立施設だという認識でしたので、この地所賃貸料とは何か、簡単にご説明ください。","respondent":"河内環境課長","answer":"こちらの地所賃貸料ですが、飲料用自動販売機の貸付料です。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私ども、令和３年第４回定例会一般質問でこのように要望しました。何回も要望していますけれども、エコルとごしの本施設の計画段階の当初から、明確に反映した展示・学習内容とすることを求めてきました。","respondent":"河内環境課長","answer":"現在、エコルとごしにおきましては、令和４年度の時点で、ＳＤＧｓ関連の講座を７講座進めております。さらに倍加いたしまして１４講座を展開しつつ、学生連携を進めまして、こういった問題に新たに進んでいくものです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"同じ一般質問の中で、エコルとごしで学び、バッジを作成して活用することが環境学習の一環としてふさわしいと求めておりました。どういう基準で配られているのかということ、さらなる活用を求めたいと思うのですが、これについてご見解を伺います。","respondent":"河内環境課長","answer":"施設見学会、団体利用の際に、こういったものの配布を進めているものです。令和５年度ですが、関係者につきましても、こういった配布を通じまして一層の意識醸成を図ってまいりたいというふうに考えているところです。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"提案","question":"そういうものをどうでしょうかというご提案をしましたら、アイコンをどう使えるかは少し検討させてくださいと、このようなご答弁でした。所管は企画調整課になるのでしょうか、人事課になるのですか、ご答弁をお願いいたしますとの意見を述べました。","respondent":"佐藤計画担当課長","answer":"その際は、区がＳＤＧｓの推進について強く打ち出していくということですので、ＰＲをしていくことも重要だというふうに考えております。そうした中で、様々なＰＲの手段が考えられると思いますので、検討しつつ取り組んでいきたいというふうに考えております。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"提案","question":"新規事業として、このＳＤＧｓ未来都市に向けた取り組みとして質問で要望したとおり、議会提案から３年を経まして。今までに２回ぐらい提案しているのですけれども、ＳＤＧｓ専門部署が、これも最初に提案してから４年を経てようやく実現に至ったのですがとの意見を述べました。","respondent":"佐藤計画担当課長","answer":"先行しております、ご紹介いただきました豊島区等の取組を参考にさせてもらいながら、全庁的に検討してまいりたいというふうに考えております。区としまして、「経済と環境が両立するＳＤＧｓ しながわ」を目指して…","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それを対外的に発信をしていただきたい、強く強く意識を持って発信をしていただきたいという趣旨で質問させていただきました。ぜひ区長の主導で大きく進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"私からは、１４１ページ、非核平和都市品川宣言事業に関わって、ウクライナを侵略したロシアへの品川区の２度目の抗議を求めて質問いたします。この現状を区はどのように思われますか、伺います。","respondent":"古巻総務課長","answer":"ちょうど１年がたつのだなですけれども、品川区として、ロシア連邦の大統領宛てに送らせていただきました。終結の見込みが立たないような状況ということで、解決の見込みが立っていないということで、非常に遺憾なことだと考えております。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問","question":"濱野区長の１年前の抗議文も、１９８５年３月に非核平和都市を宣言し、理解を明らかにしてウクライナ侵略に厳重に抗議しています。森澤区長は、この濱野区長が出した抗議文と同じ立場でしょうか、伺います。","respondent":"古巻総務課長","answer":"区として抗議文を出しておりますし、その立場については、区長が代わっておりますけれども、変わっていないと認識しております。","id":"exchange-065"},{"speaker":"おくの委員","kind":"質問・要望","question":"２月２３日に、国連憲章の原則の実現実施を求める決議案を、同様に１４１か国の賛成多数で採決いたしました。区長が濱野区長から森澤区長へと代わったのですから、いかがでしょうか、伺います。","respondent":"古巻総務課長","answer":"現時点で、特段、そういった立場の変更があるわけではございません。改めての抗議文は、現時点では考えておりません。","id":"exchange-066"},{"speaker":"おくの委員","kind":"質問","question":"有権者の目から見ましても、どのようなことをしてくれるのだろうというようなことで、いろいろ期待も集まったりしております。すから、そういう話にはならないと思うのですけれども、いかがか尋ねました。","respondent":"古巻総務課長","answer":"ウクライナ支援ということでは、支援金については、さらに追加の支援もいろいろ考えている中で今後も進めていきたいという形です。繰り返しになりますけれども、区として抗議文を送らせていただいているということで、改めて抗議文を送る考えは現在のところございません。","id":"exchange-067"},{"speaker":"おくの委員","kind":"質問・要望","question":"その点、もう一度お伺いしたいと思います。それでも抗議文を出せないと言うのなら、なぜ抗議文を出せないのか、もう一度明らかにしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"おくの委員","kind":"質問・要望","question":"それを終わらせるためには、世論、それと支えられた政治や外交の動きが繰り返し必要だと思います。抗議文を強く求めて質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"西村委員","kind":"質問","question":"充当事業のすまいるスクール運営費ほか１３事業の中に私立保育園の一時預かり事業が含まれていると伺っておりますので、関連して伺ってまいります。今年度の新しい取組と、来年度に向けての取組について説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"産後の家事・育児支援につきましては、お子さん１人当たりの助成時間を増やすなどいたしまして、多くの方にご利用いただいているところです。令和５年度、お母さんに限らず…","id":"exchange-070"},{"speaker":"西村委員","kind":"確認","question":"区役所内でも、昨年４月から、男性職員に子どもが生まれた場合には、必ず育休意向確認を実施していると伺っています。今、職員の男性育休取得率はどのくらいか尋ねました。","respondent":"崎村人事課長","answer":"昨年度が３９.６％でしたので、今年度、数字としては上がっているところです。１０月にも育休が分割取得できるですとか、男性の産後パパ育休といった制度も開始になったことから、人事課でも促進をしています。","id":"exchange-071"},{"speaker":"西村委員","kind":"意見","question":"職員の皆様の働き方の改革の推進と、まずは足元から子育てとの両立を目指す取組を引き続きお願いしたいと思います。区内企業に対する啓発や取組で、現在、実施していることがあれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"区内の中小企業に対する育休等の支援ですけれども、それから働き方への対応のために、専門家やコンサルタントを活用した際に助成金を支給する事業を実施させていただいているところです。","id":"exchange-072"},{"speaker":"西村委員","kind":"質問・要望","question":"次に、品川区の子育て世帯の現状について伺います。現在の品川区の子育て世帯の現状はいかがでしょうか、伺います。","respondent":"廣田子ども育成課長","answer":"コロナ禍も手伝いまして、テレワークが増えて父親の育児参加率は増えていると認識しております。児童センター等で行います事業につきましても、父親の参加率が大変上がっておりまして、かなり参加率が増えていると認識しています。","id":"exchange-073"},{"speaker":"西村委員","kind":"質問・要望","question":"そもそもなぜ父親に育休をとってほしいのかという、何のためにというメッセージを届けていくことが必要だと思いまして、お伺いさせていただきました。パパ向けやパートナーシップ講座など、現在どのような講座があるか伺います。","respondent":"若生健康課長、柏木品川保健センター所長","answer":"父親に関する親子健康手帳上の内容の盛り込む予定です。この改正を受けまして、来年度、親子健康手帳、品川区のほうにもそちらを反映していけるように、現在、検討を進めているところです。 個人ワークといいまして、時間配分等も含めて自分でその後の育児等を考える、そういうことで父親向けの教室を実施しております。先ほど答弁でもございました児童センターでは、父親のための親育ちワークショップ等も開催しています。","id":"exchange-074"},{"speaker":"西村委員","kind":"提案","question":"北欧は女性の就業率が８割から９割なのですけれども、父親が夕方に帰ってくるため、家事・育児を大半の家庭で分担していると伺っております。さらに、対象年齢ごとの受入れ枠の人数は何人になるか尋ねました。","respondent":"中元保育支援課長","answer":"区が今回取り組もうとしているモデル事業ですが、品川版の未就園児の新たなモデル事業を実施したいというものです。区内の私立保育園事業者に案内したところ、７事業者の応募がありましたが、今後、提案内容などを加味した上で実施する保育園を選定する予定です。","id":"exchange-075"},{"speaker":"せお委員","kind":"提案","question":"私からは、１４４ページ、ふるさと納税寄附金、１３７ページ、特別支援教育推進補助金についてお伺いします。昨年から増額しています見込み、どういった理由か説明を求めました。","respondent":"提坂税務課長","answer":"令和３年度、令和４年度については、やはりコロナ禍の影響を踏まえまして、実績がやや伸び悩んでいる部分があると。令和５年度につきましては、コロナも５類へ移行するということも踏まえまして、金額を増額させていただいた次第です。","id":"exchange-076"},{"speaker":"せお委員","kind":"質問・要望","question":"それはそれで大切なことだと思っていて、ふるさと納税制度は国には制度を見直ししていただきたいという思いは同じです。そこで、品川区のホームページには、「返礼品競争に加担せず」と書かれていますが、そこの考え方だけ説明を求めました。","respondent":"提坂税務課長","answer":"返礼品としましては、物よりも事ということで開発を進めております。今後も新しい体験型の返礼品の開発を進めていきたいと考えているところです。","id":"exchange-077"},{"speaker":"せお委員","kind":"質問・要望","question":"そして、返礼品の検討に関しても、所管は税務課なのでしょうかと、少し疑問です。そこも含めて見解を説明を求めました。","respondent":"提坂税務課長","answer":"品川区をＰＲして、品川区に来てみたいというようなものであれば、返礼品として追加することは積極的に進めていきたいと思います。協力するとか、そういうことでやっていくことはやぶさかではありませんので、とにかく全庁的に取り組んでまいりたいと考えています。","id":"exchange-078"},{"speaker":"せお委員","kind":"質問・要望","question":"私が考えているだけでもたくさん出てくるので、今ご答弁ありました全庁的に、ぜひチームを立ち上げて検討していっていただきたいと要望します。どのような補助金なのか教えていただきたいのと、なぜ東京都は原則１年としたのか、ご存じでしたら説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"１点目、こちらの補助金につきましては、補助額２分の１でございまして、これは発達障害教育支援員を配置する人件費になってあります。特別支援教室のガイドラインが改訂された１つの大きな理由は、小学生だったら１年生から入室すれば、やはりきちんと１年間で。","id":"exchange-079"},{"speaker":"せお委員","kind":"質問・要望","question":"そこの支援をしっかりしていただきたいということと、そこも週１回だったりするので、ぜひこれから検討して長期的に見ていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"こんの委員","kind":"確認","question":"１２５ページ、１４３ページ、この３点をお伺いしたいと思います。空き家等対策事業と、それから地域自殺対策強化交付金、この２点について、簡単に事業概要を確認させてください。","respondent":"竹田住宅課長、つる委員長、坂野保健予防課長","answer":"品川区内には、区で把握しておりますのは約１００近い管理不全の建物があると認識しております。そこに対して、発生予防の推進、適正管理の推進… 所管の担当の課長はいらっしゃいますか。自殺の対策のことについて概要を説明してください。 自死遺族の支援機能、これは割と新しい事業なのですが、２か月に１回やっている自死遺族の方に集まっていただいて交流するという会。ゲートキーパー養成事…","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区の現状が分かれば教えていただきたいのですけれども、もっと必要なのか、その辺のお考えをお聞かせほしいと求めました。さらなる対策を考えることも必要だと私は思っているのですけれども、今後の品川区の自殺防止対策の方向性についてお伺いしたいと思います。","respondent":"竹田住宅課長、坂野保健予防課長","answer":"社団法人等を支援法人として活用することという内容ですが、支援法人に近い形で５者を毎年指定されておりますので、そちらをご案内するような形で。今後、与えられた権限を最大限に使って、空き家対策を進めていきたいと考えております。 具体的に、この先どうしていこうかというところなのですが、令和３年度から区で始めた事業として、インターネットゲートキーパー事業があります。若年層の場合は…","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうした情報は捉えていらっしゃいましたでしょうか。そこら辺のところはどう考えか尋ねました。","respondent":"坂野保健予防課長","answer":"自殺未遂者対応支援事業等、課題の分析、事業の効果等の評価にはまだ至っていないのが今の状況です。ある程度、また評価をしていきたいと思っておりまして、またチャンスがあれば狙っていきたい事業かというところで考えているところです。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"どのようなものが不用品として売り払われているのでしょうか。参考までに伺いたいと思います。","respondent":"品川品川区清掃事務所長、坂野保健予防課長","answer":"それから、昨年の１０月から始めています粗大ごみのリユース事業、これで一部有料のものがあります。こういったものの歳入を計上しているものです。 今、非常に厳しいお話であったわけなので、できるだけ前向きというか、積極的に、一歩前というのはなかなかあれで、半歩でも前にということでお答えしたいと思います。","id":"exchange-084"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ふるさと納税の区のスタンスをもう一度確認していきますが、特別区長会を通じて、不合理な税制度の抜本的な改善を見直していくことを求めていく。その上で、地方にも手をつないで、不毛な消耗戦をやめましょうというようなスタンスをとり続けるということで間違いございませんか尋ねました。","respondent":"提坂税務課長","answer":"今委員ご指摘のスタンスで変わりないかと思います。","id":"exchange-085"},{"speaker":"芹澤委員","kind":"質問","question":"お伺いしますが、世田谷区のこの一件は、事前に何かお話があったのでしょうか。品川区も一員でありますが、特別区長会として、世田谷区とどういうようなお付き合いをされていくのか説明を求めました。","respondent":"提坂税務課長","answer":"ふるさと納税に対するスタンスとしては、特別区長会で要望しているとおりなので、品川区としては、淡々とそのスタンスで進めていくということで、ほかの区の状況は特に情報は仕入れてございません。","id":"exchange-086"},{"speaker":"芹澤委員","kind":"提案","question":"やはりふるさと納税制度自体は改善を求めていく、傷口を少しでも減らしていくということが、品川区が常にとり続けるべきスタンスだと思っています。その方が使っていただけるようなものをつくってはどうですかというようなご提案をさせていただきましたが、今、ご見解を説明を求めました。","respondent":"提坂税務課長","answer":"２３区中、数区でまだ返礼品の開発を行っていないような区があることも実情です。もらえないものですから、プロジェクトを立ち上げるということで返礼品を獲得していきたいという気持ちはあります。","id":"exchange-087"},{"speaker":"芹澤委員","kind":"提案","question":"品川区の観光大使を様々具体的な案を提案して、もしくはゆるキャラをつくったらどうかというなお話を何度もしてきた中で、初めて知りました。この２０２２年当時に神奈川県の中井町の応援大使に着任をされたそうなのですが、兼務になりますというか、そういったご報告はあったのか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"自治体の場合は、品川区唯一というようなことで、他自治体とは同様の契約はご遠慮いただいているようなところです。サンリオ、企業が開放する別の用途の領域というようなところで、２層構造の契約に実態としてはなっているというところで理解をしています。","id":"exchange-088"},{"speaker":"芹澤委員","kind":"質問","question":"自治体として、神奈川県中井町の応援大使もされていらっしゃったということで、これは契約違反ということでお考えなのでしょうか。いかがか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"私どもが企業のほうから聞いているところにつきましては、行政としての契約については品川区としての契約が成立しております関係で、他の自治体と観光大使という内容の中では、品川区と一意の関係にあるというふうに聞いております。","id":"exchange-089"},{"speaker":"芹澤委員","kind":"意見","question":"タイミングでもあると思うので、新しいゆるキャラであったりとか、以前からお話ししている「わ！そろそろ変えてもいいのではないかという思いでありますので、このタイミングでぜひ前向きにご検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"１０３ページの公的賃貸住宅家賃対策調整補助金、１３３ページ、家賃補助と区営住宅増設を求めて質問します。実証する目的を伺います。","respondent":"竹田住宅課長","answer":"登録住宅のほうは、２月１０日現在、品川区内に１,０１５戸ありますが、専用住宅のほうは残念ながら０戸となっております。今回の令和５年度予算では、専用住宅に家賃低廉化補助、家賃補助を導入することをご提案しています。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"専用住宅に家賃補助するということですが、これが幾らなのか、誰に給付されるものなのか伺います。","respondent":"竹田住宅課長","answer":"こちらの制度は、貸主の方が入居者の方に対して家賃を下げた分を貸主の方に補助するという制度になってあります。金額としては、最大４万円となっております。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"しかし、専用住宅が増えれば、家賃補助を受けられるわけですから、入居者にとってはとても助かりますので、拡充をしてほしいと思います。先ほど、実施をする目的についても伺いましたので、そこを伺いたいと思います。","respondent":"竹田住宅課長","answer":"こちらの制度は貸主にご登録いただくことが前提となりますので、貸主および不動産事業者等に、十分この事業を周知していきたいと考えております。ひとり親、その他法律で規定されております該当者…","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"住まいは生活の基本であり、憲法第２５条に基づく健康で文化的な生活にとっての基盤です。この住まいを保障することが自治体の役割だという立場で進めてほしいと求めましたが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"こちらの制度は国の制度でございまして、全国で都道府県が中心になって行っている制度です。こちらの制度の趣旨を十分活かしまして、品川区としても、住宅の確保に努めていきたいと考えております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"この住まいは生活の基盤だと、人権の基盤だということで、その立場で施策を実施することが重要だと。それがやはり住民が安心して住み続けられる施策になっていくと思いますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"委員おっしゃるとおり、住宅は生活していく上での基盤です。しっかりと適切な環境でお住まいいただき、品川区に長く住んでいただけるよう支援していきたいと考えています。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうか。先ほど挙げた人たち以外に、このセーフティネット住宅には同性カップルは入居できるのでしょうか、伺います。","respondent":"竹田住宅課長","answer":"それから、生活保護受給者の方については、登録住宅には入居が可能です。それから、パートナーシップ制度を取得された方につきましては、ご入居いただける制度となっています。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問","question":"同性カップルについては入居できるということで、それはよかったと思います。それと、生活保護受給者は登録住宅しか入れないということなのですが、専用住宅には、なぜ入れないのか伺います。","respondent":"竹田住宅課長","answer":"専用住宅には、６か月間、併用が可能だというふうになってあります。生活保護の場合は、住宅扶助等もありますので、そういったところの併用を避けるため、こういった制度になったと考えております。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"入居後のフォローなども区として支援をしていっていただきたいというふうに思います。単身者など、住宅困窮者への家賃助成を実施することを求めますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"生活保護の方につきましては、先ほど申し上げた理由から、登録住宅に入居していただくことを考えてあります。それから、ほかの方々への家賃補助ですが、こちらについては研究させていただきたいと考えています。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"家賃補助を研究するということですので、ぜひ区としても独自にやってほしいと求めました。やはり民間アパートではなかなか入りづらいので、そういった意味でも区営住宅を増設していっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問","question":"私からは、議会費から質問いたしますけれども、議会運営費の中、議員報酬等、令和４年度６億３,４００万円余。この差は、議員数が空白の時期のためにできた差と私は思いますけれども、もう一度、どのようにできた差なのかを説明を求めました。","respondent":"工藤区議会事務局長","answer":"令和４年度の予算につきましては、議員定数から２名欠員の３８名分、４月から９月まで計上していたところです。一方、令和５年度は、議員定数どおり４０名分を計上しておりまして、これによる差です。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問","question":"令和４年度、そして令和５年度とほぼ同額の予算が組まれているわけですけれども、それとも変化はないと言えるのでしょうか。お聞かせくだい。","respondent":"工藤区議会事務局長","answer":"コロナ禍以前と比べての議会費全体の予算編成の変化というところでのお尋ねだと思います。予算の執行というところでは、行政視察に関わる経費につきましては、コロナ禍によって実施できなかった部分があったです。","id":"exchange-101"},{"speaker":"木村委員","kind":"意見","question":"コロナ禍以前と比べて、本区だけではなく、全国で同じような苦しみを味わっていると思います。行政としては、どのようなことを感じているのか、コロナに対しての感想をお願いいたしますとの意見を述べました。","respondent":"工藤区議会事務局長","answer":"その件で少しお答えしますと、視察に関しましては、令和５年度も令和４年度と同様の経費５４０万円余を計上しております。令和４年度は日帰りでの視察を再開したところですが、令和５年度は通常の形で予算どおりに実施できることを願っているものです。","id":"exchange-102"},{"speaker":"木村委員","kind":"意見","question":"次に、区議会だより発行ですけれども、昨年より２５４万円余、増えています。人口増なのか、それとも物価の上昇等などが関係しているのか、説明を求めました。","respondent":"工藤区議会事務局長","answer":"区議会だより発行経費の増の要因についてです。主な要因といたしましては、やはり印刷経費および配布に係る経費の単価が上昇したことによるものです。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"率直に、その策が効果が出ているとお考えでしょうか。それとも、そうではないとお考えでしょうか、説明を求めました。","respondent":"工藤区議会事務局長","answer":"それから、基本コンセプトを、読みやすい、親しみやすい、分かりやすいの３点といたしまして、そのような方針に沿って編集をしています。こちらは２０２２年１２月に実施された調査におきましては、４年前の調査時が５３％でございましたので…","id":"exchange-104"},{"speaker":"木村委員","kind":"質問・要望","question":"もしくは、品川区をよく理解していただくために頑張っていると思いますけれども、苦労は報われているとお思いでしょうか。もしよろしければ、感想を説明を求めました。","respondent":"工藤区議会事務局長","answer":"映像配信を行っているところですが、やはりこちらは議場に直接傍聴に行くことができない方を補完する上でも重要な情報発信手段です。それから、平成２８年に大幅にリニューアルいたしまして、欲しい情報に容易にたどり着けるような視認性や検索性の向上に努めているところです。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問・要望","question":"これは品川区の宣伝にもなりますし、いろいろと、我々４０名の区議会議員のためにもあると思います。ぜひとも皆さんのお力をおかりして頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"１２７ページ、それと、１４７ページの歩行喫煙防止過料について順不同に質問いたします。実際に私が指定地区での見回りをやっていますけれども、もっと多くの違反者がいると感じていますが、そこら辺の経緯の説明をお願いします。","respondent":"森田生活安全担当課長","answer":"過料の数につきましては、近年の取締件数を参考にしまして算出をさせていただいているところです。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、閉鎖と言われていたいろいろな喫煙所、こういったものも再開となるのか教えてください。指定喫煙所、または、庁舎内の喫煙所、公園にある喫煙所、それぞれの今後の計画を説明を求めました。","respondent":"森田生活安全担当課長、高梨公園課長、東野経理課長","answer":"今の指定喫煙所につきましては、現在、閉鎖しているところはございません。今後の喫煙所の設置ですが、これにつきましては… ５類移行を受けての動きですが、幾つかの公園におきましては、灰皿の撤去という形で進めしています。５類以降後も、地域の方のご意見を伺いながら… 庁舎の屋外喫煙所につきましては、現在、加熱式たばこについてのみ許可をしています。５類移行後ですが、臭いが気になるというような区民の声もありますの…","id":"exchange-108"},{"speaker":"松澤委員","kind":"意見","question":"息抜きの場所、また職員の皆さんのコミュニケーションを図れる、そういったものをつくるべきではないかと考えております。閉鎖して５年近くが経ったと思いますけれども、庁舎内、また、地域センター内の元屋内喫煙所、そういった活用についてご見解を説明を求めました。","respondent":"東野経理課長、川島地域活動課長","answer":"平成２１年度から、庁舎５階のところ、それから冷蔵庫を置いて新型コロナウイルスワクチンの保管場所としての活用なども行っているところです。そういったところも加味しながら、運用については… 地域センターのほう、６か所、屋内喫煙所があったのですが、そちらは今はほとんど倉庫として使わせていただいております。必要な改修を行ってというようなことになると思いますが…","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"例えば、プレミアム付区内共通商品券、今年で２０年目となる事業でありまして、大変好評だとお聞きしております。区のほうで何か分かっている費用対効果、結果等がありましたら、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街連合会への補助事業として実施させていただいておりまして、平成２１年度以降は年２回、春と秋に継続して実施させていただいているものです。実施後に商店街連合会でアンケートをとっておりまして、例えば…","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"次に、事業承継、ＢＣＰです、事業継続計画についてお聞きします。区内の事業所に対して、ＢＣＰの取組がどれだけ進んでいるのか、周知方法、計画、また事例の紹介などがありましたら、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"ＢＣＰですが、２０１１年３月の東日本大震災以降、区のほうでもいろいろな形で実施させていただいているところです。これに沿った形で、企業がカスタマイズといいますか、その企業に合ったものでつくられているということで認識しています。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"国としても、経営を早く若い人に渡してほしい、チャレンジしないと中小企業は生きていけないと考えています。区として、この課題をどう捉えているのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"特に従業員を抱えていらっしゃる企業にとっては、雇用の確保ということからも、大きな課題だというふうには認識しています。平成２８年度から実施させていただいておりまして、あるいは専門家の派遣、後継者塾などを中心に実施しています。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"取引先、引継先などの事例収集を行って、今後の支援策に向けて資料としていく。会議体というのですか、そういった取組もあるかと思いますが、ご見解を説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街サポーター事業は、基本的に商店街支援という形になりますが、商店街による店舗に対しての相談なども承っているところです。事業承継については、今後も様々なツールを用いまして、事業承継の重要性について周知していきたいと考えています。","id":"exchange-113"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１３９ページの無料乗車券発行事務委託金、１６１ページの雑入の公園内自動販売機設置運営事業収入について伺います。公園のほうは、公園数はどれくらいあって、自販機の数、また、金額など、どれくらいの収入になっているのか説明を求めました。","respondent":"松山障害者支援課長、飛田子育て応援課長、高梨公園課長","answer":"無料乗車券についての事業内容をお答えいたします。児童扶養手当の方へ、東京都都営交通無料乗車券を発行し、経済的負担軽減を図っているものです。 ひとり親家庭につきましても交通費無料パスをやっておりまして、児童扶養手当を受けている世帯の世帯員のうち１人に交付しています。 公園内に設置している飲料事業者による自動販売機の設置ですが、全１１公園で２１台の自動販売機を設置しています。…","id":"exchange-114"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この３月１８日から、この辺の状況を、どのような内容なのか教えてほしいと求めました。公園のほうにつきましては、そうすると、約９８０万円で２１台ですから、自販機が１台当たり４７万円ぐらいの利益になっているわけです。","respondent":"松山障害者支援課長、高梨公園課長","answer":"東京都交通局では、新たにＩＣカードを、障害者用ＰＡＳＭＯ等によるサービスを開始するということです。そちらに障害者ＰＡＳＭＯについて搭載することが可能ということで、事前にお手続をすれば… 設置している公園ですが、運動施設があったりとか、また、広い面積で一定滞在時間が長くなるような大きな公園に設置しています。例えばですと、しながわ区民公園や東品川海上公園、戸越公園等に設置しています。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問・要望","question":"大体１,０００人を超える方が発行を求められる中で、障害者支援課としても、そのことについてのお考えをお聞かせください。幾つか公園が挙がっておりますので、そこはそれぞれが存在していいのかなとは思うのですけれども、そういうことについてのお考えを説明を求めました。","respondent":"松山障害者支援課長、高梨公園課長","answer":"３月１８日から開始されます新たなサービスについての周知についてお答えいたします。窓口でもご案内するとともに、委員おっしゃられるように、障害者団体に個別に周知をしてまいります。 Ｐａｒｋ－ＰＦＩの検討についてですけれども、今、委員ご案内のとおり、まだ実施の公園や実施する内容については検討中の状況です。自動販売機が設置されている公園と、Ｐａｒｋ－ＰＦＩで実施する事業者と飲料の事業者と…","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"障害者の団体の方からご要望をいただいて、１台について４０万円ぐらいの費用になるのであれば、その辺の確保策について説明を求めました。","respondent":"松山障害者支援課長、高梨公園課長","answer":"新たなサービスについての周知につきましては、これまでやはり障害者支援課の窓口でも様々なお声をいただいておりました。今後とも、利便性向上のために、障害者支援課としても積極的に周知を図ってまいります。 自動販売機のさらなる設置といったところですが、公園の周辺に設置されているほかの事業者の自販機の設置の状況であるとか、見極めながら設置する公園については考えていきたいと考えています。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"あるとすれば、何世帯で、金額にしてどれぐらいなのでしょうか。そして、債権の継承はするのでしょうか、しないのでしょうか、お伺いします。","respondent":"勝亦学務課長","answer":"直近では５世帯程度となってございまして、直近では１０万円程度、全体の給食費で言いますと０.０１％程度となっています。こちらについては、私費で未納ですので、引き続き、徴収には努めてまいりたいと考えています。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"私費なので徴収していくということは、学校で徴収するのか尋ねました。","respondent":"勝亦学務課長","answer":"学校のほうから徴収のお願いを引き続きしていくという形になります。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"文科省のほうで、学校給食費徴収・管理に関するガイドラインとあって、債権の継承をするためのガイドラインが出ているのですが、それに基づいて、公会計に、私費会計のままでして、債権にならないで、学校のほうでこのままずっと徴収していくというか、督促をしていくのか尋ねました。","respondent":"勝亦学務課長","answer":"基本的には、学校のほうで徴収をお願いする形になります。徴収がなかなか果たせない部分につきましては、教育委員会のほうからの督促をかけていくような形を考えてあります。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、給食費の滞納分は私費会計のままで、公会計に入れて、地方自治法による私債権の回収の流れに乗せていかないということでよろしいか尋ねました。","respondent":"勝亦学務課長","answer":"給食費の食材費につきましては、引き続き、私費の口座を使ってまいりますので、そのような形で継続してまいります。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"確認","question":"公会計に入れないということが、今、説明があったので、それでどうなるかということは、また別の機会にお話を伺いたいと思います。区の債権の条例にも載せないで、今までどおり、この後何年も私費会計でいくかということだけ確認させてください。","respondent":"勝亦学務課長","answer":"現状の食材費の口座をそのまま継続していく形で考えてあります。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"ほかの機会に伺いたいと思います。学校教育法第１１条および同法施行令第２条に、無償化が可能の考え方と、あるいは文科省の見解があれば説明を求めました。","respondent":"勝亦学務課長","answer":"給食食材費の負担については保護者とすると学校給食法に記載があります。国のほうでも首相答弁の中で、こちらは義務の規定ではございませんので、そういった形で対応しているものです。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"確認","question":"私は決して給食無償化に反対しているわけではなくて、大変重要な政策だと思っているのですが、その道筋をもう一度確認したくてお尋ねしています。ということで、どうしてそのときにできなかったのか尋ねました。","respondent":"勝亦学務課長","answer":"人件費ですとか設備費は設置者が負担、まず基本的な考え方があった部分、そういったものを継承してきたという考え方です。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"１４４ページ、減債基金繰入金、約８億２,０００万円についてお尋ねします。利子の合計が約１１億円、繰入金が充当されていない約２億８,０００万円、充当されない理由はどのようなことかお尋ねします。","respondent":"黒田財政課長","answer":"いわゆる減債基金の繰入れの考え方ですが、歳出のほうで、いわゆる起債償還元金、利子がありますので、そちらをまず計上していくと。その一般会計の最後の調整として、起債償還元金の中で繰入れていない差額の部分につきましては、一般財源で対応しているものです。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"それは充当できない都市計画とか学校関係の建設費でない部分というふうに考えてよろしいですか。財調で手当てをされない部分を一般財源で充てているという考え方でよろしいか尋ねました。","respondent":"黒田財政課長","answer":"繰入れの原資の中に財調で、算定で措置された部分もありますので、そういったところの減債基金の補填の積み立てた部分については充てておりますし、それ以外の部分について、繰入分に対して一般財源を充てているといったものです。","id":"exchange-126"},{"speaker":"渡部委員","kind":"質問・要望","question":"この基準をもう１回教えてほしいのと、その考え方を教えてほしいのと、これは私道だからと。地域の人から要望があれば、その２点、お答えください。","respondent":"森道路課長、工藤交通安全担当課長","answer":"どういう経緯か分かりませんけれども、地域の方からのご要望も踏まえて、区のほうで設置したという経緯があるところもあるやに聞いてはおります。どういったやり方があるのかということは、所有者の方… 両方の道路に「止まれ」がないといったご質問にお答えします。要望等も加味しながら、警察のほうへの申入れはいたしていきたいと思いますので、そのような形でやっていきたいと思います。","id":"exchange-127"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、その地域から要望等があったら、これでやめておきます。その５年前に聞いた話をもう１回聞くようになるのですけれども、今年いよいよ１,５００万円でしょうか、減りましたよね。","respondent":"鈴木都市計画課長","answer":"平成７年度から平成１４年度まで合計３６億円の貸付けを行っておりまして、令和１１年度をもって最終的な返還が全て完了するというような状況です。再度、戻るかどうかについては、これからりんかい線のほうとお話をするということになろうかと思います。","id":"exchange-128"},{"speaker":"渡部委員","kind":"質問・要望","question":"前も伺って、２２億円のお金が品川区から入っていて、これは戻ってくるでいいのですよね。その辺で何か情報があったら教えてほしいし、それはしっかりとってくるべきだと思いますので、少しお考えだけ。","respondent":"鈴木都市計画課長","answer":"５年前に都市計画課長になりましたが、直接、東京臨海高速鉄道株式会社のほうからお話があったということはございません。その出資のお話、出資金の話がありますが、仮定の話で申し上げるのは、少しこの場ではふさわしくないのかなです。","id":"exchange-129"},{"speaker":"渡部委員","kind":"質問・要望","question":"いわゆる基礎自治体、この東京都にも、もっともっと出てくる性質のものなのですかということをまず教えていただきたいのが１点です。１２９ページの多摩産材との兼ね合いなのだけれども、事業が違って、そういう性質のものなのかどうなのかということを説明を求めました。","respondent":"黒田財政課長、森道路課長","answer":"そういった意味では、活用を検討するから額が増えるということではなくて、ある程度決まった額が譲与されるというものです。 東京都の多摩産材利用促進プロジェクト補助金ということで、今年度、道路課としては初めて充当するところです。申し訳ありませんが、こういった補助金を活用して、区としてもしっかり進めてまいりたいというふうに考えております。","id":"exchange-130"},{"speaker":"渡部委員","kind":"質問","question":"そうやって山林の荒廃を防ぐとかという目的もありましょうし、であれば、すごく教育活動に活かしてほしいと思うのです。そのまま使えるような仕組みを考えてほしいと思うのですが、環境課長、いかがか尋ねました。","respondent":"河内環境課長","answer":"ワークショップを行い、またそういったものを広めるウェブサイトの制作など、これを１１年にわたってやっております。こういったものの延長線にあるかどうかは別ですが、やはり木材の大切さやＣＯ２の削減につきまして取り組んでまいりたいと考えています。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０１９年６月に一般質問でこれを取り上げてから、８回にわたる購入費助成を求める請願や陳情が出されて、この制度を求めてきましたので。２つ目は、世帯非課税ということになるのか、その点も伺います。","respondent":"川原高齢者地域支援課長","answer":"現段階に関しましては、補助金の活用をする、申請をする予定で考えてあります。現時点の検討の段階におきましては、本人の非課税とするというように考えてあります。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その代表質問では、１つは、「なぜ所得制限を設けたのか、伺います」と、そしてもう１つは、「所得制限はなくすべきです。いかがでしょうか」と質問をしています。","respondent":"川原高齢者地域支援課長","answer":"そして２点目、あと、品川区でどういった助成ができるかということを情報収集を含め検討してまいりました。これを実施する上でまず大事なのが、そして使う上で大切なこと、そういった普及啓発をまず第一に取り組んでまいりたいというふうに考えてあります。","id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"あえて２つの質問に「伺います。改めて、対象をなぜ住民税非課税者だけにしたのか伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"こちらも改めてのご回答になりますが、こちらの補聴器の助成に当たっては、一定の年齢制限および所得制限を設けることというふうに記載があります。知識を深めていただく上で、社会参加に必要な補聴器の装用を行っていく…","id":"exchange-134"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"普及啓発のことは質問していませんので、ずっと求めてきましたので、その点も伺いたいと思います。これは、住民税は所得の１０％ですから、４６万円の納税額ということは、所得は４６０万円あるということです。","respondent":"川原高齢者地域支援課長","answer":"こちらは、まだこれから申請をするところですので、どのような結論を下すかに関しては都が判断するものと認識しています。他の自治体の情報収集を引き続き行ってまいりたいと思います。","id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどの答弁は、準ずるというのは当たらないのではないかというふうにお聞きしましたので、その点も伺いたいと思います。私は、高齢者は品川区を選んでほしくないというメッセージにもなってしまうのではないかと思うのですけれども、いかがか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"２個目の所得制限の撤廃についてですが、今回の要件を６５歳以上の高齢者、住民税非課税という形で設定をさせていただきました。引き続き情報収集に努めてまいりたいと考えています。","id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう所得制限をつけるという、そういうところだけ他区がそうしているから品川区もそうしましたというのは、理由にならないのではないのですか。これは矛盾になるのではないかと思うのですけれども、区の姿勢としては、根本的なところでどうなのか尋ねました。","respondent":"佐藤企画調整課長","answer":"少子化の進行に関しましては、異次元の少子化対策というところで、国を挙げて取り組んでいるところです。令和５年度予算に関しましては、３つの無償化に対して財源を振り向けて、それから福祉施策に関しましてもバランスよく実施していくです。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に理屈に合わないと思うので、ぜひともこれは所得制限を撤廃するという方向で検討してほしいと求めました。３万５,０００円というのは、隣の港区の４分の１ぐらいなのですけれども、どこから出した額なのか、このことも伺います。","respondent":"川原高齢者地域支援課長","answer":"港区に関しましては、委員ご指摘のとおり、金額の助成を所得制限なしで設けていることは認識しています。私どもも調査を踏まえた上で、他の自治体に関しましては、まずはしっかりと必要な方へ支援を行っていきたいと考えています。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問・要望","question":"６３ページのプラネタリウム、歳入から伺います。８６席あるということですが、こういった点、分かれば教えてほしいと求めました。","respondent":"黒田財政課長、山崎文化スポーツ振興部長","answer":"０歳児見守り子育てサポート事業も新規としておりますのは、いわゆる予算を編成する過程で、最後に調整して追加していったものについては「新規」といった表示をしているものです。 延べで５,５００人入っておりますので、４４人、ちょうど半分の席というようなところです。それから逆に、今ぐらいの少し寒い時期はというような状況です。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"令和３年度は既に持ち直しているということで、魅力とは何かということをお聞きして、あえて魅力づくりはどのように行っているのか。今のご答弁にもあったと思うのですが、端的に伺います。","respondent":"山崎文化スポーツ振興部長","answer":"やはり何といっても、魅力的な部分の１つとしては、低廉な利用料金で気軽に利用できるということがやはり１つの売りかなというふうに思っております。施設も複合機能がありますので、様々工夫しながら魅力アップにつなげていけるようなことに…","id":"exchange-140"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このプロジェクトは、２０３０年、２０５０年の未来の主役たちの意識醸成に向けても大変効果的な取組であると思われるからです。これに関する区のご見解をお伺いします。","respondent":"河内環境課長","answer":"こちらにつきましては、２００７年に開始された事業でございまして、品川環境プロジェクトとして実施されたものです。こうした状況下の中、チョウについてのあり方や取組について検討してはというふうに考えているところです。","id":"exchange-141"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この取組を進める上で、品川区立環境学習交流施設「エコルとごし」の活用は非常に有用ではないかと考えますが、現在の展望や構想などはいかがか尋ねました。","respondent":"河内環境課長","answer":"こうしたところも含めまして、エコルとごしの指定管理者なども、区民要望に基づきまして、ネイチャー担当などの設置の検討も進めているところです。学生などの連携、活用を含めまして、こういったところとの検討を進めてまいりたいというふうに考えているところです。","id":"exchange-142"},{"speaker":"鈴木（博）委員","kind":"質問","question":"エノキなどのチョウの食樹を、かつての武蔵野雑木林のように、その１区域にできれば再建することはできないでしょうか。区のご見解をお伺いしたいと思います。","respondent":"高梨公園課長","answer":"ジャコウアゲハの保護といたしまして、食草であるウマノスズクサの植栽を、蝶の道プロジェクトの時代から継続して行っているところです。公園内の自然環境は貴重なものであるとの認識ですので、大規模公園の改修の際には、ご提案を参考に検討させていただきたいと考えております。","id":"exchange-143"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。美しいチョウが舞い、美しい花が咲き乱れる魅力あふれる未来の品川が実現することを祈願しまして質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問","question":"私からは、８１ページ、車体ラッピング広告等、関連して、コミュニティバスについて、都市計画課について伺います。５６ページの特別区財政調整交付金についても伺いたいと思います。","respondent":"溝口土木管理課長","answer":"これにつきましては、東京都の屋外広告物条例に基づきまして、許可を取りながらやっているものです。その許可をする際に、手数料を予算計上として上げているものです。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"今日は歳入なので広告収入を伺いたいのですけれども、運行主体の収入になるということで、区の歳入としては上がってこない。これは東急のほうにはなると思うのですけれども、コミュニティバスということで収入があるのか、お伺いできればと思います。","respondent":"鈴木都市計画課長","answer":"収入は、９か月で、バス停両方向で、おおむね６万円弱というようなところです。２件ほどの応募があって、お使いいただいている状況です。","id":"exchange-146"},{"speaker":"松本委員","kind":"確認","question":"確認ですが、車体ラッピングも募集自体はされたということでよろしいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"ラッピングも含めて、東急バスのほうでは募集をかけているというような状況です。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"先ほどのお話だと６万円というふうな数字が出てきたのですけれども、そうすると、その分だけ収支は上がってくるということになるかと思うのです。お伺いしたいのですが、収支率の中に入ってきているのかどうなのか、そこの部分をお願いいたします。","respondent":"鈴木都市計画課長","answer":"広告収入につきましても、運行経費も含めて全体の収支率の中には入ってくるという考えです。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問・要望","question":"どういうことかというと、営業とは言わないですけれども、取るために動かれているのだろうなと思います。ぜひとも積極的に区としても広告を増やしていく、そちらのほうでやっていただきたいなと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そのメンバーとしましては、地元の町会の方ですとか、公募の区民ですとか、あるいは沿線の商店街の方々も入っていただく予定です。ご意見をいただきながら図っていく等も含めて、東急バスと連携しながら、さらに広告収入が上がるような周知の仕方については検討していきたいです。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問・要望","question":"そこの点は地域と連携しながら、東急バスとも連携しながら、増やしていただきたいなというふうに思います。これ、この後、合意に至らない場合はどうなっていくのか伺います。","respondent":"黒田財政課長","answer":"令和４年度分でしか算定ができませんので、これは都区が合意しませんと条例で配分できませんので、その算定残が残ったままになってしまうということが実態になろうかというふうに思ってあります。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問・要望","question":"ぜひともやっていただきたいのが、これまでも５５.１対４４.９ですか、児童相談所を区も設置できるようになった。これをもっと積極的に、例えば特別区長会で記者会見をやるとか、そういうことも必要かと思いますが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"区長会でも引き続き協議しておりますので、そういったところも含めて、区側としても発信していきたいというふうに考えてあります。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問","question":"なぜ五反田ではないのかということを伺ったところ、渋谷区のプラネタリウムのほうが圧倒的に性能がいい、それがまず１つ。それをまず伺います。","respondent":"山崎文化スポーツ振興部長","answer":"大人の方が２００円をいただく形、それから、リーズナブルな料金設定をさせていただいているというようなことかなというふうに認識しております。特に無料というようなところは、３歳未満の乳幼児の方はそういうことなのですけれども…","id":"exchange-152"},{"speaker":"吉田委員","kind":"質問","question":"つまり、障害者手帳を見せても、それ以上の減免はないという理解でしょうか。それから、ほかの施設についても伺いたいのです。","respondent":"山崎文化スポーツ振興部長","answer":"障害者の方がそういった諸活動で社会教育団体としての登録というようなことを兼ねていただくというのですか、そういうことだと思います。例えば、何か少し曖昧な答弁で大変恐縮ですが、よろしくお願いいたします。","id":"exchange-153"},{"speaker":"吉田委員","kind":"質問・要望","question":"全部で１５項目、それから、要保護児童の予防への配慮も行うことも区として求めていることが確認できました。ぜひ伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"障害者、ある程度の審査をしてマン・ツー・マンで介助員がつくというような対応はあるのですけれども、ご利用のときにご説明をしているところです。なるべく支援児でなくても配慮の必要なお子さんについても受け入れるというところでやっているところなのですけれども…","id":"exchange-154"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしても具体的に配慮が必要な子だけではなくても、すぐにその後、「トイレ行きたい」とか言ったりするお子さんがいるではないですか。それは配慮が必要な子とか、そういうことではなく、そういうことについては個別の対応はされていると理解してよろしいか尋ねました。","respondent":"廣田子ども育成課長","answer":"今度もう新１年生が入りますけれども、４月はそれまで幼稚園、年齢や発達段階に合わせた支援をするようにしております。区の職員が各校に１人ずつ担当指導員としてついておりますので、状況にあわせて本課と相談をしながら調整していくというような形で運営しております。","id":"exchange-155"},{"speaker":"吉田委員","kind":"確認","question":"ＳＮＳ上の求人広告というのですか、楽しみながら働きたい人、資格や経験は必要なしということで人員募集をしているものを確認いたしました。どのように話し合いというか、委託のときにされているのか、配慮されているのか伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"放課後児童支援員という資格を持った人が、子ども対応、事業者と共に話し合いながらやっているです。","id":"exchange-156"},{"speaker":"吉田委員","kind":"確認","question":"ぜひ両方、受け止めるほうは、しっかり受け止めていただいていることを区としても確認しながら運営されているということで理解をいたしました。もう時間がないので、その後の質問は衛生費のところで伺います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-157"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１０３ページ、災害時応急物資確保費、６７ページ、八潮北公園スケートボード場、６９ページ、ボルダリング場についてお伺いします。防災課でブースを出すというふうになっているのですけれども、この無人航空機、確認だけです。","respondent":"平原防災課長","answer":"３月１１日に開催予定の防災フェアにおける無人航空機のデモ飛行につきましては、区の職員が行います。","id":"exchange-158"},{"speaker":"高橋（伸）委員","kind":"確認","question":"無人航空機は、免許がないと多分できないと思いますけれども、区の職員の方は、大体何人ぐらい免許を持っておられますか。それだけ確認だけさせてください。","respondent":"平原防災課長","answer":"現時点では、職員５名が取得しておりまして、追加で２名、今、取得の練習中です。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問","question":"６７ページ、スケートボードについてお伺いします。大体４,５００回ぐらいということで、周知の部分もまだ不足しているのかと思っているのですけれども、その部分についてご見解をお願いいたします。","respondent":"高梨公園課長","answer":"令和３年９月になりますが、１２０m2ほどのスケートボードができるエリアを開放して、一定使っていただいているといった状況です。過去、品川区にあるアーバンスポーツのできる箇所ということで、周知の内容についても今後検討していく必要があるかというふうに考えてあります。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"質問","question":"６９ページ、ボルダリング場についてお伺いいたします。ボルダリング場の運営についてお伺いいたします。","respondent":"辻スポーツ推進課長","answer":"東京２０２０大会でアーバンスポーツ、ボルダリングが新規種目として開催されまして、非常に多くの感動を得たところだと思います。種目もたくさんの、今まであったスポーツではない種目を増やすという意味で、こちらの設置を決定したところです。","id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"質問","question":"４ｍの高さがあるというところ、安全面も含めて、今後どのように対応していかれるのかということをまず１つお聞きします。４月、重要なことになるのかと思っていますので、お考えをお聞きしたいと思います。","respondent":"高梨公園課長、辻スポーツ推進課長","answer":"魅力ある施設だということが分かるような周知方法については、これから検討して、皆さんに知っていただきたいというふうに思ってあります。４ｍの高さの下には、厚さ３０cmのマットを敷いて安全面に配慮いたしますが… オープニングイベントを開催する予定でして、一定程度有名なボルダリングの選手をお呼びしたりということは考えております。ブレイクダンス等も含めまして…","id":"exchange-162"},{"speaker":"大倉委員","kind":"質問","question":"１３５ページ、部活動指導員配置経費補助金から、これも伺っていくのと、スポーツの地域移行をあわせて伺いたいと思います。こうした２名体制になっていった経緯について説明を求めました。","respondent":"高梨公園課長、多並都市開発課長、矢部教育総合支援センター長、中谷指導課長","answer":"１,５００万円の補助対象額、２分の１の補助で７５０万円を計上させていただいてあります。公園・児童遊園整備費につきましては… ここに記載しています３億１,０８０万円につきましては、令和５年度に、小山三丁目第２地区が組合設立を今予定しております。… 部活動指導員です。こちらは、地域移行も含めまして、学校があと一歩進めるために、２人ずつ配置できるような予算案を計上したものです。 地域移行につきましては、まず…","id":"exchange-163"},{"speaker":"大倉委員","kind":"質問・要望","question":"１人当たりというものも出しているかと思うのですが、公園をどこまで増やしていくかという区の考え方を教えていただきたいのと、それをお願いします。そうした連携をしっかりしていくという地域スポーツのほうでもお話があればと思いますが、その辺の連携について説明を求めました。","respondent":"高梨公園課長、多並都市開発課長、辻スポーツ推進課長","answer":"区内では２８０、区が管理している公園としては２７２の公園がありますが、１人当たりの公園面積を５m2ということで定めてあります。… ２ｍしか歩道が確保できない箇所がありまして、高木、高い木をその２ｍの歩道の中央部に植えていた関係がございました。… 最終的に、地域としての受皿として、地域スポーツクラブや地域のスポーツ連盟、そういった団体が考えられております。今現在でも…","id":"exchange-164"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺はどういうふうにお考えなのかということと、ぜひ取り組んでほしいと求めましたので、よろしくお願いします。２名体制にしたというのは本当すごいなと思って評価しているところなのですが、その分、その辺はどのように工夫してやられていくのか説明を求めました。","respondent":"高梨公園課長、中谷指導課長","answer":"２点目の遊具取替えの件ですが、古い遊具を取り替えると、前の遊具よりも小さくなったというようなことが各公園で起こってあります。しっかりと周辺の状況等を調査して、また… 部活動指導員の人材についてのお問合せかと思います。学校のほうから、例えば、学校地域コーディネーターの方のネットワークの中で地域の方の人材を選ばせていただいているというような状況があります。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"別途質問しますが、今回はここで終わらせていただきます。その辺しっかり横串というか、課と連携しながら進めていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"１つ進めていくというお話も先ほどあったかと思うのですが、ぜひそういった好事例を参考にしながら進めていってほしいと求めました。〔「関連」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-167"},{"speaker":"いながき委員","kind":"質問","question":"これに関して、道路の脇に、今、２ｍしか歩道がとれなかったというお話でしたが、私、ここは歩道ではなく、敷地というふうに伺いました。その点をお尋ねします。","respondent":"多並都市開発課長","answer":"１点目の、先ほどのご説明の繰り返しになりますけれども、敷地内の歩道です。もう１点のビル風対策かというご質問ですけれども、これもご説明いたしましたけれども、緑化を一定程度しなければいけない。","id":"exchange-168"},{"speaker":"いながき委員","kind":"質問","question":"そうなると、歩道というよりは、やはり敷地内という理解で、このお隣のパルムと何とか、名前はごめんなさい、忘れてしまったのですけれども、その敷地内ということで、品川区が所持している歩道という意味ではないという理解でよろしいか尋ねました。","respondent":"多並都市開発課長","answer":"品川区が所有している土地ではなくて、武蔵小山パルム駅前地区という市街地再開発事業の区域内ですので、その持ち主の方々が共有でお持ちの土地、民間の土地になります。","id":"exchange-169"},{"speaker":"いながき委員","kind":"質問","question":"私がお伝えしたかったのは、道路が８ｍあるということであれば、通常、道路の脇に歩道がなければ危ないと思うのです。そもそも８ｍ道路をつくった際に、歩道がきちんとつくられていれば、そういったこともなかったのではないかと思うので、その見解を伺います。","respondent":"多並都市開発課長","answer":"再開発事業を進めるに当たりましては、その脇に歩道状空地を整備するなど、地区計画の整備の中で地区施設として定めて行うものです。都市計画、まちづくりの中でしっかり確認させていただきながら進めている事業、そういうふうにご理解いただければと思います。","id":"exchange-170"},{"speaker":"石田委員","kind":"質問・要望","question":"５０ページの特別区民税の増収について、増収している全体的なこの歳入は、区民や中小業者の暮らしの支援に使うことを求めて質問します。なぜ高額所得者が増えているのか、そして、なぜ５０代が多いのか、区はこの理由をどう考えていますか、伺います。","respondent":"提坂税務課長","answer":"昨日も申し上げましたが、もう一度説明しますけれども、その方たちが占める所得割税額が約４５％です。５０代の方が１年間で１,９００人ほど増えていまして、結局その方がよそから品川区を選んでいただいて転入してこられたのかと分析しています。","id":"exchange-171"},{"speaker":"石田委員","kind":"質問","question":"なぜ増えているのか、そういう所得の方が品川区に増えたということなのですよね。再開発が大きな要因だと思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"先ほどもご説明しましたが、駅前に駐車場があって、そういうものを皆さんで考えて共同で建物の計画をしていく事業であります。昔の課題があった地区をみんなで新しくしていこうということを目的としておりますので、そういう考えでご理解いただければと思います。","id":"exchange-172"},{"speaker":"石田委員","kind":"質問","question":"だから、要するに、再開発によって人口が増え、そういう再開発マンションを購入できる高額所得者が増えているということで、再開発によって増えていることも１つの要因として考えていいですかということをお聞きしたのです。","respondent":"多並都市開発課長","answer":"一般的には、個別で建て替えるところを、皆さんで一緒にその地区で整備していこうということで考えて建て替えると。皆さんとしては、その地区をよくしていこうと考える中で今につながっていると、そういうご理解をいただきたいと思ってあります。","id":"exchange-173"},{"speaker":"石田委員","kind":"質問・要望","question":"２３区トップクラスに税金投入もして進めることで、高額所得者も増える、次にいきます。２００万円から７００万円の方、そして２００万円以下の方、この３つの分類で分かれば教えていただきたいのですが。","respondent":"提坂税務課長","answer":"比率でよろしいですか。","id":"exchange-174"},{"speaker":"石田委員","kind":"質問・要望","question":"代表質問でも、物価高騰に苦しむ区民や中小事業者の実態をどう受け止めるかと伺いましたが、区民や中小企業を直撃し。なぜやらないのか伺いたいと思います。","respondent":"黒田財政課長","answer":"令和５年度の予算ですが、こちらは様々な事業の積み上げで歳出予算はできておりまして、そのために必要な財源ということで歳入予算を計上しています。ですので、しかも継続的にということは難しいところですので…","id":"exchange-175"},{"speaker":"石田委員","kind":"質問・要望","question":"認識している下で、区が直接やらずに、国や都の動向を注視することが理解できないのです。こういう悲鳴が上がっている中で、区がそこに独自に支援をすることが求められていると思いませんか、伺います。","respondent":"黒田財政課長","answer":"いわゆる福祉の予算もこの予算の中で組んでおりますので、そういった意味では、必要な財源を予算の中で計上しているです。令和２年度には、１年を通じた行政活動として、国や都の財源等も勘案しながら様々検討していきたいです。","id":"exchange-176"},{"speaker":"石田委員","kind":"質問・要望","question":"負担や不安を抱えているということも認識されているのですから、今回のこの歳入で過去最高なわけですから、国や都の動向待ちではなくて。区独自でやる気がないということなのか、そう思われても仕方がないと思うのですけれども、いかがか尋ねました。","respondent":"黒田財政課長","answer":"今回の令和５年度の歳入予算につきましては、いろいろ新しい施策も打ち出しています。これまで必要としている予算にプラスして、新しい区長の掲げる施策も入れて編成しているものですので、積極的に予算を編成しているものです。","id":"exchange-177"},{"speaker":"石田委員","kind":"質問","question":"だから、国や都がやっているからそれに乗るのではなくて、さらにそこに上乗せをしている、そういう支援策こそ必要ではないでしょうか。それによって増えた税収、それを暮らしの応援として区独自に使う考えはないということなのでしょうか、伺います。","respondent":"黒田財政課長","answer":"予算ですので、積極的に編成して、区の独自の政策を行っているものです。","id":"exchange-178"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１１１ページの防犯設備整備補助金、それから９１ページの新型コロナウイルスワクチン接種負担金についてお伺いしたいと思います。防犯カメラの設置経費とか、そういうことではないかと思いますけれども、お伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"１７４台の防犯カメラの設置ということで、令和３年度は予算を５,４００万円としておりましたが、実績増として増額しています。この使途につきましては、委員お話のとおり、防犯カメラが主でございまして、各商店街や町会等で設置をする防犯カメラの補助金となります。","id":"exchange-179"},{"speaker":"塚本委員","kind":"質問","question":"青天井ではないですけれども、つければつけるほどどんどん増えると、こういうような仕組みとして受け止めていいのかを１つお伺いしたいと思います。防犯カメラは、今後、防犯性を高めるためにどういうところにつけていくべきものと考えているのかもお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"これは、町会の皆様方が設置に前向きでやっていただけるのであるならば、できる限りの設置は私どもはしていきたいと考えているところです。設置の考え方ですが、そういったところにはしっかりとご説明をしてやっていきたいと、そのように思っているところです。","id":"exchange-180"},{"speaker":"塚本委員","kind":"質問・要望","question":"少し関連してお伺いしたいのですけれども、いろいろなまちに立っていらっしゃったり、動いているのをよく見かけます。どういうふうに、今、状況として捉えていらっしゃるのかお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"５台のパトロールカーがありますが、全てが出ているわけではありませんが、シフトを組みながら品川区内全域に回っているところです。そういった意味では、まもるっちの発報であるとか、不審者情報があるとか、そういったところに応じてパトロールの強化をして進めているところで…","id":"exchange-181"},{"speaker":"塚本委員","kind":"質問","question":"危ないことがあった場合にはというふうに伺うのですけれども、何でもかんでも１１０番というところに抵抗を感じていらっしゃる方もいらっしゃる。１１０番なのか、どうなのだという見解です、ここをお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"緊急に、今この場で何かが起こっている、すぐにでも対応してほしいという方は、遠慮なく１１０番という形でしていただければと思います。これは遠慮してしまって、♯９１１０につながったとしても、警察ですので、対応は当然緊急の対応とさせてはいただきます。","id":"exchange-182"},{"speaker":"塚本委員","kind":"質問","question":"時間がないので、最後に簡単にお伺いします。あるいはまたＶＲＳの登録などの運用、こういったことで今後の変更等が起こるような部分があるのか、その点だけお伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"我々のほうに自治体説明会がありまして、少なくとも令和５年度、令和６年３月３１日までは無料で接種が行われるというふうに聞いております。集団接種会場につきましては、今の予約状況を考えまして、現在は縮小して行っていくということで考えております。","id":"exchange-183"},{"speaker":"渡辺委員","kind":"質問","question":"１３１ページで都市防災不燃化促進事業、また、密集住宅等、その件から防災街区、要は、一番軸は特定整備路線について伺います。ただし、やはり課題なり、多くの方の深い理解があるということも承知していただきながら、区の役割を伺っていきます。","respondent":"鈴木都市計画課長","answer":"２９号線が約３４％、放射２号線が４４％、補助２８号線が７３％というような状況です。それから、事業期間ですが、延伸がなされておりまして、現在の事業期間が令和８年３月３１日というような状況です。","id":"exchange-184"},{"speaker":"渡辺委員","kind":"質問","question":"そういう意味で、品川区の役割と立ち位置の感じを教えてください。そして、先ほど言いました地域の声、懸念、そういったことをどのように把握しているか説明を求めました。","respondent":"大石木密整備推進課長","answer":"東京都からは、暫定活用の要望があった場合は、その活用の時期や具体的な内容に応じて案件ごとに検討するとの回答を得ているところです。道路建設予定地ですので、１つずつ東京都に働きかけていく、そういうことです。","id":"exchange-185"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう意味では、今後の動きの中でも、やはり道路予定地は大変幅も尺もある中で、特にという意味で要望させていただきたい。２点、この２点でぜひ抱負、決意を伺いたいと思います。","respondent":"大石木密整備推進課長","answer":"協議の都度、やはり閉鎖管理が原則と言われておりまして、なかなか難しい状況であることはあります。区としてどのような活用方法ができるのかということは、引き続き東京都の動向も注視しながら検討していきたいと思います。","id":"exchange-186"},{"speaker":"渡辺委員","kind":"質問","question":"ただ、これまで本当にそれぞれの職員の方、丁寧に対応していただいて、そして地域がすごくそこで勇気づけられている。すごくいい知恵も出てきていますので、このスタートを本当に感謝もしていますし、これからの期待を大きく持って質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":132533,"voices":447}},{"id":"r05-20230307-10","meetingId":"r05-cm03","date":"2023年3月7日","dateIso":"2023-03-07","committee":"議会運営委員会","time":"午後 ６時０９分～午後 ６時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"前回の議会運営委員会から、くにば議員の欠席の件について、少し状況が変わりましたので、ご報告させてほしいと求めました。本人と少しお話ししましたが、なかなか体調のほうで出席ができない状況であるということで、議長にもそのように説明させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5500#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1565,"voices":13}}]);
